import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Opportunity {
  id: string;
  title: string;
  type: string;
  value: number;
  daysAgo: number;
  user: {
    name: string;
    avatar: string;
  };
  tags: string[];
}

export enum NavItem {
  Resumos = 'Resumos',
  Clientes = 'Clientes',
  Processos = 'Processos',
  Documentos = 'Documentos',
  Produtos = 'Produtos',
