  isCollapsed: boolean;
  setIsCollapsed: (value: boolean) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeItem, onSelect, isCollapsed, setIsCollapsed }) => {
  return (
    <aside 
      className={`h-screen bg-[#1a0b36] text-white flex flex-col fixed left-0 top-0 z-50 shadow-2xl transition-all duration-300 ease-in-out ${
        isCollapsed ? 'w-20' : 'w-72'
