          <div className="bg-gradient-to-br from-violet-400 to-fuchsia-500 p-2 rounded-xl shadow-lg shadow-purple-500/20 shrink-0">
            <Hexagon className="text-white fill-current" size={24} />
          </div>
          {!isCollapsed && (
            <h1 className="text-2xl font-black tracking-tighter bg-clip-text text-transparent bg-gradient-to-r from-white to-purple-200 animate-in fade-in duration-500">
              V&C
            </h1>
          )}
        </div>

        {/* Toggle Button */}
        {!isCollapsed && (
