import React from 'react';
import { PIPELINE_STAGES } from '../constants';
import { Opportunity } from '../types';

interface FunnelChartProps {
  opportunities: Opportunity[];
}

const FunnelChart: React.FC<FunnelChartProps> = ({ opportunities }) => {
  const getStageCount = (stageId: string) => 
    opportunities.filter(o => o.stage === stageId).length;

  const data = PIPELINE_STAGES.map(stage => ({
    ...stage,
    count: getStageCount(stage.id)
  }));

  const maxCount = Math.max(...data.map(d => d.count), 1);

  return (
    <div className="bg-white border border-gray-100 rounded-3xl p-8 mb-10 shadow-sm">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h3 className="text-xl font-black text-gray-900 tracking-tight">Funil de Vendas</h3>
          <p className="text-sm text-gray-400 font-medium">Conversão volumétrica por estágio</p>
        </div>
      </div>

      <div className="flex flex-col gap-2">
        {data.map((item, index) => {
          const percentage = (item.count / maxCount) * 100;
          // Calculate a narrowing width for visual funnel effect
          const width = 100 - (index * 8); 

          return (
            <div key={item.id} className="group relative">
              <div className="flex items-center justify-between mb-1.5 px-2">
                <span className="text-[10px] font-black uppercase tracking-widest text-gray-500">{item.label}</span>
                <span className="text-xs font-bold text-gray-900">{item.count} ops</span>
              </div>
              <div className="h-10 bg-gray-50 rounded-xl overflow-hidden relative flex items-center justify-center">
                <div 
                  className={`h-full ${item.color} opacity-20 absolute left-0 top-0 transition-all duration-700`}
                  style={{ width: `${percentage}%` }}
                />
                <div 
                  className={`h-2 rounded-full ${item.color} shadow-sm transition-all duration-700`}
                  style={{ width: `${Math.max(percentage, 5)}%`, maxWidth: `${width}%` }}
                />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default FunnelChart;

