import React, { useState, useEffect } from 'react';
import { Save, X, DollarSign, Hash } from 'lucide-react';

interface SaleFormProps {
  onCancel: () => void;
  onSubmit: (sale: any) => void;
}

const SaleForm: React.FC<SaleFormProps> = ({ onCancel, onSubmit }) => {
  const [pedido, setPedido] = useState('');
  const [produto, setProduto] = useState<number>(0);
  const [assistencia, setAssistencia] = useState<number>(0);
  const [impermeabilizacao, setImpermeabilizacao] = useState<number>(0);
  const [total, setTotal] = useState(0);

  useEffect(() => {
    setTotal(produto + assistencia + impermeabilizacao);
  }, [produto, assistencia, impermeabilizacao]);

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(val);
  };

  const handleInputChange = (setter: React.Dispatch<React.SetStateAction<number>>, value: string) => {
    const numericValue = parseFloat(value.replace(/[^\d]/g, '')) / 100;
    setter(isNaN(numericValue) ? 0 : numericValue);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({
      numeroPedido: pedido,
      valorProduto: produto,
      valorAssistencia: assistencia,
      valorImpermeabilizacao: impermeabilizacao,
      total: total,
    });
  };

  return (
    <div className="animate-in fade-in slide-in-from-bottom-8 duration-500 max-w-4xl mx-auto">
      <div className="bg-white rounded-[2.5rem] shadow-2xl overflow-hidden border border-gray-100">
        <div className="bg-[#1a0b36] p-8 md:p-12 text-white">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-3xl font-black tracking-tighter">Lançar Nova Venda</h2>
            <button onClick={onCancel} className="p-2 hover:bg-white/10 rounded-full transition-colors">
              <X size={24} />
            </button>
          </div>
          <p className="text-purple-200/70 font-medium">Preencha os dados do pedido abaixo para registrar no sistema V&C.</p>
        </div>

        <form onSubmit={handleSave} className="p-8 md:p-12 space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {/* Numero do Pedido */}
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-purple-600 ml-1">Número do Pedido</label>
              <div className="relative group">
                <Hash className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-purple-500 transition-colors" size={20} />
                <input
                  type="text"
                  required
                  value={pedido}
                  onChange={(e) => setPedido(e.target.value)}
                  placeholder="Ex: #99234"
                  className="w-full pl-12 pr-6 py-4 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-4 focus:ring-purple-500/10 focus:bg-white focus:border-purple-200 transition-all font-bold text-gray-800"
                />
              </div>
            </div>

            {/* Valor Produto */}
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-purple-600 ml-1">Valor do Produto</label>
              <div className="relative group">
                <DollarSign className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-300 group-focus-within:text-purple-500 transition-colors" size={20} />
                <input
                  type="text"
                  required
                  value={produto === 0 ? "" : formatCurrency(produto)}
                  onChange={(e) => handleInputChange(setProduto, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full pl-12 pr-6 py-4 bg-gray-50 border border-gray-200 rounded-2xl focus:outline-none focus:ring-4 focus:ring-purple-500/10 focus:bg-white focus:border-purple-200 transition-all font-bold text-gray-800"
                />
              </div>
            </div>

            {/* Valor Assistência */}
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-purple-600 ml-1">Assistência</label>
              <div className="relative group">
