import React, { useState, useEffect } from 'react';
import { Save, X, Terminal, Target, Database, Droplets, CreditCard } from 'lucide-react';

interface SaleFormProps {
  onCancel: () => void;
  onSubmit: (sale: any) => void;
}

const SaleForm: React.FC<SaleFormProps> = ({ onCancel, onSubmit }) => {
  const [pedido, setPedido] = useState('');
  const [produto, setProduto] = useState<number>(0);
  const [assistencia, setAssistencia] = useState<number>(0);
  const [impermeabilizacao, setImpermeabilizacao] = useState<number>(0);
  const [total, setTotal] = useState(0);

  useEffect(() => {
    setTotal(produto + assistencia + impermeabilizacao);
  }, [produto, assistencia, impermeabilizacao]);

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(val);
  };

  const handleInputChange = (setter: React.Dispatch<React.SetStateAction<number>>, value: string) => {
    const numericValue = parseFloat(value.replace(/[^\d]/g, '')) / 100;
    setter(isNaN(numericValue) ? 0 : numericValue);
  };

  return (
    <div className="max-w-5xl mx-auto py-6 animate-in zoom-in-95 duration-500">
      <div className="glass rounded-[3rem] overflow-hidden shadow-[0_0_50px_rgba(0,0,0,0.5)] border border-white/10 relative">
        {/* Animated background element */}
        <div className="absolute top-0 right-0 w-96 h-96 bg-cyan-500/10 blur-[100px] rounded-full -mr-48 -mt-48"></div>

        <div className="p-10 md:p-14 relative z-10">
          <div className="flex items-center justify-between mb-12">
            <div>
              <div className="flex items-center gap-3 text-cyan-400 mb-2">
                <Terminal size={20} className="animate-pulse" />
                <span className="text-[10px] font-black uppercase tracking-[0.4em]">Operational Terminal v4.0</span>
              </div>
              <h2 className="text-4xl font-extrabold text-white tracking-tighter">Lançamento de Dados</h2>
            </div>
            <button onClick={onCancel} className="bg-white/5 p-4 rounded-2xl text-slate-400 hover:text-white hover:bg-rose-500/20 transition-all">
              <X size={24} />
            </button>
          </div>

          <form className="grid grid-cols-1 md:grid-cols-2 gap-10" onSubmit={(e) => {
            e.preventDefault();
            onSubmit({ pedido, produto, assistencia, impermeabilizacao, total });
          }}>
            {/* Input Groups */}
            <div className="space-y-8">
              <div className="space-y-3 group">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                  <Database size={14} className="text-cyan-400" /> ID do Pedido
                </label>
                <input
                  type="text"
                  required
                  value={pedido}
                  onChange={(e) => setPedido(e.target.value)}
                  placeholder="EX-99234X"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl focus:outline-none focus:ring-2 focus:ring-cyan-500/50 focus:bg-white/10 transition-all text-lg font-bold text-white mono"
                />
              </div>

              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                  <Target size={14} className="text-violet-400" /> Valor do Produto
                </label>
                <input
                  type="text"
                  required
                  value={produto === 0 ? "" : formatCurrency(produto)}
                  onChange={(e) => handleInputChange(setProduto, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl focus:outline-none focus:ring-2 focus:ring-violet-500/50 focus:bg-white/10 transition-all text-lg font-bold text-white mono"
                />
              </div>
            </div>

            <div className="space-y-8">
              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                  <CreditCard size={14} className="text-blue-400" /> Assistência Técnica
                </label>
                <input
                  type="text"
                  required
                  value={assistencia === 0 ? "" : formatCurrency(assistencia)}
                  onChange={(e) => handleInputChange(setAssistencia, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl focus:outline-none focus:ring-2 focus:ring-blue-500/50 focus:bg-white/10 transition-all text-lg font-bold text-white mono"
                />
              </div>

              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest ml-1 flex items-center gap-2">
                  <Droplets size={14} className="text-fuchsia-400" /> Impermeabilização
                </label>
                <input
                  type="text"
                  required
                  value={impermeabilizacao === 0 ? "" : formatCurrency(impermeabilizacao)}
                  onChange={(e) => handleInputChange(setImpermeabilizacao, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl focus:outline-none focus:ring-2 focus:ring-fuchsia-500/50 focus:bg-white/10 transition-all text-lg font-bold text-white mono"
                />
              </div>
            </div>

            {/* Consolidado */}
            <div className="md:col-span-2 mt-8">
              <div className="p-1 rounded-[2.5rem] bg-gradient-to-r from-cyan-500 via-violet-600 to-fuchsia-500">
                <div className="bg-[#0a051a] rounded-[2.3rem] p-10 flex flex-col md:flex-row items-center justify-between gap-6">
                  <div>
                    <span className="text-[10px] font-black uppercase tracking-[0.5em] text-cyan-400 mb-2 block">Total Consolidado</span>
                    <h3 className="text-2xl font-bold text-white">Montante Operacional</h3>
                  </div>
                  <div className="text-5xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-violet-400 mono tracking-tighter">
                    {formatCurrency(total)}
                  </div>
                </div>
              </div>
            </div>

            <div className="md:col-span-2 flex gap-6 pt-10">
              <button type="submit" className="flex-1 bg-white text-black py-6 rounded-3xl font-black text-xl hover:scale-[1.02] active:scale-[0.98] transition-all shadow-[0_0_30px_rgba(255,255,255,0.15)] flex items-center justify-center gap-4">
                <Save size={24} /> Registrar Transação
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default SaleForm;

