import React from 'react';
import { PIPELINE_STAGES } from '../constants';
import { Opportunity } from '../types';

interface FunnelChartProps {
  opportunities: Opportunity[];
}

const FunnelChart: React.FC<FunnelChartProps> = ({ opportunities }) => {
  const getStageCount = (stageId: string) => 
    opportunities.filter(o => o.stage === stageId).length;

  const data = PIPELINE_STAGES.map(stage => ({
    ...stage,
    count: getStageCount(stage.id)
  }));

  const maxCount = Math.max(...data.map(d => d.count), 1);

  return (
    <div className="glass rounded-[2.5rem] p-8 mb-8 border border-white/5">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h3 className="text-lg font-black text-white tracking-tight">Fluxo de Conversão</h3>
          <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">Métrica de Eficiência por Estágio</p>
        </div>
      </div>

      <div className="flex flex-col gap-3">
        {data.map((item, index) => {
          const percentage = (item.count / maxCount) * 100;
          const width = 100 - (index * 6); 

          return (
            <div key={item.id} className="group relative">
              <div className="flex items-center justify-between mb-1.5 px-1">
                <span className="text-[9px] font-black uppercase tracking-widest text-slate-500">{item.label}</span>
                <span className="text-[10px] font-bold text-white mono">{item.count} OPS</span>
              </div>
              <div className="h-8 bg-white/5 rounded-xl overflow-hidden relative flex items-center justify-center border border-white/5">
                <div 
                  className={`h-full ${item.color} opacity-10 absolute left-0 top-0 transition-all duration-700`}
                  style={{ width: `${percentage}%` }}
                />
                <div 
                  className={`h-1 rounded-full ${item.color} shadow-[0_0_10px_rgba(255,255,255,0.2)] transition-all duration-700`}
                  style={{ width: `${Math.max(percentage, 5)}%`, maxWidth: `${width}%` }}
                />
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default FunnelChart;

