import React, { useState, useEffect, useRef } from 'react';
import { Save, X, Terminal, Target, Database, CheckSquare, Square } from 'lucide-react';

interface SaleFormProps {
  onCancel: () => void;
  onSubmit: (sale: any) => void;
}

const BONUS_VALUES = {
  montagem: 10,
  lavagem: 40,
  almofada: 10,
  pes_guarda_roupa: 7,
  impermeabilizacao_bonus: 40
};

const SaleForm: React.FC<SaleFormProps> = ({ onCancel, onSubmit }) => {
  const [pedido, setPedido] = useState('');
  const [produto, setProduto] = useState<number>(0);
  const [assistencia, setAssistencia] = useState<number>(0);
  const [impermeabilizacao, setImpermeabilizacao] = useState<number>(0);
  const [total, setTotal] = useState(0);

  // Estados dos Bônus
  const [extras, setExtras] = useState({
    montagem: false,
    lavagem: false,
    almofada: false,
    pes_guarda_roupa: false,
    impermeabilizacao_bonus: false
  });

  const firstInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setTotal(produto + assistencia + impermeabilizacao);
  }, [produto, assistencia, impermeabilizacao]);

  useEffect(() => {
    if (firstInputRef.current) {
      firstInputRef.current.focus();
    }
  }, []);

  const calculateBonus = () => {
    let bonusTotal = 0;
    if (extras.montagem) bonusTotal += BONUS_VALUES.montagem;
    if (extras.lavagem) bonusTotal += BONUS_VALUES.lavagem;
    if (extras.almofada) bonusTotal += BONUS_VALUES.almofada;
    if (extras.pes_guarda_roupa) bonusTotal += BONUS_VALUES.pes_guarda_roupa;
    if (extras.impermeabilizacao_bonus) bonusTotal += BONUS_VALUES.impermeabilizacao_bonus;
    return bonusTotal;
  };

  const getSelectedLabels = () => {
    const labels: string[] = [];
    if (extras.montagem) labels.push("Montagem");
    if (extras.lavagem) labels.push("Lavagem");
    if (extras.almofada) labels.push("Almofada");
    if (extras.pes_guarda_roupa) labels.push("Pés G-Roupa");
    if (extras.impermeabilizacao_bonus) labels.push("Impermeab.");
    return labels;
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(val);
  };

  const handleInputChange = (setter: React.Dispatch<React.SetStateAction<number>>, value: string) => {
    const numericValue = parseFloat(value.replace(/[^\d]/g, '')) / 100;
    setter(isNaN(numericValue) ? 0 : numericValue);
  };

  const toggleExtra = (key: keyof typeof extras) => {
    setExtras(prev => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <div className="w-full max-w-4xl mx-auto animate-in zoom-in-95 duration-500 pb-20">
      <div className="glass rounded-[3rem] overflow-hidden shadow-[0_0_80px_rgba(0,0,0,0.6)] border border-white/10 relative">
        <div className="absolute top-0 right-0 w-96 h-96 bg-cyan-500/5 blur-[100px] rounded-full -mr-48 -mt-48"></div>

        <div className="p-6 md:p-12 relative z-10">
          <div className="flex items-center justify-between mb-10">
            <div>
              <div className="flex items-center gap-3 text-cyan-400 mb-2">
                <Terminal size={18} className="animate-pulse" />
                <span className="text-[9px] font-black uppercase tracking-[0.4em]">Módulo Quantum v4.1</span>
              </div>
              <h2 className="text-2xl md:text-3xl font-extrabold text-white tracking-tighter uppercase">Novo Lançamento</h2>
            </div>
            <button onClick={onCancel} className="bg-white/5 p-3 rounded-xl text-slate-400 hover:text-white transition-all">
              <X size={20} />
            </button>
          </div>

          <form className="space-y-8" onSubmit={(e) => {
            e.preventDefault();
            onSubmit({ 
              pedido, 
              produto, 
              assistencia, 
              impermeabilizacao, 
              total,
              bonusTotal: calculateBonus(),
              servicosExtras: getSelectedLabels()
            });
          }}>
            {/* Campos Principais */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">ID Pedido</label>
                <input
                  ref={firstInputRef}
                  type="text"
                  required
                  autoCapitalize="characters"
                  value={pedido}
                  onChange={(e) => setPedido(e.target.value.toUpperCase())}
                  placeholder="DIGITE O CÓDIGO"
                  className="w-full bg-white/5 border border-white/10 p-4 rounded-xl focus:ring-1 focus:ring-cyan-500/50 transition-all text-white mono font-bold"
                />
              </div>

              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Valor Produto</label>
                <input
                  type="text"
                  inputMode="decimal"
                  required
                  value={produto === 0 ? "" : formatCurrency(produto)}
                  onChange={(e) => handleInputChange(setProduto, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-4 rounded-xl focus:ring-1 focus:ring-violet-500/50 transition-all text-white mono font-bold"
                />
              </div>
            </div>

            {/* Serviços Internos (Valores) */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Assistência</label>
                <input
                  type="text"
                  inputMode="decimal"
                  value={assistencia === 0 ? "" : formatCurrency(assistencia)}
                  onChange={(e) => handleInputChange(setAssistencia, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-4 rounded-xl focus:ring-1 focus:ring-blue-500/50 transition-all text-white mono"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Impermeabilização (Cliente)</label>
                <input
                  type="text"
                  inputMode="decimal"
                  value={impermeabilizacao === 0 ? "" : formatCurrency(impermeabilizacao)}
                  onChange={(e) => handleInputChange(setImpermeabilizacao, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-4 rounded-xl focus:ring-1 focus:ring-fuchsia-500/50 transition-all text-white mono"
                />
              </div>
            </div>

            {/* Seção de Bônus (Checkboxes) - Compacta */}
            <div className="bg-white/5 border border-white/5 p-6 rounded-3xl">
              <div className="flex items-center gap-3 mb-4">
                <CheckSquare size={16} className="text-emerald-400" />
                <h4 className="text-[10px] font-black text-white uppercase tracking-[0.3em]">Serviços com Bônus (Fixo Vendedor)</h4>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-3">
                {[
                  { id: 'montagem', label: 'Montagem', value: 'R$10' },
                  { id: 'lavagem', label: 'Lavagem', value: 'R$40' },
                  { id: 'almofada', label: 'Almofada', value: 'R$10' },
                  { id: 'pes_guarda_roupa', label: 'Pés G-R', value: 'R$7' },
                  { id: 'impermeabilizacao_bonus', label: 'Impermeab.', value: 'R$40' }
                ].map((item) => (
                  <button
                    key={item.id}
                    type="button"
                    onClick={() => toggleExtra(item.id as keyof typeof extras)}
                    className={`flex items-center justify-between p-3 rounded-xl border transition-all ${
                      extras[item.id as keyof typeof extras]
                      ? 'bg-emerald-500/10 border-emerald-500/40 text-emerald-400'
                      : 'bg-white/5 border-white/5 text-slate-500 hover:border-white/20'
                    }`}
                  >
                    <div className="flex flex-col items-start">
                      <span className="text-[10px] font-bold uppercase tracking-tighter leading-none mb-1">{item.label}</span>
                      <span className="text-[8px] mono opacity-60">{item.value}</span>
                    </div>
                    {extras[item.id as keyof typeof extras] ? <CheckSquare size={14} /> : <Square size={14} />}
                  </button>
                ))}
              </div>
            </div>

            {/* Rodapé de Totais */}
            <div className="md:col-span-2">
              <div className="p-[1px] rounded-3xl bg-gradient-to-r from-cyan-500 via-violet-600 to-fuchsia-500 shadow-2xl">
                <div className="bg-[#0a051a] rounded-[1.8rem] p-6 flex flex-col md:flex-row items-center justify-between gap-6">
                  <div className="flex flex-col items-center md:items-start">
                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-cyan-400 mb-1">Pagamento Cliente</span>
                    <div className="text-2xl md:text-3xl font-black text-white mono">{formatCurrency(total)}</div>
                  </div>
                  <div className="w-px h-10 bg-white/10 hidden md:block"></div>
                  <div className="flex flex-col items-center md:items-end">
                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-emerald-400 mb-1">Bônus Vendedor</span>
                    <div className="text-2xl md:text-3xl font-black text-emerald-400 mono">{formatCurrency(calculateBonus())}</div>
                  </div>
                </div>
              </div>
            </div>

            <button type="submit" className="w-full bg-white text-black py-5 rounded-2xl font-black text-sm hover:scale-[1.01] active:scale-[0.99] transition-all flex items-center justify-center gap-3">
              <Save size={20} /> FINALIZAR E GRAVAR PEDIDO
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

