               <div className="bg-white/5 p-5 rounded-2xl border border-white/5">
                  <div className="text-[9px] font-black text-slate-500 uppercase mb-2">Total Vendas</div>
                  <div className="text-xl font-black text-white mono">{formatBRL(totalGlobal)}</div>
               </div>
               <div className="bg-white/5 p-5 rounded-2xl border border-white/5">
                  <div className="text-[9px] font-black text-emerald-500 uppercase mb-2">Total Bônus</div>
                  <div className="text-xl font-black text-emerald-400 mono">{formatBRL(totalBonusGlobal)}</div>
               </div>
               <div className="bg-white/5 p-5 rounded-2xl border border-white/5">
                  <div className="text-[9px] font-black text-cyan-500 uppercase mb-2">Pedidos</div>
                  <div className="text-xl font-black text-cyan-400 mono">{savedSales.length}</div>
               </div>
               <div className="bg-white/5 p-5 rounded-2xl border border-white/5">
                  <div className="text-[9px] font-black text-violet-500 uppercase mb-2">Ganhos Totais</div>
                  <div className="text-xl font-black text-violet-400 mono">{formatBRL(totalGlobal + totalBonusGlobal)}</div>
               </div>
            </div>

            {viewMode === 'list' ? (
              <div className="space-y-4">
                {MOCK_OPPORTUNITIES.map(op => <OpportunityCard key={op.id} opportunity={op} />)}
              </div>
