  };

  return (
    <div className="min-h-screen flex selection:bg-cyan-400 selection:text-black bg-[#05020a] overflow-hidden">
      {/* Sidebar */}
      <div className={`transition-all duration-500 z-50 flex-shrink-0 ${isSidebarCollapsed ? 'w-24' : 'w-64'}`}>
        <Sidebar isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed} activeItem={activeNav} onSelect={setActiveNav} />
