import React, { useState, useEffect, useRef } from 'react';
import { Save, X, Terminal, CheckSquare, Square } from 'lucide-react';

interface SaleFormProps {
  onCancel: () => void;
  onSubmit: (sale: any) => void;
}

const BONUS_VALUES = {
  montagem: 10,
  lavagem: 40,
  almofada: 10,
  pes_guarda_roupa: 7,
  impermeabilizacao_bonus: 40
};

const SaleForm: React.FC<SaleFormProps> = ({ onCancel, onSubmit }) => {
  const [pedido, setPedido] = useState('');
  const [produto, setProduto] = useState<number>(0);
  const [assistencia, setAssistencia] = useState<number>(0);
  const [impermeabilizacao, setImpermeabilizacao] = useState<number>(0);
  const [total, setTotal] = useState(0);

  const [extras, setExtras] = useState({
    montagem: false,
    lavagem: false,
    almofada: false,
    pes_guarda_roupa: false,
    impermeabilizacao_bonus: false
  });

  const firstInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setTotal(produto + assistencia + impermeabilizacao);
  }, [produto, assistencia, impermeabilizacao]);

  useEffect(() => {
    // Foca imediatamente no número do pedido para agilizar a entrada via teclado
    if (firstInputRef.current) firstInputRef.current.focus();
  }, []);

  const calculateBonus = () => {
    let bonusTotal = 0;
    Object.keys(extras).forEach(key => {
      if (extras[key as keyof typeof extras]) {
        bonusTotal += BONUS_VALUES[key as keyof typeof BONUS_VALUES];
      }
    });
    return bonusTotal;
  };

  const getSelectedLabels = () => {
    const labels: string[] = [];
    if (extras.montagem) labels.push("Montagem");
    if (extras.lavagem) labels.push("Lavagem");
    if (extras.almofada) labels.push("Almofada");
    if (extras.pes_guarda_roupa) labels.push("Pés G-R");
    if (extras.impermeabilizacao_bonus) labels.push("Impermeab.");
    return labels;
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
  };

  const handleInputChange = (setter: React.Dispatch<React.SetStateAction<number>>, value: string) => {
    const numericValue = parseFloat(value.replace(/[^\d]/g, '')) / 100;
    setter(isNaN(numericValue) ? 0 : numericValue);
  };

  return (
    <div className="w-full max-w-4xl mx-auto pb-10">
      <div className="glass rounded-[2.5rem] overflow-hidden border border-white/10">
        <div className="p-6 md:p-10">
          <div className="flex items-center justify-between mb-8">
            <div>
              <div className="flex items-center gap-2 text-cyan-400 mb-1">
                <Terminal size={14} />
                <span className="text-[8px] font-black uppercase tracking-[0.3em]">Quantum Terminal</span>
              </div>
              <h2 className="text-xl font-black text-white uppercase tracking-tighter">Lançamento de Pedido</h2>
            </div>
            <button onClick={onCancel} className="text-slate-500 hover:text-white"><X size={24} /></button>
          </div>

          <form className="space-y-6" onSubmit={(e) => {
            e.preventDefault();
            onSubmit({ pedido, produto, assistencia, impermeabilizacao, total, bonusTotal: calculateBonus(), servicosExtras: getSelectedLabels() });
          }}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1">Nº do Pedido</label>
                <input
                  ref={firstInputRef}
                  type="text"
                  required
                  autoFocus
                  autoCapitalize="characters"
                  value={pedido}
                  onChange={(e) => setPedido(e.target.value.toUpperCase())}
                  placeholder="EX: 12345X"
                  className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl text-white font-bold mono focus:ring-1 focus:ring-cyan-500 transition-all outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1">Valor do Produto</label>
                <input
                  type="text"
                  inputMode="decimal"
                  required
                  value={produto === 0 ? "" : formatCurrency(produto)}
                  onChange={(e) => handleInputChange(setProduto, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl text-white font-bold mono focus:ring-1 focus:ring-violet-500 transition-all outline-none"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1">Assistência</label>
                <input
                  type="text"
                  inputMode="decimal"
                  value={assistencia === 0 ? "" : formatCurrency(assistencia)}
                  onChange={(e) => handleInputChange(setAssistencia, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl text-white font-bold mono outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-1">Impermeabilização (Cliente)</label>
                <input
                  type="text"
                  inputMode="decimal"
                  value={impermeabilizacao === 0 ? "" : formatCurrency(impermeabilizacao)}
                  onChange={(e) => handleInputChange(setImpermeabilizacao, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-4 rounded-2xl text-white font-bold mono outline-none"
                />
              </div>
            </div>

            {/* Bônus Vendedor - Grade Compacta para Mobile */}
            <div className="bg-white/5 p-5 rounded-[2rem] border border-white/5">
