import React, { useState, useEffect, useRef } from 'react';
import { Save, X, Terminal, CheckSquare, Square, Award, Target } from 'lucide-react';

interface SaleFormProps {
  onCancel: () => void;
  onSubmit: (sale: any) => void;
}

// Valores de bônus restaurados conforme o print solicitado
const BONUS_VALUES = {
  montagem: 40,
  lavagem: 40,
  almofada: 7,
  pes_guarda_roupa: 7,
  impermeabilizacao_bonus: 40
};

const SaleForm: React.FC<SaleFormProps> = ({ onCancel, onSubmit }) => {
  const [pedido, setPedido] = useState('');
  const [produto, setProduto] = useState<number>(0);
  const [assistencia, setAssistencia] = useState<number>(0);
  const [impermeabilizacao, setImpermeabilizacao] = useState<number>(0);
  const [total, setTotal] = useState(0);

  const [extras, setExtras] = useState({
    montagem: false,
    lavagem: false,
    almofada: false,
    pes_guarda_roupa: false,
    impermeabilizacao_bonus: false
  });

  const firstInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // O total que o cliente paga (não inclui os bônus do vendedor)
    setTotal(produto + assistencia + impermeabilizacao);
  }, [produto, assistencia, impermeabilizacao]);

  useEffect(() => {
    if (firstInputRef.current) firstInputRef.current.focus();
  }, []);

  const calculateBonus = () => {
    let bonusTotal = 0;
    Object.keys(extras).forEach(key => {
      if (extras[key as keyof typeof extras]) {
        bonusTotal += BONUS_VALUES[key as keyof typeof BONUS_VALUES];
      }
    });
    return bonusTotal;
  };

  const getSelectedLabels = () => {
    const labels: string[] = [];
    if (extras.montagem) labels.push("Montagem");
    if (extras.lavagem) labels.push("Lavagem");
    if (extras.almofada) labels.push("Almofada");
    if (extras.pes_guarda_roupa) labels.push("Pés G-R");
    if (extras.impermeabilizacao_bonus) labels.push("Impermeab.");
    return labels;
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
  };

  const handleInputChange = (setter: React.Dispatch<React.SetStateAction<number>>, value: string) => {
    const numericValue = parseFloat(value.replace(/[^\d]/g, '')) / 100;
    setter(isNaN(numericValue) ? 0 : numericValue);
  };

  return (
    <div className="w-full max-w-4xl mx-auto pb-20 animate-in zoom-in-95 duration-500">
      <div className="glass rounded-[3rem] overflow-hidden border border-white/10 shadow-[0_0_80px_rgba(0,0,0,0.6)]">
        <div className="p-8 md:p-12">
          <div className="flex items-center justify-between mb-10">
            <div>
              <div className="flex items-center gap-3 text-cyan-400 mb-2">
                <Terminal size={18} className="animate-pulse" />
                <span className="text-[9px] font-black uppercase tracking-[0.4em]">V&C Quantum Module</span>
              </div>
              <h2 className="text-3xl font-black text-white uppercase tracking-tighter">Lançar Nova Venda</h2>
            </div>
            <button onClick={onCancel} className="bg-white/5 p-4 rounded-2xl text-slate-500 hover:text-white transition-all">
              <X size={24} />
            </button>
          </div>

          <form className="space-y-8" onSubmit={(e) => {
            e.preventDefault();
            onSubmit({ pedido, produto, assistencia, impermeabilizacao, total, bonusTotal: calculateBonus(), servicosExtras: getSelectedLabels() });
          }}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">ID do Pedido</label>
                <input
                  ref={firstInputRef}
                  type="text"
                  required
                  autoCapitalize="characters"
                  value={pedido}
                  onChange={(e) => setPedido(e.target.value.toUpperCase())}
                  placeholder="DIGITE O CÓDIGO"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl text-white font-black mono text-xl focus:ring-1 focus:ring-cyan-500 transition-all outline-none"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Valor do Produto</label>
                <input
                  type="text"
                  inputMode="decimal"
                  required
                  value={produto === 0 ? "" : formatCurrency(produto)}
                  onChange={(e) => handleInputChange(setProduto, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl text-white font-black mono text-xl focus:ring-1 focus:ring-violet-500 transition-all outline-none"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Assistência</label>
                <input
                  type="text"
                  inputMode="decimal"
                  value={assistencia === 0 ? "" : formatCurrency(assistencia)}
                  onChange={(e) => handleInputChange(setAssistencia, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl text-white font-bold mono outline-none"
                />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Impermeabilização (Cliente)</label>
                <input
                  type="text"
                  inputMode="decimal"
                  value={impermeabilizacao === 0 ? "" : formatCurrency(impermeabilizacao)}
                  onChange={(e) => handleInputChange(setImpermeabilizacao, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl text-white font-bold mono outline-none"
                />
              </div>
            </div>

            {/* Bônus Operacionais - Versão Restaurada */}
            <div className="bg-white/5 p-8 rounded-[2.5rem] border border-white/5">
              <div className="flex items-center gap-3 mb-6">
                <Award size={18} className="text-emerald-400" />
                <h4 className="text-[11px] font-black text-white uppercase tracking-[0.3em]">Bônus Operacionais (Checkboxes)</h4>
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
                {[
                  { id: 'montagem', label: 'Montagem', val: 'R$40' },
                  { id: 'lavagem', label: 'Lavagem', val: 'R$40' },
                  { id: 'almofada', label: 'Almofada', val: 'R$7' },
                  { id: 'pes_guarda_roupa', label: 'Pés G-R', val: 'R$7' },
                  { id: 'impermeabilizacao_bonus', label: 'Impermeab.', val: 'R$40' }
                ].map((item) => (
                  <button
                    key={item.id}
                    type="button"
                    onClick={() => setExtras(prev => ({...prev, [item.id]: !prev[item.id as keyof typeof extras]}))}
                    className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all duration-300 ${
                      extras[item.id as keyof typeof extras] 
                      ? 'bg-emerald-500 text-black border-emerald-400 shadow-[0_0_20px_rgba(16,185,129,0.4)]' 
                      : 'bg-white/5 border-white/5 text-slate-600 hover:border-white/20'
                    }`}
                  >
                    <span className="text-[10px] font-black uppercase mb-1">{item.label}</span>
                    <span className={`text-[9px] mono font-bold ${extras[item.id as keyof typeof extras] ? 'text-black' : 'opacity-40'}`}>{item.val}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="bg-[#0a051a] rounded-[2.5rem] p-8 flex flex-col md:flex-row items-center justify-between gap-8 border border-white/5 shadow-2xl">
               <div className="text-center md:text-left">
                  <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Total Pago (Cliente)</span>
                  <div className="text-3xl font-black text-white mono">{formatCurrency(total)}</div>
               </div>
               <div className="w-px h-12 bg-white/10 hidden md:block"></div>
               <div className="text-center md:text-right">
                  <span className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Seu Bônus Extra</span>
                  <div className="text-3xl font-black text-emerald-400 mono">+{formatCurrency(calculateBonus())}</div>
               </div>
            </div>

            <button type="submit" className="w-full bg-white text-black py-6 rounded-[2rem] font-black text-sm uppercase tracking-[0.2em] hover:bg-cyan-400 transition-all hover:scale-[1.02]">
              Finalizar Lançamento
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

