import React, { useState, useEffect, useRef } from 'react';
import { X, Terminal, Award, ChevronRight } from 'lucide-react';

interface SaleFormProps {
  onCancel: () => void;
  onSubmit: (sale: any) => void;
}

const BONUS_VALUES = {
  montagem: 40,
  lavagem: 40,
  almofada: 7,
  pes_guarda_roupa: 7,
  impermeabilizacao_bonus: 40
};

const SaleForm: React.FC<SaleFormProps> = ({ onCancel, onSubmit }) => {
  const [pedido, setPedido] = useState('');
  const [produto, setProduto] = useState<number>(0);
  const [assistencia, setAssistencia] = useState<number>(0);
  const [impermeabilizacao, setImpermeabilizacao] = useState<number>(0);
  const [total, setTotal] = useState(0);

  const [extras, setExtras] = useState({
    montagem: false,
    lavagem: false,
    almofada: false,
    pes_guarda_roupa: false,
    impermeabilizacao_bonus: false
  });

  const firstInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setTotal(produto + assistencia + impermeabilizacao);
  }, [produto, assistencia, impermeabilizacao]);

  useEffect(() => {
    if (firstInputRef.current) firstInputRef.current.focus();
  }, []);

  const calculateBonus = () => {
    let bonusTotal = 0;
    Object.keys(extras).forEach(key => {
      if (extras[key as keyof typeof extras]) {
        bonusTotal += BONUS_VALUES[key as keyof typeof BONUS_VALUES];
      }
    });
    return bonusTotal;
  };

  const getSelectedLabels = () => {
    const labels: string[] = [];
    if (extras.montagem) labels.push("Montagem");
    if (extras.lavagem) labels.push("Lavagem");
    if (extras.almofada) labels.push("Almofada");
    if (extras.pes_guarda_roupa) labels.push("Pés G-R");
    if (extras.impermeabilizacao_bonus) labels.push("Impermeab.");
    return labels;
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
  };

  const handleInputChange = (setter: React.Dispatch<React.SetStateAction<number>>, value: string) => {
    const numericValue = parseFloat(value.replace(/[^\d]/g, '')) / 100;
    setter(isNaN(numericValue) ? 0 : numericValue);
  };

  return (
    <div className="w-full">
      <div className="glass rounded-[2.5rem] p-8 md:p-12 relative border-white/5">
        <div className="flex items-center justify-between mb-12">
          <div>
            <div className="flex items-center gap-2 text-cyan-400 mb-2">
              <Terminal size={14} className="animate-pulse" />
              <span className="text-[9px] font-black uppercase tracking-[0.4em]">Quantum Input Module</span>
            </div>
            <h2 className="text-2xl font-black text-white uppercase tracking-tighter">Registrar Transação</h2>
          </div>
          <button onClick={onCancel} className="bg-white/5 p-3 rounded-xl text-slate-500 hover:text-white transition-all">
            <X size={20} />
          </button>
        </div>

        <form className="space-y-8" onSubmit={(e) => {
          e.preventDefault();
          onSubmit({ pedido, produto, assistencia, impermeabilizacao, total, bonusTotal: calculateBonus(), servicosExtras: getSelectedLabels() });
        }}>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-[9px] font-black text-slate-600 uppercase tracking-widest ml-1">ID do Pedido</label>
              <input
                ref={firstInputRef}
                type="text"
                required
                autoCapitalize="characters"
                value={pedido}
                onChange={(e) => setPedido(e.target.value.toUpperCase())}
                placeholder="EX: 9988X"
                className="w-full bg-white/[0.03] border border-white/5 p-4 rounded-xl text-white font-black mono text-lg outline-none transition-all"
              />
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-slate-600 uppercase tracking-widest ml-1">Valor do Produto</label>
              <input
                type="text"
                inputMode="decimal"
                required
                value={produto === 0 ? "" : formatCurrency(produto)}
                onChange={(e) => handleInputChange(setProduto, e.target.value)}
                placeholder="R$ 0,00"
                className="w-full bg-white/[0.03] border border-white/5 p-4 rounded-xl text-white font-black mono text-lg outline-none transition-all"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-[9px] font-black text-slate-600 uppercase tracking-widest ml-1">Assistência Técnica</label>
              <input
                type="text"
                inputMode="decimal"
                value={assistencia === 0 ? "" : formatCurrency(assistencia)}
                onChange={(e) => handleInputChange(setAssistencia, e.target.value)}
                placeholder="R$ 0,00"
                className="w-full bg-white/[0.03] border border-white/5 p-4 rounded-xl text-white font-bold mono outline-none"
              />
            </div>
            <div className="space-y-2">
              <label className="text-[9px] font-black text-slate-600 uppercase tracking-widest ml-1">Impermeabilização</label>
              <input
                type="text"
                inputMode="decimal"
                value={impermeabilizacao === 0 ? "" : formatCurrency(impermeabilizacao)}
                onChange={(e) => handleInputChange(setImpermeabilizacao, e.target.value)}
                placeholder="R$ 0,00"
                className="w-full bg-white/[0.03] border border-white/5 p-4 rounded-xl text-white font-bold mono outline-none"
              />
            </div>
          </div>

          <div className="bg-white/[0.02] p-6 rounded-3xl border border-white/5">
            <div className="flex items-center gap-3 mb-6">
              <Award size={16} className="text-emerald-500" />
              <h4 className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Bônus Operacionais</h4>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
              {[
                { id: 'montagem', label: 'Montagem', val: 'R$40' },
                { id: 'lavagem', label: 'Lavagem', val: 'R$40' },
                { id: 'almofada', label: 'Almofada', val: 'R$7' },
                { id: 'pes_guarda_roupa', label: 'Pés G-R', val: 'R$7' },
                { id: 'impermeabilizacao_bonus', label: 'Impermeab.', val: 'R$40' }
              ].map((item) => (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => setExtras(prev => ({...prev, [item.id]: !prev[item.id as keyof typeof extras]}))}
                  className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all duration-200 ${
                    extras[item.id as keyof typeof extras] 
                    ? 'bg-emerald-500 text-black border-emerald-400' 
                    : 'bg-white/5 border-white/5 text-slate-500 hover:border-white/20'
                  }`}
                >
                  <span className="text-[9px] font-black uppercase mb-0.5">{item.label}</span>
                  <span className={`text-[8px] mono font-bold ${extras[item.id as keyof typeof extras] ? 'text-black' : 'opacity-40'}`}>{item.val}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="flex flex-col md:flex-row items-center justify-between p-8 bg-white/[0.02] rounded-3xl border border-white/5 gap-6">
             <div className="text-center md:text-left">
                <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest block mb-1">Total do Cliente</span>
                <div className="text-3xl font-black text-white mono">{formatCurrency(total)}</div>
             </div>
             <div className="text-center md:text-right">
                <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest block mb-1">Seu Bônus Extra</span>
                <div className="text-3xl font-black text-emerald-400 mono">+{formatCurrency(calculateBonus())}</div>
             </div>
          </div>

          <button type="submit" className="w-full bg-white text-black py-6 rounded-2xl font-black text-xs uppercase tracking-[0.3em] hover:bg-cyan-400 transition-all hover:scale-[1.01] active:scale-95 shadow-xl flex items-center justify-center gap-3">
            Concluir Lançamento <ChevronRight size={16} />
          </button>
        </form>
      </div>
    </div>
  );
};

export default SaleForm;

