                onChange={(e) => handleInputChange(setImpermeabilizacao, e.target.value)}
                placeholder="R$ 0,00"
                className="w-full bg-white/[0.02] border border-white/5 p-4 rounded-xl text-white font-bold mono outline-none"
              />
            </div>
          </div>

          <div className="bg-white/[0.01] p-6 rounded-[2rem] border border-white/5">
            <div className="flex items-center gap-2 mb-6 ml-1">
              <Award size={14} className="text-emerald-500" />
              <h4 className="text-[10px] font-black text-white uppercase tracking-[0.2em]">Bônus Operacionais</h4>
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
              {[
                { id: 'montagem', label: 'Montagem', val: 'R$40' },
                { id: 'lavagem', label: 'Lavagem', val: 'R$40' },
                { id: 'almofada', label: 'Almofada', val: 'R$7' },
                { id: 'pes_guarda_roupa', label: 'Pés G-R', val: 'R$7' },
                { id: 'impermeabilizacao_bonus', label: 'Impermeab.', val: 'R$40' }
              ].map((item) => (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => setExtras(prev => ({...prev, [item.id]: !prev[item.id as keyof typeof extras]}))}
                  className={`flex flex-col items-center justify-center p-3 rounded-xl border transition-all duration-200 ${
                    extras[item.id as keyof typeof extras] 
                    ? 'bg-emerald-500 text-black border-emerald-400' 
                    : 'bg-white/5 border-white/5 text-slate-600 hover:border-white/20'
                  }`}
                >
                  <span className="text-[9px] font-black uppercase mb-0.5">{item.label}</span>
                  <span className={`text-[8px] mono font-bold ${extras[item.id as keyof typeof extras] ? 'text-black' : 'opacity-40'}`}>{item.val}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="flex flex-col md:flex-row items-center justify-between p-8 bg-black/40 rounded-3xl border border-white/5 gap-8">
             <div className="text-center md:text-left">
                <span className="text-[9px] font-black text-slate-700 uppercase tracking-widest block mb-1">Total Pago (Cliente)</span>
                <div className="text-3xl font-black text-white mono">{formatCurrency(totalCliente)}</div>
             </div>
             <div className="w-px h-10 bg-white/5 hidden md:block"></div>
             <div className="text-center md:text-right">
                <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest block mb-1">Seu Bônus Extra</span>
                <div className="text-3xl font-black text-emerald-400 mono">+{formatCurrency(calculateBonusVendedor())}</div>
             </div>
          </div>

          <button type="submit" className="w-full bg-white text-black py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.4em] hover:bg-cyan-400 transition-all active:scale-95 shadow-2xl flex items-center justify-center gap-3">
            Gravar Pedido <ChevronRight size={14} />
          </button>
        </form>
      </div>
    </div>
  );
};

