            <div className="glass rounded-[2.5rem] p-10">
               <h3 className="text-2xl font-black text-white uppercase tracking-tighter mb-10">Histórico de Pedidos Quantum</h3>
               <div className="space-y-4">
                  {savedSales.map((sale, i) => (
