                         <div className="text-[9px] text-slate-700 font-bold uppercase tracking-widest mb-4">{sale.data}</div>
                         <div className="flex flex-wrap gap-1.5">
                            {sale.servicosExtras.map((e, idx) => (
                              <span key={idx} className="text-[8px] font-black bg-white/5 text-slate-500 px-2 py-1 rounded-lg border border-white/5 uppercase">{e}</span>
                            ))}
