        <Header />
        <main ref={mainRef} className="flex-1 overflow-x-hidden overflow-y-auto px-6 md:px-12 py-8">
          <div className="max-w-[1100px] mx-auto w-full">
            {renderContent()}
          </div>
        </main>

        <div className="fixed bottom-10 right-10 z-[100]">
          {isFabOpen && (
            <div className="absolute bottom-20 right-0 flex flex-col gap-3 animate-in slide-in-from-bottom-5 fade-in duration-200">
              <button 
                onClick={() => { setActiveNav(NavItem.AdicionarVenda); setIsFabOpen(false); }}
                className="flex items-center gap-3 bg-white text-black px-6 py-4 rounded-xl shadow-2xl font-black text-[10px] uppercase tracking-widest hover:bg-cyan-400 transition-all"
              >
