          )}
          <button 
            onClick={() => setIsFabOpen(!isFabOpen)}
            className={`w-14 h-14 rounded-xl flex items-center justify-center shadow-2xl transition-all duration-300 animate-pulse-neon bg-white text-black ${isFabOpen ? 'rotate-45 bg-red-500 text-white' : ''}`}
