import React, { useState, useRef, useEffect, useMemo } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import OpportunityCard from './components/OpportunityCard';
import PipelineView from './components/PipelineView';
import FunnelChart from './components/FunnelChart';
import SaleForm from './components/SaleForm';
import { NavItem, Sale } from './types';
import { MOCK_OPPORTUNITIES, NAVIGATION_ITEMS } from './constants';
import { 
  Plus, 
  X, 
  History,
  LayoutGrid, 
  List,
  Command,
  Search,
  Award,
  Calendar,
  Share2,
  FilterX
} from 'lucide-react';

const App: React.FC = () => {
  const [activeNav, setActiveNav] = useState<NavItem>(NavItem.Resumos);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [viewMode, setViewMode] = useState<'list' | 'pipeline'>('pipeline');
  const [isFabOpen, setIsFabOpen] = useState(false);
  const [savedSales, setSavedSales] = useState<Sale[]>([]);

  // Filtros de Data
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  const mainRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const data = localStorage.getItem('vc_sales_data');
    if (data) {
      setSavedSales(JSON.parse(data));
    }
  }, []);

  const saveSale = (newSaleData: any) => {
    const saleObj: Sale = {
      numeroPedido: newSaleData.pedido,
      valorProduto: newSaleData.produto,
      valorAssistencia: newSaleData.assistencia,
      valorImpermeabilizacao: newSaleData.impermeabilizacao,
      total: newSaleData.total,
      bonusTotal: newSaleData.bonusTotal,
      comissaoProduto: newSaleData.comissaoProduto,
      servicosExtras: newSaleData.servicosExtras,
      data: new Date().toLocaleDateString('pt-BR'),
      timestamp: Date.now()
    };

    const updatedSales = [saleObj, ...savedSales];
    setSavedSales(updatedSales);
    localStorage.setItem('vc_sales_data', JSON.stringify(updatedSales));
    setActiveNav(NavItem.ResumoPedido);
  };

  const formatBRL = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(val);

  // Lógica de Filtragem
  const filteredSales = useMemo(() => {
    return savedSales.filter(sale => {
      if (!startDate && !endDate) return true;
      const saleDate = new Date(sale.timestamp);
      saleDate.setHours(0, 0, 0, 0);

      const start = startDate ? new Date(startDate + 'T00:00:00') : null;
      const end = endDate ? new Date(endDate + 'T23:59:59') : null;

      if (start && saleDate < start) return false;
      if (end && saleDate > end) return false;
      return true;
    });
  }, [savedSales, startDate, endDate]);

  const totals = useMemo(() => {
    return {
      faturamento: filteredSales.reduce((acc, s) => acc + s.total, 0),
      ganhos: filteredSales.reduce((acc, s) => acc + (s.bonusTotal || 0), 0),
      count: filteredSales.length
    };
  }, [filteredSales]);

  const sendWhatsAppReport = () => {
    const periodStr = startDate && endDate 
      ? `Período: ${new Date(startDate).toLocaleDateString()} até ${new Date(endDate).toLocaleDateString()}`
      : `Relatório Geral (Total)`;

    let message = `🚀 *RELATÓRIO DE VENDAS V&C*\n`;
    message += `📅 ${periodStr}\n`;
    message += `----------------------------\n`;
    message += `💰 *FATURAMENTO:* ${formatBRL(totals.faturamento)}\n`;
    message += `💎 *SEUS GANHOS:* ${formatBRL(totals.ganhos)}\n`;
    message += `📦 *TOTAL PEDIDOS:* ${totals.count}\n`;
    message += `----------------------------\n\n`;
    message += `*DETALHAMENTO:*\n`;

    filteredSales.slice(0, 20).forEach(sale => {
      message += `• Pedido #${sale.numeroPedido}: ${formatBRL(sale.total)} (Ganhos: ${formatBRL(sale.bonusTotal)})\n`;
    });

    if (filteredSales.length > 20) {
      message += `\n... e mais ${filteredSales.length - 20} pedidos no período.`;
    }

    const encodedMessage = encodeURIComponent(message);
    window.open(`https://wa.me/?text=${encodedMessage}`, '_blank');
  };

  const renderContent = () => {
    switch (activeNav) {
      case NavItem.AdicionarVenda:
        return (
          <div className="content-section">
            <SaleForm onCancel={() => setActiveNav(NavItem.Resumos)} onSubmit={saveSale} />
          </div>
        );

      case NavItem.Meta:
      case NavItem.Resumos:
      case NavItem.ResumoPedido:
      case NavItem.ResumoServico:
        return (
          <div className="content-section space-y-8 pb-24 px-2">
            {/* Header de Operações com Filtros */}
            <div className="glass rounded-[2.5rem] p-6 md:p-10 border-white/5 relative overflow-hidden">
               <div className="flex flex-col lg:flex-row items-center justify-between gap-6 relative z-10">
                  <div>
                     <h2 className="text-2xl md:text-3xl font-black text-white uppercase tracking-tighter">Quantum BI</h2>
                     <p className="text-[10px] text-cyan-400 font-bold uppercase tracking-[0.4em] mt-1">Terminal de Auditoria</p>
                  </div>

                  <div className="flex flex-wrap items-center gap-4 justify-center">
                    <div className="flex items-center gap-2 bg-white/5 p-2 rounded-2xl border border-white/10">
                      <div className="flex flex-col px-2">
                        <span className="text-[8px] font-black text-slate-500 uppercase mb-1">De</span>
                        <input 
                          type="date" 
                          value={startDate}
                          onChange={(e) => setStartDate(e.target.value)}
                          className="bg-transparent text-white text-xs font-bold outline-none [color-scheme:dark]"
                        />
                      </div>
                      <div className="w-px h-6 bg-white/10"></div>
                      <div className="flex flex-col px-2">
                        <span className="text-[8px] font-black text-slate-500 uppercase mb-1">Até</span>
                        <input 
                          type="date" 
                          value={endDate}
                          onChange={(e) => setEndDate(e.target.value)}
                          className="bg-transparent text-white text-xs font-bold outline-none [color-scheme:dark]"
                        />
                      </div>
                      {(startDate || endDate) && (
                        <button onClick={() => {setStartDate(''); setEndDate('');}} className="p-2 text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all">
                          <FilterX size={16} />
                        </button>
                      )}
                    </div>

                    <button 
                      onClick={sendWhatsAppReport}
                      className="bg-emerald-500 hover:bg-emerald-400 text-black px-6 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-3 transition-all shadow-xl shadow-emerald-500/10"
                    >
                      <Share2 size={16} /> Enviar p/ Supervisão
                    </button>
                  </div>
               </div>
            </div>

            {/* Dash de Resultados Filtrados */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
               <div className="glass p-8 rounded-[2.5rem] border-white/5 relative overflow-hidden group">
                  <span className="text-[10px] font-black tracking-widest text-slate-500 uppercase mb-4 block">Faturamento Período</span>
                  <h3 className="text-3xl font-black text-white mono">{formatBRL(totals.faturamento)}</h3>
                  <div className="mt-4 flex items-center gap-2">
                    <div className="w-1.5 h-1.5 rounded-full bg-cyan-400 animate-pulse"></div>
                    <span className="text-[9px] font-bold text-cyan-400 uppercase">{totals.count} Pedidos Processados</span>
                  </div>
               </div>

               <div className="glass p-8 rounded-[2.5rem] relative overflow-hidden group border-emerald-500/20">
                  <span className="text-[10px] font-black tracking-widest text-emerald-400 uppercase mb-4 block">Ganhos Vendedor</span>
                  <h3 className="text-3xl font-black text-white mono">{formatBRL(totals.ganhos)}</h3>
                  <div className="mt-4 text-[9px] text-emerald-500/60 font-bold uppercase">
                    Comissões (2.2%) + Bônus Fixos
                  </div>
               </div>

               <div className="bg-gradient-to-br from-violet-600 to-indigo-800 p-8 rounded-[2.5rem] relative overflow-hidden group">
                  <span className="text-[10px] font-black tracking-widest text-white/50 uppercase mb-4 block">Performance Operacional</span>
                  <h3 className="text-3xl font-black text-white mono">{Math.round((totals.ganhos / (totals.faturamento || 1)) * 100)}%</h3>
                  <p className="text-[9px] text-white/40 mt-4 font-bold uppercase">Taxa de Conversão de Bônus</p>
               </div>
            </div>

            {/* Tabela de Lançamentos */}
            <div className="glass rounded-[2.5rem] p-6 md:p-10">
               <div className="flex items-center justify-between mb-8">
                  <h3 className="text-xl font-black text-white uppercase tracking-tighter">Histórico Customizado</h3>
                  {startDate && <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Filtrado por Data</span>}
               </div>

               {filteredSales.length === 0 ? (
                 <div className="py-24 text-center border border-dashed border-white/5 rounded-[2rem] opacity-30">
                    <Calendar size={48} className="mx-auto mb-4" />
                    <p className="font-black uppercase text-[10px] tracking-widest">Nenhum registro no período</p>
                 </div>
               ) : (
                 <div className="space-y-4">
                    {filteredSales.map((sale, i) => (
                      <div key={i} className="flex flex-col lg:flex-row items-center justify-between p-6 bg-white/[0.02] border border-white/5 rounded-2xl hover:bg-white/[0.04] transition-all group">
                        <div className="flex items-center gap-5 w-full lg:w-1/3">
                           <div className="w-12 h-12 rounded-xl bg-white/5 flex items-center justify-center text-slate-500 group-hover:text-cyan-400 transition-all">
                              <Search size={20} />
                           </div>
                           <div>
                              <div className="font-black text-white text-md tracking-tighter uppercase">PEDIDO #{sale.numeroPedido}</div>
                              <div className="text-[10px] text-slate-600 mono font-bold">{sale.data}</div>
                           </div>
                        </div>

                        <div className="flex-1 w-full py-4 lg:py-0">
                           <div className="flex flex-wrap gap-2">
                              {sale.servicosExtras.map((ex, idx) => (
                                <span key={idx} className="text-[8px] font-black bg-white/5 text-slate-500 px-2 py-1 rounded-md uppercase border border-white/5">{ex}</span>
                              ))}
                           </div>
                        </div>

                        <div className="flex items-center gap-10 w-full lg:w-auto justify-between">
                           <div className="text-right">
                              <span className="text-[8px] text-emerald-500 font-black uppercase block mb-1">Seu Ganho</span>
                              <div className="text-lg font-black text-emerald-400 mono">{formatBRL(sale.bonusTotal)}</div>
                           </div>
                           <div className="text-right">
                              <span className="text-[8px] text-slate-700 font-black uppercase block mb-1">Valor Venda</span>
                              <div className="text-2xl font-black text-white mono">{formatBRL(sale.total)}</div>
                           </div>
                        </div>
                      </div>
                    ))}
                 </div>
               )}
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex bg-[#05020a] selection:bg-cyan-400 selection:text-black">
      <Sidebar 
        isCollapsed={isSidebarCollapsed} 
        setIsCollapsed={setIsSidebarCollapsed} 
        activeItem={activeNav} 
        onSelect={setActiveNav} 
      />

      <div className={`flex-1 flex flex-col min-w-0 transition-all duration-500 ${isSidebarCollapsed ? 'md:ml-20' : 'md:ml-64'}`}>
        <Header />
        <main ref={mainRef} className="flex-1 overflow-x-hidden overflow-y-auto px-6 lg:px-14 py-8">
          <div className="max-w-[1200px] mx-auto w-full">
            {renderContent() || (
              <div className="py-20 text-center text-slate-600 font-black uppercase tracking-[0.5em] opacity-20">
                Acesse o Painel ou Metas
              </div>
            )}
          </div>
        </main>

        <div className="fixed bottom-10 right-10 z-[100]">
          {isFabOpen && (
            <div className="absolute bottom-20 right-0 flex flex-col gap-3 animate-in slide-in-from-bottom-5 fade-in duration-300">
              <button 
                onClick={() => { setActiveNav(NavItem.AdicionarVenda); setIsFabOpen(false); }}
                className="flex items-center gap-4 bg-white text-black px-8 py-5 rounded-2xl shadow-2xl font-black text-[10px] uppercase tracking-widest hover:bg-cyan-400 transition-all"
              >
                <Plus size={18} /> Lançar Operação
              </button>
            </div>
          )}
          <button 
            onClick={() => setIsFabOpen(!isFabOpen)}
            className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center shadow-2xl transition-all duration-500 animate-pulse-neon ${
              isFabOpen ? 'bg-rose-500 rotate-45 text-white' : 'bg-cyan-500 text-black'
            }`}
          >
            {isFabOpen ? <X size={28} /> : <Command size={28} />}
          </button>
        </div>
      </div>
    </div>
  );
};

export default App;

export interface Opportunity {
  id: string;
  title: string;
  type: string;
  value: number;
  daysAgo: number;
  stage: string;
  user: {
    name: string;
    avatar: string;
  };
  tags: string[];
}

export interface Sale {
  numeroPedido: string;
  valorProduto: number;
  valorAssistencia: number;
  valorImpermeabilizacao: number;
  total: number;
  data: string;
  timestamp: number; // Adicionado para filtro de data
  bonusTotal: number;
  comissaoProduto: number;
  servicosExtras: string[];
}

export interface PipelineStage {
  id: string;
  label: string;
  color: string;
}

export enum NavItem {
  Resumos = 'Resumos',
  Clientes = 'Clientes',
  Processos = 'Processos',
  Documentos = 'Documentos',
  Produtos = 'Produtos',
  RelatoriosBeta = 'Relatórios Beta',
  Relatorios = 'Relatórios',
  Biblioteca = 'Biblioteca',
  Meta = 'Meta',
  ResumoServico = 'Resumo serviço',
  ResumoPedido = 'Resumo pedido',
  AdicionarVenda = 'Adicionar vendas'
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import OpportunityCard from './components/OpportunityCard';
import PipelineView from './components/PipelineView';
import FunnelChart from './components/FunnelChart';
import SaleForm from './components/SaleForm';
import { NavItem, Sale } from './types';
import { MOCK_OPPORTUNITIES, NAVIGATION_ITEMS } from './constants';
import { 
  Plus, 
  X, 
  History,
  LayoutGrid, 
  List,
  Command,
  Search,
  Award,
  Calendar,
  Share2,
  FilterX
} from 'lucide-react';

const App: React.FC = () => {
  const [activeNav, setActiveNav] = useState<NavItem>(NavItem.Resumos);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [viewMode, setViewMode] = useState<'list' | 'pipeline'>('pipeline');
  const [isFabOpen, setIsFabOpen] = useState(false);
  const [savedSales, setSavedSales] = useState<Sale[]>([]);

  // Estados para filtro de data
  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  const mainRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const data = localStorage.getItem('vc_sales_data');
    if (data) {
      setSavedSales(JSON.parse(data));
    }
  }, []);

  const saveSale = (newSaleData: any) => {
    const saleObj: Sale = {
      numeroPedido: newSaleData.pedido,
      valorProduto: newSaleData.produto,
      valorAssistencia: newSaleData.assistencia,
      valorImpermeabilizacao: newSaleData.impermeabilizacao,
      total: newSaleData.total,
      bonusTotal: newSaleData.bonusTotal,
      comissaoProduto: newSaleData.comissaoProduto,
      servicosExtras: newSaleData.servicosExtras,
      data: new Date().toLocaleDateString('pt-BR'),
      timestamp: Date.now() // Timestamp para filtro
    };

    const updatedSales = [saleObj, ...savedSales];
    setSavedSales(updatedSales);
    localStorage.setItem('vc_sales_data', JSON.stringify(updatedSales));
    setActiveNav(NavItem.Resumos);
  };

  const formatBRL = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 }).format(val);

  // Filtro de Vendas por Período
  const filteredSales = useMemo(() => {
    return savedSales.filter(sale => {
      if (!startDate && !endDate) return true;

      const saleDate = new Date(sale.timestamp);
      saleDate.setHours(0, 0, 0, 0);

      const start = startDate ? new Date(startDate + 'T00:00:00') : null;
      const end = endDate ? new Date(endDate + 'T23:59:59') : null;

      if (start && saleDate < start) return false;
      if (end && saleDate > end) return false;
      return true;
    });
  }, [savedSales, startDate, endDate]);

  const sendWhatsAppReport = () => {
    const totalFaturado = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const totalGanhos = filteredSales.reduce((acc, s) => acc + (s.bonusTotal || 0), 0);
    const periodoStr = startDate && endDate 
      ? `Período: ${new Date(startDate).toLocaleDateString()} a ${new Date(endDate).toLocaleDateString()}`
      : `Relatório Completo`;

    let message = `🚀 *RELATÓRIO DE VENDAS V&C*\n`;
    message += `📅 ${periodStr}\n`;
    message += `----------------------------\n`;
    message += `💰 *FATURAMENTO:* ${formatBRL(totalFaturado)}\n`;
    message += `💎 *GANHOS VENDEDOR:* ${formatBRL(totalGanhos)}\n`;
    message += `📦 *TOTAL PEDIDOS:* ${filteredSales.length}\n`;
    message += `----------------------------\n\n`;
    message += `*PEDIDOS:* \n`;

    filteredSales.slice(0, 15).forEach(s => {
      message += `• #${s.numeroPedido} - ${formatBRL(s.total)} (Ganhos: ${formatBRL(s.bonusTotal)})\n`;
    });

    if (filteredSales.length > 15) {
      message += `\n... e mais ${filteredSales.length - 15} pedidos.`;
    }

    const encoded = encodeURIComponent(message);
    window.open(`https://wa.me/?text=${encoded}`, '_blank');
  };

  const renderContent = () => {
    // Calculamos os totais baseados no FILTRO
    const totalFaturado = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const totalBonus = filteredSales.reduce((acc, s) => acc + (s.bonusTotal || 0), 0);
    const totalComissao = filteredSales.reduce((acc, s) => acc + (s.comissaoProduto || 0), 0);

    const filterControls = (
      <div className="glass p-4 rounded-2xl border-white/10 mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-500 uppercase mb-1">Início</span>
            <input 
              type="date" 
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="bg-white/5 border border-white/10 rounded-lg p-2 text-xs text-white outline-none [color-scheme:dark]"
            />
          </div>
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-500 uppercase mb-1">Fim</span>
            <input 
              type="date" 
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="bg-white/5 border border-white/10 rounded-lg p-2 text-xs text-white outline-none [color-scheme:dark]"
            />
          </div>
          {(startDate || endDate) && (
            <button onClick={() => {setStartDate(''); setEndDate('');}} className="mt-4 p-2 text-rose-500 hover:bg-rose-500/10 rounded-lg transition-all">
              <FilterX size={16} />
            </button>
          )}
        </div>
        <button 
          onClick={sendWhatsAppReport}
          className="bg-emerald-500 hover:bg-emerald-400 text-black px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest flex items-center gap-2 transition-all shadow-lg shadow-emerald-500/10"
        >
          <Share2 size={14} /> Mudar p/ Supervisão (Whats)
        </button>
      </div>
    );

    switch (activeNav) {
      case NavItem.AdicionarVenda:
        return (
          <div className="content-section">
            <SaleForm onCancel={() => setActiveNav(NavItem.Resumos)} onSubmit={saveSale} />
          </div>
        );

      case NavItem.Meta:
        return (
          <div className="content-section py-4 px-2">
            {filterControls}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="glass p-8 rounded-[2.5rem] relative overflow-hidden group">
                <span className="text-[10px] font-black tracking-widest text-cyan-400 uppercase mb-4 block">Faturamento do Período</span>
                <h3 className="text-3xl font-black text-white mono mb-2">{formatBRL(totalFaturado)}</h3>
                <div className="h-1 w-full bg-white/5 rounded-full mt-6 overflow-hidden">
                  <div className="h-full bg-cyan-400 transition-all duration-1000" style={{ width: `${Math.min((totalFaturado / 150000) * 100, 100)}%` }}></div>
                </div>
              </div>

              <div className="glass p-8 rounded-[2.5rem] relative overflow-hidden group border-emerald-500/20">
                <span className="text-[10px] font-black tracking-widest text-emerald-400 uppercase mb-4 block">Ganhos Vendedor (Total)</span>
                <h3 className="text-3xl font-black text-white mono mb-1">{formatBRL(totalBonus)}</h3>
                <div className="text-[9px] text-emerald-500/60 font-bold uppercase flex items-center gap-1">
                   Inclui {formatBRL(totalComissao)} de comissão (2.2%)
                </div>
              </div>

              <div className="bg-gradient-to-br from-violet-600 to-fuchsia-700 p-8 rounded-[2.5rem] shadow-2xl relative overflow-hidden group">
                 <span className="text-[10px] font-black tracking-widest text-white/50 uppercase mb-4 block">Pedidos Registrados</span>
                 <h3 className="text-3xl font-black text-white mono mb-2">{filteredSales.length}</h3>
                 <p className="text-[10px] text-white/40 mt-2 font-bold uppercase">Média: {formatBRL(filteredSales.length ? totalFaturado / filteredSales.length : 0)}</p>
              </div>
            </div>
          </div>
        );

      case NavItem.ResumoServico:
      case NavItem.ResumoPedido:
        return (
          <div className="content-section py-4 space-y-6 px-2">
            {filterControls}
            <div className="glass rounded-[2.5rem] p-6 md:p-10 relative overflow-hidden">
               <h3 className="text-xl md:text-2xl font-black text-white uppercase tracking-tighter mb-8">Histórico de Lançamentos</h3>

               {filteredSales.length === 0 ? (
                 <div className="py-20 flex flex-col items-center justify-center text-slate-600 border border-dashed border-white/5 rounded-3xl">
                    <History size={48} className="mb-4 opacity-20" />
                    <p className="font-bold uppercase text-[10px] tracking-widest">Nenhum pedido no período</p>
                 </div>
               ) : (
                 <div className="space-y-4">
                    {filteredSales.map((sale, i) => (
                      <div key={i} className="flex flex-col lg:flex-row items-center justify-between p-6 bg-white/5 border border-white/5 rounded-2xl hover:border-white/20 transition-all gap-6 group">
                        <div className="flex items-center gap-5 w-full lg:w-1/3">
                           <div className="w-12 h-12 rounded-xl bg-white/5 flex items-center justify-center text-white/40 group-hover:text-cyan-400 transition-all">
                              <Search size={20} />
                           </div>
                           <div>
                              <div className="font-black text-white text-md tracking-tight uppercase">ID: {sale.numeroPedido}</div>
                              <div className="text-[10px] text-slate-500 mono font-bold">{sale.data}</div>
                           </div>
                        </div>

                        <div className="flex-1 w-full lg:w-auto">
                           <div className="flex flex-wrap gap-2">
                              {sale.servicosExtras && sale.servicosExtras.map((extra, idx) => (
                                <span key={idx} className="text-[8px] font-black bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 px-2 py-1 rounded-md uppercase">
                                  {extra}
                                </span>
                              ))}
                           </div>
                        </div>

                        <div className="flex items-center gap-10 w-full lg:w-auto justify-between lg:justify-end">
                           <div className="text-right">
                              <div className="text-[9px] text-emerald-500 font-black uppercase">Ganhos</div>
                              <div className="text-lg font-black text-emerald-400 mono">{formatBRL(sale.bonusTotal || 0)}</div>
                           </div>
                           <div className="text-right">
                              <div className="text-[9px] text-slate-600 font-black uppercase">Venda</div>
                              <div className="text-2xl font-black text-white mono">{formatBRL(sale.total)}</div>
                           </div>
                        </div>
                      </div>
                    ))}
                 </div>
               )}
            </div>
          </div>
        );

      default:
        return (
          <div className="content-section animate-in fade-in slide-in-from-bottom-6 duration-700 px-2">
            <div className="flex flex-col lg:flex-row items-center justify-between mb-8 gap-6">
              <div>
                 <div className="flex items-center gap-2 mb-1 justify-center lg:justify-start">
                    <div className="w-1.5 h-1.5 rounded-full bg-cyan-400 animate-glow"></div>
                    <span className="text-[9px] font-black tracking-[0.3em] text-cyan-400 uppercase">Status: Online</span>
                 </div>
                 <h2 className="text-3xl md:text-4xl font-black text-white tracking-tighter text-center lg:text-left uppercase">Painel Quantum</h2>
              </div>
              <div className="glass p-1 rounded-xl flex">
                <button onClick={() => setViewMode('list')} className={`p-2.5 rounded-lg transition-all ${viewMode === 'list' ? 'bg-cyan-500 text-black' : 'text-slate-500 hover:text-white'}`}><List size={18}/></button>
                <button onClick={() => setViewMode('pipeline')} className={`p-2.5 rounded-lg transition-all ${viewMode === 'pipeline' ? 'bg-cyan-500 text-black' : 'text-slate-500 hover:text-white'}`}><LayoutGrid size={18}/></button>
              </div>
            </div>

            {filterControls}

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
               <div className="bg-white/5 p-5 rounded-2xl border border-white/5">
                  <div className="text-[9px] font-black text-slate-500 uppercase mb-2">Faturamento</div>
                  <div className="text-xl font-black text-white mono">{formatBRL(totalFaturado)}</div>
               </div>
               <div className="bg-white/5 p-5 rounded-2xl border border-white/5">
                  <div className="text-[9px] font-black text-emerald-500 uppercase mb-2">Seus Ganhos</div>
                  <div className="text-xl font-black text-emerald-400 mono">{formatBRL(totalBonus)}</div>
               </div>
               <div className="bg-white/5 p-5 rounded-2xl border border-white/5">
                  <div className="text-[9px] font-black text-cyan-500 uppercase mb-2">Tickets</div>
                  <div className="text-xl font-black text-cyan-400 mono">{filteredSales.length}</div>
               </div>
               <div className="bg-white/5 p-5 rounded-2xl border border-white/5">
                  <div className="text-[9px] font-black text-violet-500 uppercase mb-2">Comissão (2.2%)</div>
                  <div className="text-xl font-black text-violet-400 mono">{formatBRL(totalComissao)}</div>
               </div>
            </div>

            {viewMode === 'list' ? (
              <div className="space-y-4">
                {MOCK_OPPORTUNITIES.map(op => <OpportunityCard key={op.id} opportunity={op} />)}
              </div>
            ) : (
              <div className="space-y-8">
                <FunnelChart opportunities={MOCK_OPPORTUNITIES} />
                <div className="overflow-x-auto pb-4 scrollbar-hide">
                  <PipelineView opportunities={MOCK_OPPORTUNITIES} />
                </div>
              </div>
            )}
          </div>
        );
    }
  };

  return (
    <div className="min-h-screen flex selection:bg-cyan-400 selection:text-black bg-[#05020a] overflow-hidden">
      <div className={`transition-all duration-500 z-50 flex-shrink-0 ${isSidebarCollapsed ? 'w-24' : 'w-64'}`}>
        <Sidebar isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed} activeItem={activeNav} onSelect={setActiveNav} />
      </div>

      <div className="flex-1 flex flex-col min-w-0 h-screen relative">
        <Header />
