               </div>
               <div className="bg-white/5 p-5 rounded-2xl border border-white/5">
                  <div className="text-[9px] font-black text-emerald-500 uppercase mb-2">Seus Ganhos</div>
                  <div className="text-xl font-black text-emerald-400 mono">{formatBRL(totalBonus)}</div>
               </div>
               <div className="bg-white/5 p-5 rounded-2xl border border-white/5">
                  <div className="text-[9px] font-black text-cyan-500 uppercase mb-2">Pedidos</div>
