    };

    const updatedSales = [saleObj, ...savedSales];
    setSavedSales(updatedSales);
    localStorage.setItem('vc_sales_data', JSON.stringify(updatedSales));
    setActiveNav(NavItem.Resumos);
  };

  const formatBRL = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 2 }).format(val);

  // Lógica de Filtro por Período
  const filteredSales = useMemo(() => {
    return savedSales.filter(sale => {
      if (!startDate && !endDate) return true;

      const saleDate = new Date(sale.timestamp || 0);
      saleDate.setHours(0, 0, 0, 0);

      const start = startDate ? new Date(startDate + 'T00:00:00') : null;
      const end = endDate ? new Date(endDate + 'T23:59:59') : null;

      if (start && saleDate < start) return false;
      if (end && saleDate > end) return false;
      return true;
    });
  }, [savedSales, startDate, endDate]);

  const sendWhatsAppReport = () => {
    const totalFaturado = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const totalGanhos = filteredSales.reduce((acc, s) => acc + (s.bonusTotal || 0), 0);
    const totalComissao = filteredSales.reduce((acc, s) => acc + (s.comissaoProduto || 0), 0);

    const periodoStr = startDate && endDate 
      ? `${new Date(startDate).toLocaleDateString('pt-BR')} até ${new Date(endDate).toLocaleDateString('pt-BR')}`
      : `Relatório Total`;

    let message = `🚀 *RELATÓRIO DETALHADO V&C*\n`;
    message += `📅 *Período:* ${periodoStr}\n`;
    message += `----------------------------\n`;
    message += `💰 *FATURAMENTO:* ${formatBRL(totalFaturado)}\n`;
    message += `💎 *GANHOS VENDEDOR:* ${formatBRL(totalGanhos)}\n`;
    message += `💸 *COMISSÃO (2.2%):* ${formatBRL(totalComissao)}\n`;
    message += `📦 *TOTAL PEDIDOS:* ${filteredSales.length}\n`;
