const CACHE_NAME = 'vc-quantum-v1';
const urlsToCache = [
  '/',
  '/index.html',
  '/index.tsx',
  '/App.tsx',
  '/types.ts',
  '/constants.tsx'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => cache.addAll(urlsToCache))
  );
});

self.addEventListener('fetch', event => {
  event.respondWith(
    caches.match(event.request)
      .then(response => {
        if (response) return response;
        return fetch(event.request);
      })
  );
});

import React, { useState, useRef, useEffect, useMemo } from 'react';
import html2canvas from 'html2canvas';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import OpportunityCard from './components/OpportunityCard';
import PipelineView from './components/PipelineView';
import FunnelChart from './components/FunnelChart';
import SaleForm from './components/SaleForm';
import { NavItem, Sale } from './types';
import { MOCK_OPPORTUNITIES, NAVIGATION_ITEMS } from './constants';
import { 
  Plus, 
  X, 
  History,
  LayoutGrid, 
  List,
  Search,
  Share2,
  FilterX,
  Image as ImageIcon,
  WifiOff,
  Percent
} from 'lucide-react';

const STORAGE_KEY = 'vc_quantum_data_v1';

const App: React.FC = () => {
  const [activeNav, setActiveNav] = useState<NavItem>(NavItem.Resumos);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [viewMode, setViewMode] = useState<'list' | 'pipeline'>('pipeline');
  const [isFabOpen, setIsFabOpen] = useState(false);
  const [savedSales, setSavedSales] = useState<Sale[]>([]);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  const mainRef = useRef<HTMLDivElement>(null);
  const reportContentRef = useRef<HTMLDivElement>(null);

  // Carregar dados iniciais e monitorar conexão
  useEffect(() => {
    const rawData = localStorage.getItem(STORAGE_KEY);
    if (rawData) {
      try {
        setSavedSales(JSON.parse(rawData));
      } catch (e) {
        console.error("Erro ao carregar dados do storage", e);
      }
    }

    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Persistência automática sempre que a lista de vendas mudar
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(savedSales));
  }, [savedSales]);

  const saveSale = (newSaleData: any) => {
    const saleObj: Sale = {
      numeroPedido: newSaleData.pedido,
      valorProduto: newSaleData.produto,
      valorAssistencia: newSaleData.assistencia,
      valorImpermeabilizacao: newSaleData.impermeabilizacao,
      total: newSaleData.total,
      bonusTotal: newSaleData.bonusTotal,
      comissaoProduto: newSaleData.comissaoProduto,
      servicosExtras: newSaleData.servicosExtras,
      data: new Date().toLocaleDateString('pt-BR'),
      timestamp: Date.now()
    };

    // Usar função de atualização para garantir consistência
    setSavedSales(prev => [saleObj, ...prev]);
    setActiveNav(NavItem.ResumoPedido);
  };

  const formatBRL = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 2 }).format(val);

  const filteredSales = useMemo(() => {
    return savedSales.filter(sale => {
      if (!startDate && !endDate) return true;
      const saleDate = new Date(sale.timestamp || 0);
      saleDate.setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate + 'T00:00:00') : null;
      const end = endDate ? new Date(endDate + 'T23:59:59') : null;
      if (start && saleDate < start) return false;
      if (end && saleDate > end) return false;
      return true;
    });
  }, [savedSales, startDate, endDate]);

  const downloadVisualReport = async () => {
    if (!reportContentRef.current) {
        alert("Acesse 'Pedidos' para gerar o relatório.");
        return;
    }
    setIsGeneratingImage(true);
    try {
      const element = reportContentRef.current;
      const canvas = await html2canvas(element, {
        backgroundColor: '#05020a',
        scale: 2,
        logging: false,
        useCORS: true,
        onclone: (clonedDoc) => {
            const el = clonedDoc.querySelector('[data-report-container]');
            if (el) (el as HTMLElement).style.background = '#05020a';
        }
      });
      const image = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      link.href = image;
      link.download = `V&C_Relatorio_${new Date().toLocaleDateString('pt-BR').replace(/\//g, '-')}.png`;
      link.click();
    } catch (error) {
      alert("Erro ao gerar PNG.");
    } finally {
      setIsGeneratingImage(false);
    }
  };

  const sendWhatsAppReport = () => {
    const totalFaturado = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const totalComissao = filteredSales.reduce((acc, s) => acc + (s.comissaoProduto || 0), 0);
    const totalGanhos = filteredSales.reduce((acc, s) => acc + (s.bonusTotal || 0), 0);

    let message = `🚀 *RELATÓRIO V&C*\n`;
    message += `💰 *FATURAMENTO:* ${formatBRL(totalFaturado)}\n`;
    message += `💸 *COMISSÃO (2.2%):* ${formatBRL(totalComissao)}\n`;
    message += `💎 *GANHOS TOTAIS:* ${formatBRL(totalGanhos)}\n`;
    message += `📦 *PEDIDOS:* ${filteredSales.length}\n`;

    const encoded = encodeURIComponent(message);
    window.open(`https://wa.me/?text=${encoded}`, '_blank');
  };

  const renderContent = () => {
    const totalFaturado = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const totalBonus = filteredSales.reduce((acc, s) => acc + (s.bonusTotal || 0), 0);
    const totalComissao = filteredSales.reduce((acc, s) => acc + (s.comissaoProduto || 0), 0);

    const filterUI = (
      <div className="glass p-4 rounded-3xl border-white/10 mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-500 uppercase mb-1 ml-1">De</span>
            <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
          </div>
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-500 uppercase mb-1 ml-1">Até</span>
            <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
          </div>
          {(startDate || endDate) && (
            <button onClick={() => {setStartDate(''); setEndDate('');}} className="mt-4 p-2 text-rose-500 hover:bg-rose-500/10 rounded-xl">
              <FilterX size={16} />
            </button>
          )}
        </div>
        <div className="flex items-center gap-3">
          {(activeNav === NavItem.ResumoPedido || activeNav === NavItem.ResumoServico) && (
            <button onClick={downloadVisualReport} disabled={isGeneratingImage} className="bg-cyan-500/10 text-cyan-400 border border-cyan-500/30 px-6 py-3 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2">
              {isGeneratingImage ? <div className="w-3 h-3 border-2 border-cyan-400 border-t-transparent animate-spin rounded-full"></div> : <ImageIcon size={14} />}
              Exportar PNG
            </button>
          )}
          <button onClick={sendWhatsAppReport} className="bg-emerald-500 text-black px-6 py-3 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2">
            <Share2 size={14} /> WhatsApp
          </button>
        </div>
      </div>
    );

    switch (activeNav) {
      case NavItem.AdicionarVenda:
        return <SaleForm onCancel={() => setActiveNav(NavItem.Resumos)} onSubmit={saveSale} />;

      case NavItem.Meta:
      case NavItem.Resumos:
        return (
          <div className="content-section py-4 px-2">
            {!isOnline && (
              <div className="bg-amber-500/10 border border-amber-500/20 p-4 rounded-2xl flex items-center gap-3 text-amber-500 mb-6">
                <WifiOff size={18} />
                <span className="text-[10px] font-black uppercase tracking-widest">Modo Offline Ativo - Dados salvos localmente</span>
              </div>
            )}
            {filterUI}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
              <div className="glass p-6 rounded-[2rem]">
                <span className="text-[10px] font-black text-cyan-400 uppercase mb-3 block">Faturamento</span>
                <h3 className="text-2xl font-black text-white mono">{formatBRL(totalFaturado)}</h3>
              </div>
              <div className="bg-gradient-to-br from-violet-600 to-indigo-700 p-6 rounded-[2rem] shadow-xl">
                <div className="flex items-center gap-2 mb-3">
                  <Percent size={14} className="text-white/60" />
                  <span className="text-[10px] font-black text-white uppercase">Comissão Total (2.2%)</span>
                </div>
                <h3 className="text-2xl font-black text-white mono">{formatBRL(totalComissao)}</h3>
              </div>
              <div className="glass p-6 rounded-[2rem]">
                <span className="text-[10px] font-black text-emerald-400 uppercase mb-3 block">Ganhos Totais</span>
                <h3 className="text-2xl font-black text-white mono">{formatBRL(totalBonus)}</h3>
              </div>
              <div className="glass p-6 rounded-[2rem]">
                <span className="text-[10px] font-black text-slate-500 uppercase mb-3 block">Pedidos</span>
                <h3 className="text-2xl font-black text-white mono">{filteredSales.length}</h3>
              </div>
            </div>

            {activeNav === NavItem.Resumos && (
               <div className="space-y-8">
                  <FunnelChart opportunities={MOCK_OPPORTUNITIES} />
                  <div className="overflow-x-auto pb-4 scrollbar-hide">
                    <PipelineView opportunities={MOCK_OPPORTUNITIES} />
                  </div>
               </div>
            )}
          </div>
        );

      case NavItem.ResumoPedido:
      case NavItem.ResumoServico:
        return (
          <div className="content-section py-4 space-y-6 px-2">
            {filterUI}
            <div ref={reportContentRef} data-report-container className="glass rounded-[2.5rem] p-6 md:p-10 bg-[#05020a]">
               <div className="flex flex-col md:flex-row md:items-center justify-between mb-10 gap-6">
                  <div>
                    <h3 className="text-2xl font-black text-white uppercase">Relatório de Vendas</h3>
                    <p className="text-[9px] text-slate-500 font-bold uppercase tracking-[0.2em] mt-1">V&C - Quantum Management System</p>
                  </div>
                  <div className="flex gap-10">
                    <div className="text-right">
                      <div className="text-[10px] font-black text-violet-400 uppercase">Comissão (2.2%)</div>
                      <div className="text-xl font-black text-white mono">{formatBRL(totalComissao)}</div>
                    </div>
                    <div className="text-right border-l border-white/10 pl-10">
                      <div className="text-[10px] font-black text-cyan-400 uppercase">Total Geral</div>
                      <div className="text-xl font-black text-white mono">{formatBRL(totalFaturado)}</div>
                    </div>
                  </div>
               </div>

               {filteredSales.length === 0 ? (
                 <div className="py-20 flex flex-col items-center justify-center text-slate-700 border border-dashed border-white/5 rounded-3xl">
                    <History size={48} className="mb-4 opacity-10" />
                    <p className="font-bold uppercase text-[10px] tracking-widest">Nenhuma venda encontrada</p>
                 </div>
               ) : (
                 <div className="space-y-4">
                    {filteredSales.map((sale, i) => (
                      <div key={i} className="flex flex-col lg:flex-row items-center justify-between p-6 bg-white/5 border border-white/5 rounded-2xl gap-6">
                        <div className="flex items-center gap-5 w-full lg:w-1/3">
                           <div className="w-10 h-10 rounded-lg bg-white/5 flex items-center justify-center text-cyan-400"><Search size={18} /></div>
                           <div>
                              <div className="font-black text-white uppercase">#{sale.numeroPedido}</div>
                              <div className="text-[9px] text-slate-500 mono">{sale.data}</div>
                           </div>
                        </div>
                        <div className="flex-1 w-full lg:w-auto flex flex-wrap gap-2">
                           {sale.servicosExtras?.map((ex, idx) => (
                             <span key={idx} className="text-[8px] font-black bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 px-2 py-1 rounded-md uppercase">{ex}</span>
                           ))}
                        </div>
                        <div className="flex items-center gap-12 w-full lg:w-auto justify-between lg:justify-end">
                           <div className="text-right">
                              <div className="text-[9px] text-emerald-500 font-black uppercase tracking-widest">Ganhos</div>
                              <div className="text-lg font-black text-emerald-400 mono">{formatBRL(sale.bonusTotal || 0)}</div>
                           </div>
                           <div className="text-right">
                              <div className="text-[9px] text-slate-600 font-black uppercase tracking-widest">Venda</div>
                              <div className="text-xl font-black text-white mono">{formatBRL(sale.total)}</div>
                           </div>
                        </div>
                      </div>
                    ))}
                 </div>
               )}
            </div>
          </div>
        );

      default:
        return <div>Em breve...</div>;
    }
  };

  return (
    <div className="min-h-screen flex bg-[#05020a] overflow-hidden">
      <div className={`transition-all duration-500 z-50 flex-shrink-0 ${isSidebarCollapsed ? 'w-24' : 'w-64'}`}>
        <Sidebar isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed} activeItem={activeNav} onSelect={setActiveNav} />
      </div>
      <div className="flex-1 flex flex-col min-w-0 h-screen relative">
        <Header />
        <main ref={mainRef} className="flex-1 overflow-x-hidden overflow-y-auto content-scroll px-4 md:px-8 py-6">
          <div className="max-w-[1200px] mx-auto w-full">{renderContent()}</div>
        </main>
        <div className="fixed bottom-10 right-10 z-[100]">
          {isFabOpen && (
            <div className="absolute bottom-20 right-0 flex flex-col gap-3 animate-in slide-in-from-bottom-10 fade-in duration-300">
              {NAVIGATION_ITEMS.map((item) => (
                <button key={item.id} onClick={() => { setActiveNav(item.id); setIsFabOpen(false); }} className="flex items-center gap-3 bg-[#0a051a]/90 backdrop-blur-2xl border border-white/10 px-6 py-4 rounded-2xl text-white hover:bg-cyan-500 hover:text-black transition-all group whitespace-nowrap">
                  <span className="text-cyan-400 group-hover:text-black">{item.icon}</span>
                  <span className="font-black text-[10px] uppercase tracking-[0.2em]">{item.label}</span>
                </button>
              ))}
            </div>
          )}
          <button onClick={() => setIsFabOpen(!isFabOpen)} className={`w-16 h-16 rounded-3xl flex items-center justify-center shadow-2xl transition-all duration-500 animate-pulse-neon floating-action ${isFabOpen ? 'bg-rose-500 rotate-45 text-white' : 'bg-cyan-500 text-black rotate-0'}`}>
            {isFabOpen ? <X size={28} /> : <Plus size={28} />}
          </button>
        </div>
      </div>
    </div>
  );
};

export default App;

export interface Opportunity {
  id: string;
  title: string;
  type: string;
  value: number;
  daysAgo: number;
  stage: string;
  user: {
    name: string;
    avatar: string;
  };
  tags: string[];
}

export interface Targets {
  product: number;
  assistance: number;
  waterproofing: number;
}

export interface Sale {
  numeroPedido: string;
  valorProduto: number;
  valorAssistencia: number;
  valorImpermeabilizacao: number;
  total: number;
  data: string;
  timestamp: number;
  bonusTotal: number;
  comissaoProduto: number; // Base 2.2%
  servicosExtras: string[];
}

export interface PipelineStage {
  id: string;
  label: string;
  color: string;
}

export enum NavItem {
  Resumos = 'Resumos',
  Clientes = 'Clientes',
  Processos = 'Processos',
  Documentos = 'Documentos',
  Produtos = 'Produtos',
  RelatoriosBeta = 'Relatórios Beta',
  Relatorios = 'Relatórios',
  Biblioteca = 'Biblioteca',
  Meta = 'Meta',
  ResumoServico = 'Resumo serviço',
  ResumoPedido = 'Resumo pedido',
  AdicionarVenda = 'Adicionar vendas'
}

import React, { useState, useRef, useEffect, useMemo } from 'react';
import html2canvas from 'html2canvas';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import OpportunityCard from './components/OpportunityCard';
import PipelineView from './components/PipelineView';
import FunnelChart from './components/FunnelChart';
import SaleForm from './components/SaleForm';
import { NavItem, Sale, Targets } from './types';
import { MOCK_OPPORTUNITIES, NAVIGATION_ITEMS } from './constants';
import { 
  Plus, 
  X, 
  History,
  LayoutGrid, 
  List,
  Search,
  Share2,
  FilterX,
  Image as ImageIcon,
  WifiOff,
  Percent,
  Target,
  Trophy,
  Zap,
  TrendingUp,
  Settings2
} from 'lucide-react';

const STORAGE_KEY = 'vc_quantum_data_v2';
const TARGETS_KEY = 'vc_quantum_targets_v1';

const App: React.FC = () => {
  const [activeNav, setActiveNav] = useState<NavItem>(NavItem.Resumos);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [viewMode, setViewMode] = useState<'list' | 'pipeline'>('pipeline');
  const [isFabOpen, setIsFabOpen] = useState(false);
  const [savedSales, setSavedSales] = useState<Sale[]>([]);
  const [isGeneratingImage, setIsGeneratingImage] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Metas editáveis
  const [targets, setTargets] = useState<Targets>({
    product: 50000,
    assistance: 3000,
    waterproofing: 2000
  });

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  const mainRef = useRef<HTMLDivElement>(null);
  const reportContentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const rawData = localStorage.getItem(STORAGE_KEY);
    if (rawData) {
      try { setSavedSales(JSON.parse(rawData)); } catch (e) {}
    }

    const rawTargets = localStorage.getItem(TARGETS_KEY);
    if (rawTargets) {
      try { setTargets(JSON.parse(rawTargets)); } catch (e) {}
    }

    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(savedSales));
  }, [savedSales]);

  useEffect(() => {
    localStorage.setItem(TARGETS_KEY, JSON.stringify(targets));
  }, [targets]);

  const saveSale = (newSaleData: any) => {
    const saleObj: Sale = {
      numeroPedido: newSaleData.pedido,
      valorProduto: newSaleData.produto,
      valorAssistencia: newSaleData.assistencia,
      valorImpermeabilizacao: newSaleData.impermeabilizacao,
      total: newSaleData.total,
      bonusTotal: newSaleData.bonusTotal,
      comissaoProduto: newSaleData.comissaoProduto,
      servicosExtras: newSaleData.servicosExtras,
      data: new Date().toLocaleDateString('pt-BR'),
      timestamp: Date.now()
    };
    setSavedSales(prev => [saleObj, ...prev]);
    setActiveNav(NavItem.ResumoPedido);
  };

  const formatBRL = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const filteredSales = useMemo(() => {
    return savedSales.filter(sale => {
      if (!startDate && !endDate) return true;
      const saleDate = new Date(sale.timestamp || 0);
      saleDate.setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate + 'T00:00:00') : null;
      const end = endDate ? new Date(endDate + 'T23:59:59') : null;
      return !( (start && saleDate < start) || (end && saleDate > end) );
    });
  }, [savedSales, startDate, endDate]);

  // Cálculos de Performance
  const stats = useMemo(() => {
    const pTotal = filteredSales.reduce((acc, s) => acc + s.valorProduto, 0);
    const aTotal = filteredSales.reduce((acc, s) => acc + s.valorAssistencia, 0);
    const iTotal = filteredSales.reduce((acc, s) => acc + s.valorImpermeabilizacao, 0);

    const pPerc = targets.product > 0 ? (pTotal / targets.product) : 0;
    const aPerc = targets.assistance > 0 ? (aTotal / targets.assistance) : 0;
    const iPerc = targets.waterproofing > 0 ? (iTotal / targets.waterproofing) : 0;

    // Regra da Assistência: 5% base, 10% se bater meta
    const aRate = aPerc >= 1 ? 0.10 : 0.05;
    const aComissao = aTotal * aRate;

    // Base de comissão produto (2.2%)
    const pComissaoBase = pTotal * 0.022;

    // Regra dos Aceleradores (Deve bater as 3 metas)
    let accelRate = 0;
    let level = 0;
    if (pPerc >= 1 && aPerc >= 1 && iPerc >= 1) {
      level = 1;
      accelRate = 0.006;
      if (pPerc >= 1.2 && aPerc >= 1.2 && iPerc >= 1.2) {
        level = 2;
        accelRate = 0.008;
      }
      if (pPerc >= 1.4 && aPerc >= 1.4 && iPerc >= 1.4) {
        level = 3;
        accelRate = 0.011;
      }
    }

    const accelBonus = pTotal * accelRate;
    const totalExtrasFixo = filteredSales.reduce((acc, s) => acc + (s.bonusTotal - s.comissaoProduto), 0);

    return {
      pTotal, aTotal, iTotal,
      pPerc, aPerc, iPerc,
      aComissao, aRate,
      pComissaoBase,
      accelBonus, accelRate, level,
      totalExtrasFixo,
      ganhosTotais: pComissaoBase + aComissao + accelBonus + totalExtrasFixo,
      faturamentoGeral: pTotal + aTotal + iTotal
    };
  }, [filteredSales, targets]);

  const updateTarget = (key: keyof Targets, val: string) => {
    const numeric = parseFloat(val.replace(/[^\d]/g, '')) / 100;
    setTargets(prev => ({ ...prev, [key]: isNaN(numeric) ? 0 : numeric }));
  };

  const renderContent = () => {
    const filterUI = (
      <div className="glass p-4 rounded-3xl border-white/10 mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-500 uppercase mb-1 ml-1">Início</span>
            <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
          </div>
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-500 uppercase mb-1 ml-1">Fim</span>
            <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
          </div>
          {(startDate || endDate) && (
            <button onClick={() => {setStartDate(''); setEndDate('');}} className="mt-4 p-2 text-rose-500 hover:bg-rose-500/10 rounded-xl"><FilterX size={16} /></button>
          )}
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setActiveNav(NavItem.AdicionarVenda)} className="bg-cyan-500 text-black px-6 py-3 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2"><Plus size={14} /> Lançar</button>
        </div>
      </div>
    );

    if (activeNav === NavItem.AdicionarVenda) return <SaleForm onCancel={() => setActiveNav(NavItem.Resumos)} onSubmit={saveSale} />;

    if (activeNav === NavItem.Meta) {
      return (
        <div className="content-section py-4 px-2 space-y-8">
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-3xl font-black text-white uppercase tracking-tighter">Gestão de Metas</h2>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">Configure seus objetivos de faturamento</p>
            </div>
            <Settings2 className="text-cyan-500/50" size={32} />
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {[
              { label: 'Meta Produto', key: 'product' as keyof Targets, color: 'text-cyan-400', val: stats.pTotal, perc: stats.pPerc },
              { label: 'Meta Assistência', key: 'assistance' as keyof Targets, color: 'text-emerald-400', val: stats.aTotal, perc: stats.aPerc },
              { label: 'Meta Impermeab.', key: 'waterproofing' as keyof Targets, color: 'text-fuchsia-400', val: stats.iTotal, perc: stats.iPerc },
            ].map((item) => (
              <div key={item.key} className="glass p-6 rounded-[2.5rem] relative overflow-hidden group">
                <div className="flex items-center justify-between mb-4">
                  <span className={`text-[10px] font-black uppercase tracking-widest ${item.color}`}>{item.label}</span>
                  <Target size={16} className="opacity-20" />
                </div>
                <input 
                  type="text" 
                  value={new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(targets[item.key])}
                  onChange={(e) => updateTarget(item.key, e.target.value)}
                  className="w-full bg-white/5 border border-white/5 p-4 rounded-2xl text-xl font-black text-white mono mb-6 focus:ring-1 focus:ring-white/20 outline-none"
                />
                <div className="flex items-center justify-between mb-2">
                  <span className="text-[9px] font-bold text-slate-500 uppercase">Realizado</span>
                  <span className="text-[10px] font-black text-white mono">{(item.perc * 100).toFixed(1)}%</span>
                </div>
                <div className="h-2 w-full bg-white/5 rounded-full overflow-hidden">
                  <div className={`h-full bg-current transition-all duration-1000 ${item.color}`} style={{ width: `${Math.min(item.perc * 100, 100)}%` }}></div>
                </div>
                <div className="mt-4 text-[11px] font-bold text-slate-400 mono">{formatBRL(item.val)}</div>
              </div>
            ))}
          </div>

          <div className="bg-gradient-to-br from-violet-600/20 to-cyan-500/10 border border-white/10 rounded-[3rem] p-8 md:p-12 relative overflow-hidden">
            <div className="absolute top-0 right-0 p-8 opacity-10"><Trophy size={120} /></div>
            <div className="relative z-10">
              <div className="flex items-center gap-3 mb-6">
                <Zap size={24} className="text-cyan-400 fill-current" />
                <h3 className="text-2xl font-black text-white uppercase italic">Acelerador Quantum</h3>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-10">
                {[
                  { lvl: 1, rate: '0.6%', cond: '100% Metas', active: stats.level >= 1 },
                  { lvl: 2, rate: '0.8%', cond: '120% Metas', active: stats.level >= 2 },
                  { lvl: 3, rate: '1.1%', cond: '140% Metas', active: stats.level >= 3 },
                ].map(lvl => (
                  <div key={lvl.lvl} className={`p-6 rounded-3xl border transition-all ${lvl.active ? 'bg-cyan-500 border-cyan-400 text-black shadow-lg shadow-cyan-500/20' : 'bg-white/5 border-white/5 text-slate-500'}`}>
                    <div className="text-[9px] font-black uppercase mb-1">Nível {lvl.lvl}</div>
                    <div className="text-2xl font-black mono mb-2">{lvl.rate}</div>
                    <div className="text-[8px] font-bold uppercase tracking-widest">{lvl.cond}</div>
                  </div>
                ))}
              </div>

              <div className="flex flex-col md:flex-row items-center justify-between p-6 bg-black/40 rounded-3xl border border-white/5">
                <div>
                  <div className="text-[10px] font-black text-cyan-400 uppercase mb-1">Status do Acelerador</div>
                  <div className="text-lg font-bold text-white uppercase">
                    {stats.level > 0 ? `Nível ${stats.level} Ativado!` : 'Aguardando Metas...'}
                  </div>
                </div>
                <div className="text-center md:text-right mt-4 md:mt-0">
                  <div className="text-[10px] font-black text-slate-500 uppercase mb-1">Ganhos de Aceleração</div>
                  <div className="text-3xl font-black text-cyan-400 mono">{formatBRL(stats.accelBonus)}</div>
                </div>
              </div>
            </div>
          </div>
        </div>
      );
    }

    return (
      <div className="content-section py-4 px-2 space-y-6">
        {!isOnline && (
          <div className="bg-amber-500/10 border border-amber-500/20 p-4 rounded-2xl flex items-center gap-3 text-amber-500 mb-6">
            <WifiOff size={18} />
            <span className="text-[10px] font-black uppercase tracking-widest">Modo Offline - Dados salvos localmente</span>
          </div>
        )}
        {filterUI}

        {/* Painel Principal de Ganhos */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="glass p-6 rounded-[2rem] border-white/10">
            <span className="text-[10px] font-black text-cyan-400 uppercase mb-3 block">Faturamento</span>
            <h3 className="text-2xl font-black text-white mono">{formatBRL(stats.faturamentoGeral)}</h3>
          </div>
          <div className="bg-gradient-to-br from-emerald-600 to-teal-700 p-6 rounded-[2rem] shadow-xl">
            <div className="flex items-center justify-between mb-3">
              <span className="text-[10px] font-black text-white/80 uppercase">Comis. Assistência</span>
              <span className="bg-white/20 px-2 py-0.5 rounded text-[8px] font-black text-white">{(stats.aRate * 100)}%</span>
            </div>
            <h3 className="text-2xl font-black text-white mono">{formatBRL(stats.aComissao)}</h3>
          </div>
          <div className="glass p-6 rounded-[2rem]">
            <span className="text-[10px] font-black text-violet-400 uppercase mb-3 block">Acelerador Prod.</span>
            <h3 className="text-2xl font-black text-white mono">{formatBRL(stats.accelBonus)}</h3>
          </div>
          <div className="bg-white/5 p-6 rounded-[2rem] border border-cyan-500/30">
            <span className="text-[10px] font-black text-emerald-400 uppercase mb-3 block">Ganhos Totais</span>
            <h3 className="text-2xl font-black text-emerald-400 mono">{formatBRL(stats.ganhosTotais)}</h3>
          </div>
        </div>

        {activeNav === NavItem.Resumos && (
          <div className="space-y-8 mt-10">
            <div className="flex items-center gap-3">
               <TrendingUp className="text-cyan-400" size={20} />
               <h3 className="text-lg font-black text-white uppercase tracking-tighter">Fluxo de Conversão</h3>
            </div>
            <FunnelChart opportunities={MOCK_OPPORTUNITIES} />
            <div className="overflow-x-auto pb-4 scrollbar-hide">
              <PipelineView opportunities={MOCK_OPPORTUNITIES} />
            </div>
          </div>
        )}

        {(activeNav === NavItem.ResumoPedido || activeNav === NavItem.ResumoServico) && (
          <div ref={reportContentRef} data-report-container className="glass rounded-[2.5rem] p-6 md:p-10 bg-[#05020a] mt-8">
             <div className="flex flex-col md:flex-row md:items-center justify-between mb-10 gap-6">
                <div>
