                         ))}
                         {sale.valorAssistencia > 0 && (
                            <span className="text-[9px] font-black bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 px-3 py-1.5 rounded-xl uppercase tracking-widest">Assis: {formatBRL(sale.valorAssistencia)}</span>
                         )}
                      </div>
                      <div className="flex items-center gap-14 w-full lg:w-auto justify-between lg:justify-end border-t lg:border-t-0 border-white/5 pt-6 lg:pt-0">
