                            <div className="text-[9px] text-slate-600 font-black uppercase tracking-widest mb-1">Faturamento</div>
                            <div className="text-xl font-black text-white mono">{formatBRL(sale.total)}</div>
                         </div>
                         <div className="text-right">
                            <div className="text-[9px] text-emerald-500 font-black uppercase tracking-widest mb-1">Bônus</div>
                            <div className="text-2xl font-black text-emerald-400 mono">{formatBRL(sale.bonusTotal)}</div>
                         </div>
                         <ChevronRight className="text-slate-800 group-hover:text-cyan-400 transition-colors hidden lg:block" size={20} />
                      </div>
                    </div>
                  ))}
               </div>
             )}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-[#05020a] overflow-hidden">
      <div className={`transition-all duration-500 z-50 flex-shrink-0 ${isSidebarCollapsed ? 'w-24' : 'w-64'}`}>
