                <button key={item.id} onClick={() => { setActiveNav(item.id); setIsFabOpen(false); }} className="flex items-center gap-4 bg-[#0a051a]/95 backdrop-blur-3xl border border-white/10 px-8 py-5 rounded-[2rem] text-white hover:bg-cyan-500 hover:text-black transition-all group shadow-2xl whitespace-nowrap">
                  <span className="text-cyan-400 group-hover:text-black transition-colors">{item.icon}</span>
