          <button onClick={() => setIsFabOpen(!isFabOpen)} className={`w-16 h-16 rounded-[2rem] flex items-center justify-center shadow-2xl transition-all duration-500 animate-pulse-neon floating-action ${isFabOpen ? 'bg-rose-500 rotate-45 text-white' : 'bg-cyan-500 text-black rotate-0'}`}>
