import React, { useState, useRef, useEffect, useMemo } from 'react';
import html2canvas from 'html2canvas';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import OpportunityCard from './components/OpportunityCard';
import PipelineView from './components/PipelineView';
import FunnelChart from './components/FunnelChart';
import SaleForm from './components/SaleForm';
import { NavItem, Sale, Targets, LevelConfig } from './types';
import { MOCK_OPPORTUNITIES, NAVIGATION_ITEMS } from './constants';
import { 
  Plus, 
  X, 
  History,
  Search,
  FilterX,
  Target,
  Zap,
  TrendingUp,
  Settings2,
  ShieldCheck,
  CheckCircle2,
  Lock,
  Wrench,
  Droplets,
  Layers,
  Layout,
  Star,
  Construction,
  Wallet
} from 'lucide-react';

const STORAGE_KEY = 'vc_quantum_data_v2';
const TARGETS_KEY = 'vc_quantum_targets_v4';

const App: React.FC = () => {
  const [activeNav, setActiveNav] = useState<NavItem>(NavItem.Resumos);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isFabOpen, setIsFabOpen] = useState(false);
  const [savedSales, setSavedSales] = useState<Sale[]>([]);

  const [targets, setTargets] = useState<Targets>({
    product: 50000,
    assistance: 3000,
    waterproofing: 2000,
    levels: {
      1: { threshold: 100, rate: 0.6 },
      2: { threshold: 120, rate: 0.8 },
      3: { threshold: 140, rate: 1.1 }
    }
  });

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  const mainRef = useRef<HTMLDivElement>(null);
  const reportContentRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const rawData = localStorage.getItem(STORAGE_KEY);
    if (rawData) {
      try { setSavedSales(JSON.parse(rawData)); } catch (e) {}
    }

    const rawTargets = localStorage.getItem(TARGETS_KEY);
    if (rawTargets) {
      try { setTargets(JSON.parse(rawTargets)); } catch (e) {}
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(savedSales));
  }, [savedSales]);

  useEffect(() => {
    localStorage.setItem(TARGETS_KEY, JSON.stringify(targets));
  }, [targets]);

  const saveSale = (newSaleData: any) => {
    const saleObj: Sale = {
      numeroPedido: newSaleData.pedido,
      valorProduto: newSaleData.produto,
      valorAssistencia: newSaleData.assistencia,
      valorImpermeabilizacao: newSaleData.impermeabilizacao,
      total: newSaleData.total,
      bonusTotal: newSaleData.bonusTotal,
      comissaoProduto: newSaleData.comissaoProduto,
      servicosExtras: newSaleData.servicosExtras,
      data: new Date().toLocaleDateString('pt-BR'),
      timestamp: Date.now()
    };
    setSavedSales(prev => [saleObj, ...prev]);
    setActiveNav(NavItem.ResumoPedido);
  };

  const formatBRL = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const filteredSales = useMemo(() => {
    return savedSales.filter(sale => {
      if (!startDate && !endDate) return true;
      const saleDate = new Date(sale.timestamp || 0);
      saleDate.setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate + 'T00:00:00') : null;
      const end = endDate ? new Date(endDate + 'T23:59:59') : null;
      return !( (start && saleDate < start) || (end && saleDate > end) );
    });
  }, [savedSales, startDate, endDate]);

  const stats = useMemo(() => {
    const pTotal = filteredSales.reduce((acc, s) => acc + s.valorProduto, 0);
    const aTotal = filteredSales.reduce((acc, s) => acc + s.valorAssistencia, 0);
    const iTotal = filteredSales.reduce((acc, s) => acc + s.valorImpermeabilizacao, 0);

    const pPerc = targets.product > 0 ? (pTotal / targets.product) : 0;
    const aPerc = targets.assistance > 0 ? (aTotal / targets.assistance) : 0;
    const iPerc = targets.waterproofing > 0 ? (iTotal / targets.waterproofing) : 0;

    const aRate = aPerc >= 1 ? 0.10 : 0.05;
    const aComissao = aTotal * aRate;
    const pComissaoBase = pTotal * 0.022;

    let accelRate = 0;
    let level = 0;

    [3, 2, 1].forEach(lvlNum => {
      if (level > 0) return;
      const lNum = lvlNum as 1 | 2 | 3;
      const thresh = targets.levels[lNum].threshold / 100;
      if (pPerc >= thresh && aPerc >= thresh && iPerc >= thresh) {
        level = lNum;
        accelRate = targets.levels[lNum].rate / 100;
      }
    });

    const accelBonus = pTotal * accelRate;

    const serviceCounts = {
      'Montagem': 0,
      'Lavagem': 0,
      'Almofada': 0,
      'Pés G-Roupa': 0,
      'Impermeab.': 0
    };
    const serviceValues = {
      'Montagem': 10,
      'Lavagem': 40,
      'Almofada': 10,
      'Pés G-Roupa': 7,
      'Impermeab.': 40
    };

    filteredSales.forEach(s => {
      s.servicosExtras.forEach(ex => {
        if (serviceCounts.hasOwnProperty(ex)) {
          // @ts-ignore
          serviceCounts[ex]++;
        }
      });
    });

    const totalExtrasFixo = Object.keys(serviceCounts).reduce((acc, key) => {
      // @ts-ignore
      return acc + (serviceCounts[key] * serviceValues[key]);
    }, 0);

    return {
      pTotal, aTotal, iTotal,
      pPerc, aPerc, iPerc,
      aComissao, aRate,
      pComissaoBase,
      accelBonus, accelRate, level,
      totalExtrasFixo,
      serviceCounts,
      serviceValues,
      ganhosTotais: pComissaoBase + aComissao + accelBonus + totalExtrasFixo,
      faturamentoGeral: pTotal + aTotal + iTotal
    };
  }, [filteredSales, targets]);

  const updateTargetValue = (key: 'product' | 'assistance' | 'waterproofing', val: string) => {
    const numeric = parseFloat(val.replace(/[^\d]/g, '')) / 100;
    setTargets(prev => ({ ...prev, [key]: isNaN(numeric) ? 0 : numeric }));
  };

  const updateLevelConfig = (lvl: 1 | 2 | 3, field: keyof LevelConfig, val: string) => {
    const numeric = parseFloat(val.replace(/[^\d.,]/g, '').replace(',', '.'));
    setTargets(prev => ({
      ...prev,
      levels: {
        ...prev.levels,
        [lvl]: { ...prev.levels[lvl], [field]: isNaN(numeric) ? 0 : numeric }
      }
    }));
  };

  const renderContent = () => {
    const filterUI = (
      <div className="glass p-4 rounded-3xl border-white/10 mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-500 uppercase mb-1 ml-1">Filtro de Período</span>
            <div className="flex items-center gap-2">
               <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
               <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
            </div>
          </div>
          {(startDate || endDate) && (
            <button onClick={() => {setStartDate(''); setEndDate('');}} className="mt-4 p-2 text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all active:scale-90"><FilterX size={16} /></button>
          )}
        </div>
        <button onClick={() => setActiveNav(NavItem.AdicionarVenda)} className="bg-cyan-500 text-black px-6 py-3 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 shadow-lg shadow-cyan-500/10 transition-transform active:scale-95"><Plus size={14} /> Novo Pedido</button>
      </div>
    );

    if (activeNav === NavItem.AdicionarVenda) return <SaleForm onCancel={() => setActiveNav(NavItem.Resumos)} onSubmit={saveSale} />;

    // EM BREVE para Clientes e Fluxo
    if (activeNav === NavItem.Clientes || activeNav === NavItem.Processos || activeNav === NavItem.Relatorios) {
      return (
        <div className="h-[70vh] flex flex-col items-center justify-center text-center animate-in zoom-in-95 duration-700">
           <div className="relative mb-10">
              <div className="absolute inset-0 bg-cyan-500 blur-[80px] opacity-20 animate-pulse"></div>
              <div className="p-8 bg-white/5 rounded-[2.5rem] border border-white/10 relative z-10 shadow-2xl">
                <Construction size={100} className="text-cyan-400" />
              </div>
           </div>
           <h2 className="text-5xl font-black text-white uppercase tracking-tighter italic mb-4">Em Breve</h2>
           <p className="text-slate-500 font-bold uppercase tracking-[0.4em] max-w-sm mx-auto leading-relaxed">
             Estamos refinando as engrenagens para este módulo do ecossistema V&C.
           </p>
           <button onClick={() => setActiveNav(NavItem.Resumos)} className="mt-12 px-10 py-5 bg-cyan-500 text-black rounded-2xl font-black text-[10px] uppercase tracking-widest hover:scale-105 transition-all shadow-xl shadow-cyan-500/20">Voltar ao Painel</button>
        </div>
      );
    }

    if (activeNav === NavItem.ResumoServico) {
      return (
        <div className="content-section py-4 px-2 space-y-12 animate-in slide-in-from-right-10 duration-500">
           <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
              <div>
                <div className="flex items-center gap-2 text-emerald-400 mb-2">
                  <Wrench size={18} />
                  <span className="text-[10px] font-black uppercase tracking-[0.4em]">Relatório de Serviços Detalhado</span>
                </div>
                <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none">Meus Serviços</h2>
              </div>
              <div className="glass p-8 rounded-[2.5rem] flex flex-col items-end border-emerald-500/20 bg-emerald-500/[0.02]">
                 <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1">Total Acumulado</span>
                 <span className="text-4xl font-black text-white mono">{formatBRL(stats.totalExtrasFixo)}</span>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {[
                { label: 'Montagem', icon: <Layout />, count: stats.serviceCounts['Montagem'], val: 10, color: 'text-blue-400', bg: 'bg-blue-400/10' },
                { label: 'Lavagem', icon: <Droplets />, count: stats.serviceCounts['Lavagem'], val: 40, color: 'text-cyan-400', bg: 'bg-cyan-400/10' },
                { label: 'Almofada', icon: <Star />, count: stats.serviceCounts['Almofada'], val: 10, color: 'text-amber-400', bg: 'bg-amber-400/10' },
                { label: 'Pés G-Roupa', icon: <Layers />, count: stats.serviceCounts['Pés G-Roupa'], val: 7, color: 'text-fuchsia-400', bg: 'bg-fuchsia-400/10' },
                { label: 'Impermeab.', icon: <ShieldCheck />, count: stats.serviceCounts['Impermeab.'], val: 40, color: 'text-emerald-400', bg: 'bg-emerald-400/10' },
              ].map((s, idx) => (
                <div key={idx} className="glass group p-10 rounded-[3rem] border-white/5 hover:border-white/20 transition-all flex flex-col relative overflow-hidden">
                   <div className={`absolute top-0 right-0 p-8 opacity-5 group-hover:scale-110 transition-transform ${s.color}`}>{s.icon}</div>
                   <div className={`w-14 h-14 rounded-2xl ${s.bg} flex items-center justify-center mb-8 ${s.color}`}>
                      {React.cloneElement(s.icon as React.ReactElement, { size: 28 })}
                   </div>
                   <h4 className="text-[12px] font-black text-white uppercase tracking-widest mb-6">{s.label}</h4>
                   <div className="flex items-end justify-between">
                      <div>
                        <div className="text-5xl font-black text-white mono leading-none">{s.count}</div>
                        <div className="text-[10px] font-bold text-slate-500 uppercase mt-2 tracking-widest">Unidades</div>
                      </div>
                      <div className="text-right">
                         <div className="text-[10px] font-black text-slate-500 uppercase mb-1">Un: {formatBRL(s.val)}</div>
                         <div className={`text-2xl font-black mono ${s.color}`}>{formatBRL(s.count * s.val)}</div>
                      </div>
                   </div>
                </div>
              ))}
           </div>

           <div className="p-12 glass rounded-[3.5rem] border-white/10 flex flex-col md:flex-row items-center justify-between gap-10">
              <div className="flex items-center gap-6">
                 <div className="w-20 h-20 rounded-[2rem] bg-white/5 flex items-center justify-center text-white/10">
                    <History size={40} />
                 </div>
                 <div>
                    <h5 className="text-xl font-black text-white uppercase tracking-tight italic">Consolidado do Período</h5>
                    <p className="text-xs text-slate-500 font-bold uppercase mt-1">Visão clara dos ganhos extras amarrados.</p>
                 </div>
              </div>
              <div className="flex gap-4">
                 <div className="px-10 py-6 bg-white/5 rounded-3xl text-center border border-white/5">
                    <div className="text-[10px] font-black text-slate-500 uppercase mb-1">Total Geral de Serviços</div>
                    <div className="text-3xl font-black text-white mono">{Object.values(stats.serviceCounts).reduce((a, b) => a + b, 0)}</div>
                 </div>
              </div>
           </div>
        </div>
      );
    }

    if (activeNav === NavItem.Meta) {
      return (
        <div className="content-section py-4 px-2 space-y-12 animate-in fade-in zoom-in-95 duration-500">
          <div>
            <div className="flex items-center gap-2 text-cyan-400 mb-2">
              <Target size={18} />
              <span className="text-[10px] font-black uppercase tracking-[0.4em]">Configuração de Gatilhos V&C</span>
            </div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter">Gerenciar Metas</h2>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {[
              { label: 'Meta Produto (100%)', key: 'product' as const, color: 'text-cyan-400', current: stats.pTotal },
              { label: 'Meta Assistência (100%)', key: 'assistance' as const, color: 'text-emerald-400', current: stats.aTotal },
              { label: 'Meta Impermeab. (100%)', key: 'waterproofing' as const, color: 'text-fuchsia-400', current: stats.iTotal },
            ].map((item) => (
              <div key={item.key} className="glass p-8 rounded-[3rem] border-white/5">
                <div className="flex items-center justify-between mb-6">
                  <span className={`text-[10px] font-black uppercase tracking-[0.2em] ${item.color}`}>{item.label}</span>
                  <Settings2 size={16} className="text-slate-600" />
                </div>
                <div className="relative mb-6">
                   <span className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-600 text-xs font-black">R$</span>
                   <input 
                      type="text" 
                      value={new Intl.NumberFormat('pt-BR', { minimumFractionDigits: 2 }).format(targets[item.key])}
                      onChange={(e) => updateTargetValue(item.key, e.target.value)}
                      className="w-full bg-white/5 border border-white/5 pl-12 pr-4 py-5 rounded-2xl text-2xl font-black text-white mono outline-none focus:ring-1 focus:ring-cyan-500/50"
                    />
                </div>
                <div className="flex items-center justify-between text-[11px] font-bold text-slate-500">
                   <span className="uppercase">Realizado:</span>
                   <span className="text-white mono">{formatBRL(item.current)}</span>
                </div>
              </div>
            ))}
          </div>

          <div className="space-y-8">
            <div className="flex items-center gap-3">
               <Zap className="text-cyan-400 fill-current" size={24} />
               <h3 className="text-2xl font-black text-white uppercase italic tracking-tighter">Aceleradores Quantum</h3>
            </div>

            <div className="grid grid-cols-1 gap-8">
               {[1, 2, 3].map((num) => {
                 const lvl = num as 1 | 2 | 3;
                 const threshold = targets.levels[lvl].threshold;
                 const rate = targets.levels[lvl].rate;

                 const reqP = targets.product * (threshold / 100);
                 const reqA = targets.assistance * (threshold / 100);
                 const reqI = targets.waterproofing * (threshold / 100);

                 const pOk = stats.pTotal >= reqP;
                 const aOk = stats.aTotal >= reqA;
                 const iOk = stats.iTotal >= reqI;
                 const lvlActive = pOk && aOk && iOk;

                 return (
                    <div key={lvl} className={`glass rounded-[3.5rem] p-10 border transition-all duration-700 relative overflow-hidden ${lvlActive ? 'border-cyan-500/50 bg-cyan-500/[0.04]' : 'border-white/5 opacity-60'}`}>
                       <div className="flex flex-col xl:flex-row items-start xl:items-center justify-between gap-10 relative z-10">
                          <div className="flex items-center gap-8">
                             <div className={`w-20 h-20 rounded-[2.5rem] flex items-center justify-center text-3xl font-black ${lvlActive ? 'bg-cyan-500 text-black shadow-2xl shadow-cyan-500/30' : 'bg-white/5 text-slate-700'}`}>
                                0{lvl}
                             </div>
                             <div>
                                <h4 className={`text-2xl font-black uppercase italic ${lvlActive ? 'text-cyan-400' : 'text-white/40'}`}>Nível {lvl}</h4>
                                <div className="flex items-center gap-3 mt-2">
                                   <span className="text-[11px] font-black text-slate-600 uppercase">Gatilho:</span>
                                   <div className="flex items-center bg-white/5 rounded-xl px-3 py-1.5 border border-white/5">
                                      <input 
                                         type="text" 
                                         value={threshold} 
                                         onChange={(e) => updateLevelConfig(lvl, 'threshold', e.target.value)}
                                         className="w-12 bg-transparent text-white font-black text-lg text-center outline-none"
                                      />
                                      <span className="text-white text-sm font-black">%</span>
                                   </div>
                                </div>
                             </div>
                          </div>

                          <div className="flex-1 grid grid-cols-1 md:grid-cols-3 gap-6 w-full">
                             {[
                               { label: 'Valor Produto', req: reqP, ok: pOk, color: 'text-cyan-400' },
                               { label: 'Valor Assistência', req: reqA, ok: aOk, color: 'text-emerald-400' },
                               { label: 'Valor Impermeab.', req: reqI, ok: iOk, color: 'text-fuchsia-400' },
                             ].map((req, idx) => (
                                <div key={idx} className={`p-6 rounded-[2rem] border ${req.ok ? 'bg-emerald-500/5 border-emerald-500/20' : 'bg-white/5 border-white/5'}`}>
                                   <div className="flex items-center justify-between mb-2">
                                      <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{req.label}</span>
                                      {req.ok ? <CheckCircle2 size={14} className="text-emerald-400" /> : <Lock size={14} className="text-slate-800" />}
                                   </div>
                                   <div className={`text-xl font-black mono ${req.ok ? req.color : 'text-white/20'}`}>{formatBRL(req.req)}</div>
                                </div>
                             ))}
                          </div>

                          <div className="text-center xl:text-right bg-white/5 p-8 rounded-[2.5rem] border border-white/10 min-w-[200px]">
                             <span className="text-[10px] font-black text-slate-500 uppercase block mb-2 tracking-widest">Bônus Prod. %</span>
                             <div className="flex items-center justify-center xl:justify-end gap-2">
                                <input 
                                   type="text" 
                                   value={rate} 
                                   onChange={(e) => updateLevelConfig(lvl, 'rate', e.target.value)}
                                   className="w-20 bg-transparent text-4xl font-black text-cyan-400 text-right outline-none mono"
                                />
                                <span className="text-cyan-400 text-3xl font-black">%</span>
                             </div>
                          </div>
                       </div>
                    </div>
                 );
               })}
            </div>
          </div>
        </div>
      );
    }

    return (
      <div className="content-section py-4 px-2 space-y-8 animate-in slide-in-from-bottom-6 duration-700">
        {filterUI}

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          <div className="glass p-8 rounded-[3rem] border-white/10">
            <span className="text-[11px] font-black text-cyan-400 uppercase mb-5 block">Faturamento Global</span>
            <h3 className="text-3xl font-black text-white mono tracking-tighter">{formatBRL(stats.faturamentoGeral)}</h3>
          </div>
          <div className="bg-gradient-to-br from-emerald-600 to-teal-800 p-8 rounded-[3rem] shadow-2xl relative overflow-hidden group">
            <div className="absolute -right-8 -bottom-8 opacity-20 group-hover:scale-125 transition-transform duration-1000"><ShieldCheck size={160} /></div>
            <div className="flex items-center justify-between mb-5 relative z-10">
              <span className="text-[11px] font-black text-white/90 uppercase">Comis. Assistência</span>
              <span className="bg-white/25 px-2.5 py-1 rounded-xl text-[9px] font-black text-white">{(stats.aRate * 100)}%</span>
            </div>
            <h3 className="text-3xl font-black text-white mono tracking-tighter relative z-10">{formatBRL(stats.aComissao)}</h3>
          </div>
          <div className="glass p-8 rounded-[3rem] relative group border-violet-500/20">
            <div className="absolute top-8 right-8 p-1.5 bg-violet-500/20 rounded-xl text-violet-400"><TrendingUp size={18}/></div>
            <span className="text-[11px] font-black text-violet-400 uppercase mb-5 block">Bônus Quantum (LVL {stats.level})</span>
            <h3 className="text-3xl font-black text-white mono tracking-tighter">{formatBRL(stats.accelBonus)}</h3>
          </div>
          <div className="bg-white/5 p-8 rounded-[3rem] border border-cyan-500/30 relative">
            <div className="absolute -left-1 top-1/2 -translate-y-1/2 w-1.5 h-16 bg-cyan-400 rounded-full blur-[2px]"></div>
