             ) : (
               <div className="space-y-6">
                  {filteredSales.map((sale, i) => (
                    <div key={i} className="flex flex-col lg:flex-row items-center justify-between p-10 bg-white/5 border border-white/5 rounded-[2.5rem] gap-10 hover:bg-white/[0.08] transition-all group">
                      <div className="flex items-center gap-8 w-full lg:w-1/3">
                         <div className="w-16 h-16 rounded-[1.5rem] bg-white/5 flex items-center justify-center text-cyan-400 group-hover:bg-cyan-500 group-hover:text-black transition-all shadow-xl"><Search size={28} /></div>
                         <div>
                            <div className="text-xs font-black text-slate-500 uppercase tracking-widest mb-1.5">ID Pedido</div>
