                            <div className="text-[10px] text-slate-600 mono mt-2 font-bold uppercase">{sale.data}</div>
                         </div>
                      </div>
                      <div className="flex-1 w-full lg:w-auto flex flex-wrap gap-3">
                         {sale.servicosExtras?.map((ex, idx) => (
                           <span key={idx} className="text-[10px] font-black bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 px-4 py-2 rounded-2xl uppercase tracking-widest">{ex}</span>
                         ))}
                         {sale.valorAssistencia > 0 && <span className="text-[10px] font-black bg-cyan-500/10 text-cyan-400 border border-cyan-500/20 px-4 py-2 rounded-2xl uppercase tracking-widest">Assis: {formatBRL(sale.valorAssistencia)}</span>}
                      </div>
                      <div className="flex items-center gap-16 w-full lg:w-auto justify-between lg:justify-end">
                         <div className="text-right">
                            <div className="text-[10px] font-black text-slate-600 uppercase mb-2">Venda</div>
                            <div className="text-2xl font-black text-white mono">{formatBRL(sale.total)}</div>
                         </div>
                         <div className="text-right">
                            <div className="text-[10px] font-black text-emerald-500 uppercase mb-2">Ganhos</div>
                            <div className="text-3xl font-black text-emerald-400 mono">{formatBRL(sale.bonusTotal)}</div>
