import React, { useState, useEffect, useRef } from 'react';
import { Save, X, Terminal, CheckSquare, Square, Percent } from 'lucide-react';

interface SaleFormProps {
  onCancel: () => void;
  onSubmit: (sale: any) => void;
}

const BONUS_VALUES = {
  montagem: 10,
  lavagem: 40,
  almofada: 10,
  pes_guarda_roupa: 7,
  impermeabilizacao_bonus: 40
};

const SaleForm: React.FC<SaleFormProps> = ({ onCancel, onSubmit }) => {
  const [pedido, setPedido] = useState('');
  const [produto, setProduto] = useState<number>(0);
  const [assistencia, setAssistencia] = useState<number>(0);
  const [impermeabilizacao, setImpermeabilizacao] = useState<number>(0);
  const [total, setTotal] = useState(0);

  const [extras, setExtras] = useState({
    montagem: false,
    lavagem: false,
    almofada: false,
    pes_guarda_roupa: false,
    impermeabilizacao_bonus: false
  });

  const firstInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setTotal(produto + assistencia + impermeabilizacao);
  }, [produto, assistencia, impermeabilizacao]);

  useEffect(() => {
    if (firstInputRef.current) {
      firstInputRef.current.focus();
    }
  }, []);

  const calculateBonusFixo = () => {
    let bonusTotal = 0;
    if (extras.montagem) bonusTotal += BONUS_VALUES.montagem;
    if (extras.lavagem) bonusTotal += BONUS_VALUES.lavagem;
    if (extras.almofada) bonusTotal += BONUS_VALUES.almofada;
    if (extras.pes_guarda_roupa) bonusTotal += BONUS_VALUES.pes_guarda_roupa;
    if (extras.impermeabilizacao_bonus) bonusTotal += BONUS_VALUES.impermeabilizacao_bonus;
    return bonusTotal;
  };

  const comissaoProdutoBase = produto * 0.022; 
  const comissaoAssistenciaBase = assistencia * 0.05; // 5% base no formulário individual

  const getSelectedLabels = () => {
    const labels: string[] = [];
    if (extras.montagem) labels.push("Montagem");
    if (extras.lavagem) labels.push("Lavagem");
    if (extras.almofada) labels.push("Almofada");
    if (extras.pes_guarda_roupa) labels.push("Pés G-Roupa");
    if (extras.impermeabilizacao_bonus) labels.push("Impermeab.");
    return labels;
  };

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('pt-BR', {
      style: 'currency',
      currency: 'BRL',
    }).format(val);
  };

  const handleInputChange = (setter: React.Dispatch<React.SetStateAction<number>>, value: string) => {
    const numericValue = parseFloat(value.replace(/[^\d]/g, '')) / 100;
    setter(isNaN(numericValue) ? 0 : numericValue);
  };

  const toggleExtra = (key: keyof typeof extras) => {
    setExtras(prev => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <div className="w-full max-w-4xl mx-auto animate-in zoom-in-95 duration-500 pb-20">
      <div className="glass rounded-[3rem] overflow-hidden shadow-[0_0_80px_rgba(0,0,0,0.6)] border border-white/10 relative">
        <div className="absolute top-0 right-0 w-96 h-96 bg-cyan-500/5 blur-[100px] rounded-full -mr-48 -mt-48"></div>

        <div className="p-6 md:p-12 relative z-10">
          <div className="flex items-center justify-between mb-10">
            <div>
              <div className="flex items-center gap-3 text-cyan-400 mb-2">
                <Terminal size={18} className="animate-pulse" />
                <span className="text-[9px] font-black uppercase tracking-[0.4em]">Módulo Quantum v5.0</span>
              </div>
              <h2 className="text-2xl md:text-3xl font-extrabold text-white tracking-tighter uppercase leading-none">Lançar Nova Venda</h2>
            </div>
            <button onClick={onCancel} className="bg-white/5 p-3 rounded-xl text-slate-400 hover:text-white transition-all">
              <X size={20} />
            </button>
          </div>

          <form className="space-y-8" onSubmit={(e) => {
            e.preventDefault();
            onSubmit({ 
              pedido, 
              produto, 
              assistencia, 
              impermeabilizacao, 
              total,
              comissaoProduto: comissaoProdutoBase,
              bonusTotal: calculateBonusFixo() + comissaoProdutoBase + comissaoAssistenciaBase,
              servicosExtras: getSelectedLabels()
            });
          }}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">ID Pedido</label>
                <input
                  ref={firstInputRef}
                  type="text"
                  required
                  autoCapitalize="characters"
                  value={pedido}
                  onChange={(e) => setPedido(e.target.value.toUpperCase())}
                  placeholder="EX: VC1234"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl focus:ring-1 focus:ring-cyan-500/50 transition-all text-white mono font-bold text-lg"
                />
              </div>

              <div className="space-y-3">
                <div className="flex justify-between items-center px-1">
                   <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">Valor Produto</label>
                   {produto > 0 && (
                     <div className="flex items-center gap-1.5 text-cyan-400 font-black text-[10px] animate-in slide-in-from-right-2">
                        <Percent size={10} /> + {formatCurrency(comissaoProdutoBase)} (2.2%)
                     </div>
                   )}
                </div>
                <input
                  type="text"
                  inputMode="decimal"
                  required
                  value={produto === 0 ? "" : formatCurrency(produto)}
