                  <div className="flex flex-col items-center md:items-start">
                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-slate-400 mb-1">Venda Bruta Total</span>
                    <div className="text-3xl md:text-4xl font-black text-white mono leading-none">{formatCurrency(total)}</div>
                  </div>

                  <div className="flex flex-col items-center md:items-end gap-2 border-l border-white/10 pl-10">
                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-emerald-400 mb-1">Meus Ganhos (2.2% + Bônus)</span>
                    <div className="text-3xl md:text-4xl font-black text-emerald-400 mono leading-none">
                      {formatCurrency(calculateBonusFixo() + comissaoProdutoBase + comissaoAssistenciaBase)}
                    </div>
