            </div>

            <button type="submit" className="w-full bg-cyan-500 text-black py-6 rounded-2xl font-black text-sm hover:scale-[1.01] active:scale-[0.99] transition-all flex items-center justify-center gap-3 shadow-2xl shadow-cyan-500/20">
              <Save size={20} /> FINALIZAR E SOMAR GANHOS
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

