                         ))}
                         {sale.valorAssistencia > 0 && <span className="text-[10px] font-black bg-blue-500/10 text-blue-400 border border-blue-500/20 px-4 py-2 rounded-2xl uppercase tracking-widest">Assis: {formatBRL(sale.valorAssistencia)}</span>}
                      </div>

                      <div className="flex items-center gap-16 w-full lg:w-auto justify-between lg:justify-end">
                         <div className="text-right">
                            <div className="text-[10px] font-black text-slate-600 uppercase mb-2">Venda</div>
                            <div className="text-2xl font-black text-white mono">{formatBRL(sale.total)}</div>
                         </div>
                         <div className="text-right">
                            <div className="text-[10px] font-black text-emerald-500 uppercase mb-2">Ganhos</div>
                            <div className="text-3xl font-black text-emerald-400 mono">{formatBRL(sale.bonusTotal)}</div>
                         </div>
                      </div>
                    </div>
                  ))}
               </div>
             )}
          </div>
        )}

        {activeNav === NavItem.Resumos && (
          <div className="space-y-12 mt-16">
            <div className="flex items-center gap-4">
               <div className="w-1.5 h-10 bg-cyan-500 rounded-full shadow-[0_0_15px_#22d3ee]"></div>
               <div>
                  <h3 className="text-3xl font-black text-white uppercase tracking-tighter leading-none italic">Resumo de Operação</h3>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">Status do pipeline e fluxo comercial</p>
               </div>
            </div>
            <FunnelChart opportunities={MOCK_OPPORTUNITIES} />
            <div className="overflow-x-auto pb-4 scrollbar-hide">
              <PipelineView opportunities={MOCK_OPPORTUNITIES} />
