          <div className="max-w-[1400px] mx-auto w-full">{renderContent()}</div>
        </main>
        <div className="fixed bottom-10 right-10 z-[100]">
          {isFabOpen && (
            <div className="absolute bottom-24 right-0 flex flex-col gap-4 animate-in slide-in-from-bottom-10 fade-in duration-300">
              {NAVIGATION_ITEMS.map((item) => (
                <button key={item.id} onClick={() => { setActiveNav(item.id); setIsFabOpen(false); }} className="flex items-center gap-4 bg-[#0a051a]/98 backdrop-blur-3xl border border-white/10 px-10 py-6 rounded-[2.5rem] text-white hover:bg-cyan-500 hover:text-black transition-all group shadow-2xl whitespace-nowrap">
                  <span className="text-cyan-400 group-hover:text-black transition-colors">{item.icon}</span>
