            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">ID Pedido</label>
                <input
                  ref={firstInputRef}
                  type="text"
                  required
                  autoCapitalize="characters"
                  value={pedido}
                  onChange={(e) => setPedido(e.target.value.toUpperCase())}
                  placeholder="EX: VC1234"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl focus:ring-1 focus:ring-cyan-500/50 transition-all text-white mono font-bold text-lg"
                />
              </div>

              <div className="space-y-3">
                <div className="flex justify-between items-center px-1">
                   <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">Valor Produto</label>
                   {produto > 0 && (
                     <div className="flex items-center gap-1.5 text-cyan-400 font-black text-[10px] animate-in slide-in-from-right-2">
                        <Percent size={10} /> + {formatCurrency(comissaoProdutoBase)} (2.2%)
                     </div>
                   )}
                </div>
                <input
                  type="text"
                  inputMode="decimal"
                  required
                  value={produto === 0 ? "" : formatCurrency(produto)}
                  onChange={(e) => handleInputChange(setProduto, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl focus:ring-1 focus:ring-violet-500/50 transition-all text-white mono font-bold text-lg"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Valor Assistência (Comis. 5%)</label>
                <input
                  type="text"
                  inputMode="decimal"
                  value={assistencia === 0 ? "" : formatCurrency(assistencia)}
                  onChange={(e) => handleInputChange(setAssistencia, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl focus:ring-1 focus:ring-emerald-500/50 transition-all text-white mono"
                />
              </div>
              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] ml-1">Impermeabilização</label>
                <input
                  type="text"
                  inputMode="decimal"
                  value={impermeabilizacao === 0 ? "" : formatCurrency(impermeabilizacao)}
                  onChange={(e) => handleInputChange(setImpermeabilizacao, e.target.value)}
                  placeholder="R$ 0,00"
                  className="w-full bg-white/5 border border-white/10 p-5 rounded-2xl focus:ring-1 focus:ring-fuchsia-500/50 transition-all text-white mono"
                />
              </div>
            </div>

            <div className="bg-white/5 border border-white/5 p-8 rounded-[2.5rem]">
              <div className="flex items-center gap-3 mb-6">
                <CheckSquare size={16} className="text-emerald-400" />
                <h4 className="text-[10px] font-black text-white uppercase tracking-[0.3em]">Serviços Extras (Bônus Fixo)</h4>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
                {[
                  { id: 'montagem', label: 'Montagem', value: 'R$10' },
                  { id: 'lavagem', label: 'Lavagem', value: 'R$40' },
                  { id: 'almofada', label: 'Almofada', value: 'R$10' },
                  { id: 'pes_guarda_roupa', label: 'Pés G-R', value: 'R$7' },
                  { id: 'impermeabilizacao_bonus', label: 'Impermeab.', value: 'R$40' }
                ].map((item) => (
                  <button
                    key={item.id}
                    type="button"
                    onClick={() => toggleExtra(item.id as keyof typeof extras)}
                    className={`flex items-center justify-between p-4 rounded-xl border transition-all ${
                      extras[item.id as keyof typeof extras]
                      ? 'bg-emerald-500/10 border-emerald-500/40 text-emerald-400'
                      : 'bg-white/5 border-white/5 text-slate-500 hover:border-white/20'
                    }`}
                  >
                    <div className="flex flex-col items-start text-left">
                      <span className="text-[10px] font-bold uppercase tracking-tighter leading-none mb-1">{item.label}</span>
                      <span className="text-[8px] mono opacity-60 font-black">{item.value}</span>
                    </div>
                    {extras[item.id as keyof typeof extras] ? <CheckSquare size={14} /> : <Square size={14} />}
                  </button>
                ))}
              </div>
            </div>

            <div className="md:col-span-2">
              <div className="p-[1px] rounded-3xl bg-gradient-to-r from-cyan-500 via-violet-600 to-emerald-500 shadow-2xl">
                <div className="bg-[#0a051a] rounded-[1.8rem] p-8 flex flex-col md:flex-row items-center justify-between gap-10">
                  <div className="flex flex-col items-center md:items-start">
                    <span className="text-[10px] font-black uppercase tracking-[0.4em] text-slate-400 mb-1">Faturamento do Pedido</span>
                    <div className="text-3xl md:text-4xl font-black text-white mono leading-none">{formatCurrency(total)}</div>
                  </div>

                  <div className="flex flex-col items-center md:items-end gap-2 border-l border-white/10 pl-10">
