          <button onClick={() => setIsFabOpen(!isFabOpen)} className={`w-20 h-20 rounded-[2.5rem] flex items-center justify-center shadow-2xl transition-all duration-500 animate-pulse-neon floating-action ${isFabOpen ? 'bg-rose-500 rotate-45 text-white' : 'bg-cyan-500 text-black rotate-0 shadow-[0_0_30px_rgba(34,211,238,0.3)]'}`}>
            {isFabOpen ? <X size={32} /> : <Plus size={32} />}
