  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  const mainRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const rawData = localStorage.getItem(STORAGE_KEY);
    if (rawData) {
      try { setSavedSales(JSON.parse(rawData)); } catch (e) {}
    }

    const rawTargets = localStorage.getItem(TARGETS_KEY);
    if (rawTargets) {
      try { setTargets(JSON.parse(rawTargets)); } catch (e) {}
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(savedSales));
  }, [savedSales]);

  useEffect(() => {
    localStorage.setItem(TARGETS_KEY, JSON.stringify(targets));
  }, [targets]);

  const saveSale = (newSaleData: any) => {
    const saleObj: Sale = {
      numeroPedido: newSaleData.pedido,
      valorProduto: newSaleData.produto,
      valorAssistencia: newSaleData.assistencia,
      valorImpermeabilizacao: newSaleData.impermeabilizacao,
      total: newSaleData.total,
      bonusTotal: newSaleData.bonusTotal,
      comissaoProduto: newSaleData.comissaoProduto,
      servicosExtras: newSaleData.servicosExtras,
      data: new Date().toLocaleDateString('pt-BR'),
      timestamp: Date.now()
    };
    setSavedSales(prev => [saleObj, ...prev]);
    setActiveNav(NavItem.ResumoPedido);
  };

  const formatBRL = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const filteredSales = useMemo(() => {
    return savedSales.filter(sale => {
      if (!startDate && !endDate) return true;
      const saleDate = new Date(sale.timestamp || 0);
      saleDate.setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate + 'T00:00:00') : null;
      const end = endDate ? new Date(endDate + 'T23:59:59') : null;
      return !( (start && saleDate < start) || (end && saleDate > end) );
    });
  }, [savedSales, startDate, endDate]);

  const shareToWhatsApp = (sale: Sale) => {
    const message = `🚀 *RELATÓRIO DE PEDIDO V&C*
--------------------------------
📦 *Pedido:* #${sale.numeroPedido}
📅 *Data:* ${sale.data}

💰 *Valor Produto:* ${formatBRL(sale.valorProduto)}
🛠️ *Serviços:* ${sale.servicosExtras.length > 0 ? sale.servicosExtras.join(', ') : 'Nenhum'}
🛡️ *Assistência:* ${formatBRL(sale.valorAssistencia)}
💧 *Impermeab.:* ${formatBRL(sale.valorImpermeabilizacao)}

--------------------------------
✅ *TOTAL GANHOS: ${formatBRL(sale.bonusTotal)}*
--------------------------------
_Gerado via V&C Quantum Hub_`;

    const encodedMessage = encodeURIComponent(message);
    window.open(`https://wa.me/?text=${encodedMessage}`, '_blank');
  };

  const stats = useMemo(() => {
    const pTotal = filteredSales.reduce((acc, s) => acc + s.valorProduto, 0);
    const aTotal = filteredSales.reduce((acc, s) => acc + s.valorAssistencia, 0);
    const iTotal = filteredSales.reduce((acc, s) => acc + s.valorImpermeabilizacao, 0);

    const pPerc = targets.product > 0 ? (pTotal / targets.product) : 0;
    const aPerc = targets.assistance > 0 ? (aTotal / targets.assistance) : 0;
    const iPerc = targets.waterproofing > 0 ? (iTotal / targets.waterproofing) : 0;

    const aRate = aPerc >= 1 ? 0.10 : 0.05;
    const aComissao = aTotal * aRate;
    const pComissaoBase = pTotal * 0.022;

    let level = 0;
    [3, 2, 1].forEach(lvlNum => {
      if (level > 0) return;
      const lNum = lvlNum as 1 | 2 | 3;
      const thresh = targets.levels[lNum].threshold / 100;
      if (pPerc >= thresh && aPerc >= thresh && iPerc >= thresh) level = lNum;
    });

    const accelRate = level > 0 ? targets.levels[level as 1|2|3].rate / 100 : 0;
    const accelBonus = pTotal * accelRate;

    const serviceCounts = { 'Montagem': 0, 'Lavagem': 0, 'Almofada': 0, 'Pés G-Roupa': 0, 'Impermeab.': 0 };
    const serviceValues = { 'Montagem': 10, 'Lavagem': 40, 'Almofada': 10, 'Pés G-Roupa': 7, 'Impermeab.': 40 };

    filteredSales.forEach(s => {
      s.servicosExtras.forEach(ex => {
        if (serviceCounts.hasOwnProperty(ex)) {
          // @ts-ignore
          serviceCounts[ex]++;
        }
      });
    });

    const totalExtrasFixo = Object.keys(serviceCounts).reduce((acc, key) => {
      // @ts-ignore
      return acc + (serviceCounts[key] * serviceValues[key]);
    }, 0);

    // Fix: Including serviceCounts in the return object to resolve property access errors
    return {
      pTotal, aTotal, iTotal,
      pPerc, aPerc, iPerc,
      aComissao, aRate,
      pComissaoBase,
      accelBonus, accelRate, level,
      totalExtrasFixo,
      serviceCounts,
      ganhosTotais: pComissaoBase + aComissao + accelBonus + totalExtrasFixo,
      faturamentoGeral: pTotal + aTotal + iTotal
    };
  }, [filteredSales, targets]);

  const updateTargetValue = (key: 'product' | 'assistance' | 'waterproofing', val: string) => {
    const numeric = parseFloat(val.replace(/[^\d]/g, '')) / 100;
    setTargets(prev => ({ ...prev, [key]: isNaN(numeric) ? 0 : numeric }));
  };

  const renderContent = () => {
    const filterUI = (
      <div className="glass p-4 rounded-3xl border-white/10 mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-500 uppercase mb-1 ml-1">Filtro de Período</span>
            <div className="flex items-center gap-2">
               <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
               <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
            </div>
          </div>
          {(startDate || endDate) && (
            <button onClick={() => {setStartDate(''); setEndDate('');}} className="mt-4 p-2 text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all active:scale-90"><FilterX size={16} /></button>
          )}
        </div>
        <button onClick={() => setActiveNav(NavItem.AdicionarVenda)} className="bg-cyan-500 text-black px-6 py-3 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 shadow-lg shadow-cyan-500/10 transition-transform active:scale-95"><Plus size={14} /> Novo Pedido</button>
      </div>
    );

    if (activeNav === NavItem.AdicionarVenda) return <SaleForm onCancel={() => setActiveNav(NavItem.Resumos)} onSubmit={saveSale} />;

    // TELA DE EM BREVE PARA CLIENTES E FLUXO
    if (activeNav === NavItem.Clientes || activeNav === NavItem.Processos) {
      return (
        <div className="h-[70vh] flex flex-col items-center justify-center text-center animate-in zoom-in-95 duration-700">
           <div className="relative mb-10">
              <div className="absolute inset-0 bg-cyan-500 blur-[80px] opacity-20 animate-pulse"></div>
              <div className="p-8 bg-white/5 rounded-[2.5rem] border border-white/10 relative z-10 shadow-2xl">
                <Construction size={100} className="text-cyan-400" />
              </div>
           </div>
           <h2 className="text-5xl font-black text-white uppercase tracking-tighter italic mb-4">Módulo em Breve</h2>
           <p className="text-slate-500 font-bold uppercase tracking-[0.4em] max-w-sm mx-auto leading-relaxed">
             Estamos calibrando os sistemas para esta funcionalidade. Fique atento às atualizações.
           </p>
           <button onClick={() => setActiveNav(NavItem.Resumos)} className="mt-12 px-10 py-5 bg-cyan-500 text-black rounded-2xl font-black text-[10px] uppercase tracking-widest hover:scale-105 transition-all shadow-xl shadow-cyan-500/20">Voltar ao Início</button>
        </div>
      );
    }

    // TELA DE RELATÓRIOS (COMPARTILHAMENTO)
    if (activeNav === NavItem.Relatorios) {
      return (
        <div className="content-section py-4 px-2 space-y-12 animate-in slide-in-from-right-10 duration-500">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div>
              <div className="flex items-center gap-2 text-cyan-400 mb-2">
                <FileText size={18} />
                <span className="text-[10px] font-black uppercase tracking-[0.4em]">Central de Relatórios V&C</span>
              </div>
              <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none">Exportar Pedidos</h2>
            </div>
            <div className="bg-emerald-500/10 border border-emerald-500/20 p-4 rounded-2xl flex items-center gap-4">
              <MessageCircle size={20} className="text-emerald-400" />
              <div className="flex flex-col">
                <span className="text-[9px] font-black text-emerald-500 uppercase tracking-widest">Supervisor/Gerente</span>
                <span className="text-[11px] font-bold text-white">Compartilhamento via WhatsApp Ativo</span>
              </div>
            </div>
          </div>

          <div className="glass rounded-[3rem] p-8 border-white/5">
             {filteredSales.length === 0 ? (
               <div className="py-20 flex flex-col items-center justify-center opacity-30">
                  <FileText size={48} className="mb-4" />
                  <p className="font-black uppercase text-xs tracking-widest">Sem pedidos para exportar</p>
               </div>
             ) : (
               <div className="grid grid-cols-1 gap-4">
                 {filteredSales.map((sale, i) => (
                    <div key={i} className="flex flex-col md:flex-row items-center justify-between p-6 bg-white/5 border border-white/5 rounded-2xl gap-6 group hover:border-cyan-500/30 transition-all">
                       <div className="flex items-center gap-6 w-full md:w-auto">
                          <div className="w-12 h-12 rounded-xl bg-white/5 flex items-center justify-center text-white font-black text-xs mono">#{sale.numeroPedido}</div>
                          <div>
                             <div className="text-[10px] font-black text-slate-500 uppercase mb-1">{sale.data}</div>
                             <div className="text-sm font-black text-white mono">{formatBRL(sale.total)}</div>
                          </div>
                       </div>

                       <div className="flex-1 text-[10px] font-bold text-slate-500 uppercase tracking-widest">
                          {sale.servicosExtras.length > 0 ? sale.servicosExtras.join(' • ') : 'Venda Direta'}
                       </div>

                       <button 
                          onClick={() => shareToWhatsApp(sale)}
                          className="w-full md:w-auto flex items-center justify-center gap-3 bg-emerald-500 text-black px-6 py-4 rounded-xl font-black text-[10px] uppercase tracking-widest hover:scale-105 transition-all shadow-lg shadow-emerald-500/20"
                       >
                          <Share2 size={14} /> Enviar p/ Gerente
                       </button>
                    </div>
                 ))}
               </div>
             )}
          </div>
        </div>
      );
    }

    if (activeNav === NavItem.ResumoServico) {
      return (
        <div className="content-section py-4 px-2 space-y-12 animate-in slide-in-from-right-10 duration-500">
           <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
              <div>
                <div className="flex items-center gap-2 text-emerald-400 mb-2">
                  <Wrench size={18} />
                  <span className="text-[10px] font-black uppercase tracking-[0.4em]">Relatório de Serviços Detalhado</span>
                </div>
                <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none">Meus Serviços</h2>
              </div>
              <div className="glass p-8 rounded-[2.5rem] flex flex-col items-end border-emerald-500/20 bg-emerald-500/[0.02]">
                 <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest mb-1">Total Acumulado</span>
                 <span className="text-4xl font-black text-white mono">{formatBRL(stats.totalExtrasFixo)}</span>
              </div>
           </div>

           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {[
                { label: 'Montagem', icon: <Layout />, count: stats.serviceCounts['Montagem'], val: 10, color: 'text-blue-400', bg: 'bg-blue-400/10' },
                { label: 'Lavagem', icon: <Droplets />, count: stats.serviceCounts['Lavagem'], val: 40, color: 'text-cyan-400', bg: 'bg-cyan-400/10' },
                { label: 'Almofada', icon: <Star />, count: stats.serviceCounts['Almofada'], val: 10, color: 'text-amber-400', bg: 'bg-amber-400/10' },
                { label: 'Pés G-Roupa', icon: <Layers />, count: stats.serviceCounts['Pés G-Roupa'], val: 7, color: 'text-fuchsia-400', bg: 'bg-fuchsia-400/10' },
                { label: 'Impermeab.', icon: <ShieldCheck />, count: stats.serviceCounts['Impermeab.'], val: 40, color: 'text-emerald-400', bg: 'bg-emerald-400/10' },
              ].map((s, idx) => (
                <div key={idx} className="glass group p-10 rounded-[3rem] border-white/5 hover:border-white/20 transition-all flex flex-col relative overflow-hidden">
                   <div className={`absolute top-0 right-0 p-8 opacity-5 group-hover:scale-110 transition-transform ${s.color}`}>{s.icon}</div>
                   <div className={`w-14 h-14 rounded-2xl ${s.bg} flex items-center justify-center mb-8 ${s.color}`}>
                      {React.cloneElement(s.icon as React.ReactElement<any>, { size: 28 })}
                   </div>
                   <h4 className="text-[12px] font-black text-white uppercase tracking-widest mb-6">{s.label}</h4>
                   <div className="flex items-end justify-between">
                      <div>
                        <div className="text-5xl font-black text-white mono leading-none">{s.count}</div>
                        <div className="text-[10px] font-bold text-slate-500 uppercase mt-2 tracking-widest">Unidades</div>
                      </div>
                      <div className="text-right">
                         <div className="text-[10px] font-black text-slate-500 uppercase mb-1">Un: {formatBRL(s.val)}</div>
                         <div className={`text-2xl font-black mono ${s.color}`}>{formatBRL(s.count * s.val)}</div>
                      </div>
                   </div>
                </div>
              ))}
           </div>
        </div>
      );
    }

    if (activeNav === NavItem.Meta) {
      return (
        <div className="content-section py-4 px-2 space-y-12 animate-in fade-in zoom-in-95 duration-500">
          <div>
            <div className="flex items-center gap-2 text-cyan-400 mb-2">
              <Target size={18} />
              <span className="text-[10px] font-black uppercase tracking-[0.4em]">Configuração de Gatilhos V&C</span>
            </div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter">Gerenciar Metas</h2>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {[
              { label: 'Meta Produto (100%)', key: 'product' as const, color: 'text-cyan-400', current: stats.pTotal },
              { label: 'Meta Assistência (100%)', key: 'assistance' as const, color: 'text-emerald-400', current: stats.aTotal },
              { label: 'Meta Impermeab. (100%)', key: 'waterproofing' as const, color: 'text-fuchsia-400', current: stats.iTotal },
            ].map((item) => (
              <div key={item.key} className="glass p-8 rounded-[3rem] border-white/5">
                <div className="flex items-center justify-between mb-6">
                  <span className={`text-[10px] font-black uppercase tracking-[0.2em] ${item.color}`}>{item.label}</span>
                  <Settings2 size={16} className="text-slate-600" />
                </div>
                <div className="relative mb-6">
                   <span className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-600 text-xs font-black">R$</span>
                   <input 
                      type="text" 
                      value={new Intl.NumberFormat('pt-BR', { minimumFractionDigits: 2 }).format(targets[item.key])}
                      onChange={(e) => updateTargetValue(item.key, e.target.value)}
                      className="w-full bg-white/5 border border-white/5 pl-12 pr-4 py-5 rounded-2xl text-2xl font-black text-white mono outline-none focus:ring-1 focus:ring-cyan-500/50"
                    />
                </div>
                <div className="flex items-center justify-between text-[11px] font-bold text-slate-500">
                   <span className="uppercase">Realizado:</span>
                   <span className="text-white mono">{formatBRL(item.current)}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      );
    }

    return (
      <div className="content-section py-4 px-2 space-y-8 animate-in slide-in-from-bottom-6 duration-700">
        {filterUI}

        <div className="glass rounded-[3rem] p-8 border-white/5 bg-white/[0.01]">
          <div className="flex items-center justify-between mb-10">
            <div>
              <h3 className="text-xl font-black text-white uppercase tracking-tighter italic flex items-center gap-2">
                <Zap size={20} className="text-cyan-400 fill-cyan-400/20" /> Sincronização Quantum
              </h3>
            </div>
            <div className="flex gap-4">
              {[
                { label: 'Lvl 1', thresh: '100%', active: stats.level >= 1 },
                { label: 'Lvl 2', thresh: '120%', active: stats.level >= 2 },
                { label: 'Lvl 3', thresh: '140%', active: stats.level >= 3 },
              ].map(l => (
                <div key={l.label} className={`px-4 py-2 rounded-xl border text-[9px] font-black uppercase tracking-widest transition-all ${l.active ? 'bg-cyan-500 text-black border-cyan-400' : 'bg-white/5 text-slate-600 border-white/10'}`}>
                  {l.label} • {l.thresh}
                </div>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
            {[
              { label: 'Produto', current: stats.pPerc, color: 'from-cyan-500 to-blue-600' },
              { label: 'Assistência', current: stats.aPerc, color: 'from-emerald-500 to-teal-600' },
              { label: 'Impermeab.', current: stats.iPerc, color: 'from-fuchsia-500 to-purple-600' },
            ].map((cat) => (
              <div key={cat.label} className="space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{cat.label}</span>
                  <span className={`text-[12px] font-black mono ${cat.current >= 1 ? 'text-emerald-400' : 'text-white'}`}>
                    {(cat.current * 100).toFixed(1)}%
                  </span>
                </div>
                <div className="h-4 bg-white/5 rounded-full p-1 border border-white/5 overflow-hidden">
                  <div className={`h-full rounded-full bg-gradient-to-r ${cat.color} transition-all duration-1000`} style={{ width: `${Math.min(cat.current * 100, 140) / 1.4}%` }}></div>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
          <div className="glass p-8 rounded-[3rem] border-white/10">
            <span className="text-[11px] font-black text-cyan-400 uppercase mb-5 block">Faturamento Global</span>
            <h3 className="text-3xl font-black text-white mono tracking-tighter">{formatBRL(stats.faturamentoGeral)}</h3>
          </div>

          <div className="glass p-8 rounded-[3rem] border-cyan-400/30 bg-cyan-400/[0.04] relative group">
            <div className="absolute top-8 right-8 p-1.5 bg-cyan-500/20 rounded-xl text-cyan-400 group-hover:scale-110 transition-transform"><Percent size={18}/></div>
            <span className="text-[11px] font-black text-cyan-400 uppercase mb-5 block">Minha Comissão (2.2%)</span>
            <h3 className="text-3xl font-black text-white mono tracking-tighter">{formatBRL(stats.pComissaoBase)}</h3>
          </div>

          <div className="bg-gradient-to-br from-emerald-600 to-teal-800 p-8 rounded-[3rem] shadow-2xl relative overflow-hidden group">
            <div className="absolute -right-8 -bottom-8 opacity-20 group-hover:scale-125 transition-transform duration-1000"><ShieldCheck size={160} /></div>
            <div className="flex items-center justify-between mb-5 relative z-10">
              <span className="text-[11px] font-black text-white/90 uppercase">Comis. Assistência</span>
              <span className="bg-white/25 px-2.5 py-1 rounded-xl text-[9px] font-black text-white">{(stats.aRate * 100)}%</span>
            </div>
            <h3 className="text-3xl font-black text-white mono tracking-tighter relative z-10">{formatBRL(stats.aComissao)}</h3>
          </div>

          <div className="glass p-8 rounded-[3rem] relative group border-violet-500/20">
            <div className="absolute top-8 right-8 p-1.5 bg-violet-500/20 rounded-xl text-violet-400"><TrendingUp size={18}/></div>
            <span className="text-[11px] font-black text-violet-400 uppercase mb-5 block">Bônus Quantum (LVL {stats.level})</span>
            <h3 className="text-3xl font-black text-white mono tracking-tighter">{formatBRL(stats.accelBonus)}</h3>
          </div>

          <div className="bg-white/5 p-8 rounded-[3rem] border border-cyan-500/30 relative">
            <span className="text-[11px] font-black text-emerald-400 uppercase mb-5 block italic font-extrabold">Ganhos Reais (TOTAL)</span>
            <h3 className="text-4xl font-black text-emerald-400 mono tracking-tighter">{formatBRL(stats.ganhosTotais)}</h3>
          </div>
        </div>

        {activeNav === NavItem.ResumoPedido && (
          <div className="glass rounded-[3.5rem] p-10 md:p-16 bg-[#05020a] mt-12 border-white/10 relative overflow-hidden">
             <div className="flex flex-col md:flex-row md:items-center justify-between mb-16 gap-10 border-b border-white/5 pb-14 relative z-10">
                <div>
                  <h3 className="text-4xl font-black text-white uppercase tracking-tighter mb-3">Extrato de Pedidos</h3>
                  <p className="text-[11px] text-slate-600 font-bold uppercase tracking-[0.4em]">V&C Hub • Gestão Quantum</p>
                </div>
                <div className="text-right border-l border-white/10 pl-12">
                   <div className="text-[11px] font-black text-emerald-400 uppercase mb-2">Ganhos Totais Acumulados</div>
                   <div className="text-3xl font-black text-white mono">{formatBRL(stats.ganhosTotais)}</div>
                </div>
             </div>

             {filteredSales.length === 0 ? (
               <div className="py-32 flex flex-col items-center justify-center text-slate-800 border-2 border-dashed border-white/5 rounded-[3rem]">
                  <History size={72} className="mb-8 opacity-5" />
                  <p className="font-black uppercase text-xs tracking-[0.4em] opacity-40">Nenhum pedido encontrado</p>
               </div>
             ) : (
               <div className="space-y-6">
                  {filteredSales.map((sale, i) => (
                    <div key={i} className="flex flex-col lg:flex-row items-center justify-between p-10 bg-white/5 border border-white/5 rounded-[2.5rem] gap-10 hover:bg-white/[0.08] transition-all group">
                      <div className="flex items-center gap-8 w-full lg:w-1/4">
                         <div className="w-16 h-16 rounded-[1.5rem] bg-white/5 flex items-center justify-center text-cyan-400 group-hover:bg-cyan-500 group-hover:text-black transition-all shadow-xl font-black text-xs mono">#{sale.numeroPedido}</div>
                         <div>
                            <div className="text-xs font-black text-slate-500 uppercase tracking-widest mb-1.5">{sale.data}</div>
                            <div className="text-xl font-black text-white uppercase tracking-tighter">{formatBRL(sale.total)}</div>
                         </div>
                      </div>

                      <div className="flex-1 w-full lg:w-auto flex flex-wrap gap-3">
                         <span className="text-[10px] font-black bg-cyan-400/10 text-cyan-400 border border-cyan-400/20 px-4 py-2 rounded-2xl uppercase tracking-widest flex items-center gap-2">
                           <Percent size={10} /> 2.2%: {formatBRL(sale.comissaoProduto)}
                         </span>
                         {sale.servicosExtras?.map((ex, idx) => (
                           <span key={idx} className="text-[10px] font-black bg-emerald-500/10 text-emerald-500 border border-emerald-500/20 px-4 py-2 rounded-2xl uppercase tracking-widest">{ex}</span>
                         ))}
                      </div>

                      <div className="flex items-center gap-8 w-full lg:w-auto justify-between lg:justify-end">
                         <div className="text-right">
                            <div className="text-[10px] font-black text-emerald-500 uppercase mb-2">Ganhos</div>
                            <div className="text-3xl font-black text-emerald-400 mono">{formatBRL(sale.bonusTotal)}</div>
                         </div>
                         <button 
                            onClick={() => shareToWhatsApp(sale)}
                            className="bg-white/5 p-4 rounded-2xl text-slate-400 hover:bg-emerald-500 hover:text-black transition-all"
                         >
                            <Share2 size={20} />
                         </button>
                      </div>
                    </div>
                  ))}
               </div>
             )}
          </div>
        )}

        {activeNav === NavItem.Resumos && (
          <div className="space-y-12 mt-16">
            <div className="flex items-center gap-4">
               <div className="w-1.5 h-10 bg-cyan-500 rounded-full"></div>
               <div>
                  <h3 className="text-3xl font-black text-white uppercase tracking-tighter leading-none italic">Resumo de Operação</h3>
               </div>
            </div>
            <FunnelChart opportunities={MOCK_OPPORTUNITIES} />
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen flex bg-[#05020a] overflow-hidden">
      <div className={`transition-all duration-500 z-50 flex-shrink-0 ${isSidebarCollapsed ? 'w-24' : 'w-64'}`}>
        <Sidebar isCollapsed={isSidebarCollapsed} setIsCollapsed={setIsSidebarCollapsed} activeItem={activeNav} onSelect={setActiveNav} />
      </div>
      <div className="flex-1 flex flex-col min-w-0 h-screen relative">
        <Header />
        <main className="flex-1 overflow-x-hidden overflow-y-auto content-scroll px-4 md:px-12 py-6">
          <div className="max-w-[1400px] mx-auto w-full">{renderContent()}</div>
        </main>
        <div className="fixed bottom-10 right-10 z-[100]">
          {isFabOpen && (
            <div className="absolute bottom-24 right-0 flex flex-col gap-4 animate-in slide-in-from-bottom-10 fade-in duration-300">
              {NAVIGATION_ITEMS.map((item) => (
                <button key={item.id} onClick={() => { setActiveNav(item.id); setIsFabOpen(false); }} className="flex items-center gap-4 bg-[#0a051a]/98 backdrop-blur-3xl border border-white/10 px-10 py-6 rounded-[2.5rem] text-white hover:bg-cyan-500 hover:text-black transition-all group shadow-2xl">
                  <span className="text-cyan-400 group-hover:text-black transition-colors">{item.icon}</span>
                  <span className="font-black text-[12px] uppercase tracking-[0.4em]">{item.label}</span>
                </button>
              ))}
            </div>
          )}
          <button onClick={() => setIsFabOpen(!isFabOpen)} className={`w-20 h-20 rounded-[2.5rem] flex items-center justify-center shadow-2xl transition-all duration-500 ${isFabOpen ? 'bg-rose-500 rotate-45 text-white' : 'bg-cyan-500 text-black rotate-0 shadow-[0_0_30px_rgba(34,211,238,0.3)]'}`}>
            {isFabOpen ? <X size={32} /> : <Plus size={32} />}
          </button>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import PipelineView from './components/PipelineView';
import FunnelChart from './components/FunnelChart';
import SaleForm from './components/SaleForm';
import { NavItem, Sale, Targets, LevelConfig } from './types';
import { MOCK_OPPORTUNITIES, NAVIGATION_ITEMS } from './constants';
import { 
  Plus, 
  X, 
  History,
  Search,
  FilterX,
  Target,
  TrendingUp,
  Settings2,
  ShieldCheck,
  CheckCircle2,
  Lock,
  Wrench,
  Droplets,
  Layers,
  Layout,
  Star,
  Construction,
  Percent,
  ChevronRight,
  Zap,
  MessageCircle,
  Share2,
  FileText,
  AlertCircle
} from 'lucide-react';

const STORAGE_KEY = 'vc_quantum_data_v2';
const TARGETS_KEY = 'vc_quantum_targets_v4';

const App: React.FC = () => {
  const [activeNav, setActiveNav] = useState<NavItem>(NavItem.Resumos);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isFabOpen, setIsFabOpen] = useState(false);
  const [savedSales, setSavedSales] = useState<Sale[]>([]);

  const [targets, setTargets] = useState<Targets>({
    product: 50000,
    assistance: 3000,
    waterproofing: 2000,
    levels: {
      1: { threshold: 100, rate: 0.6 },
      2: { threshold: 120, rate: 0.8 },
      3: { threshold: 140, rate: 1.1 }
    }
  });

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  useEffect(() => {
    const rawData = localStorage.getItem(STORAGE_KEY);
    if (rawData) {
      try { setSavedSales(JSON.parse(rawData)); } catch (e) {}
    }

    const rawTargets = localStorage.getItem(TARGETS_KEY);
    if (rawTargets) {
      try { setTargets(JSON.parse(rawTargets)); } catch (e) {}
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(savedSales));
  }, [savedSales]);

  useEffect(() => {
    localStorage.setItem(TARGETS_KEY, JSON.stringify(targets));
  }, [targets]);

  const saveSale = (newSaleData: any) => {
    const saleObj: Sale = {
      numeroPedido: newSaleData.pedido,
      valorProduto: newSaleData.produto,
      valorAssistencia: newSaleData.assistencia,
      valorImpermeabilizacao: newSaleData.impermeabilizacao,
      total: newSaleData.total,
      bonusTotal: newSaleData.bonusTotal,
      comissaoProduto: newSaleData.comissaoProduto,
      servicosExtras: newSaleData.servicosExtras,
      data: new Date().toLocaleDateString('pt-BR'),
      timestamp: Date.now()
    };
    setSavedSales(prev => [saleObj, ...prev]);
    setActiveNav(NavItem.ResumoPedido);
  };

  const formatBRL = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const filteredSales = useMemo(() => {
    return savedSales.filter(sale => {
      if (!startDate && !endDate) return true;
      const saleDate = new Date(sale.timestamp || 0);
      saleDate.setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate + 'T00:00:00') : null;
      const end = endDate ? new Date(endDate + 'T23:59:59') : null;
      return !( (start && saleDate < start) || (end && saleDate > end) );
    });
  }, [savedSales, startDate, endDate]);

  const shareToWhatsApp = (sale: Sale) => {
    const message = `🚀 *RELATÓRIO DE PEDIDO V&C*
--------------------------------
📦 *Pedido:* #${sale.numeroPedido}
📅 *Data:* ${sale.data}

💰 *Valor Produto:* ${formatBRL(sale.valorProduto)}
🛠️ *Serviços:* ${sale.servicosExtras.length > 0 ? sale.servicosExtras.join(', ') : 'Nenhum'}
🛡️ *Assistência:* ${formatBRL(sale.valorAssistencia)}
💧 *Impermeab.:* ${formatBRL(sale.valorImpermeabilizacao)}

--------------------------------
✅ *TOTAL GANHOS: ${formatBRL(sale.bonusTotal)}*
--------------------------------
_Gerado via V&C Quantum Hub_`;

    const encodedMessage = encodeURIComponent(message);
    window.open(`https://wa.me/?text=${encodedMessage}`, '_blank');
  };

  const stats = useMemo(() => {
    const pTotal = filteredSales.reduce((acc, s) => acc + s.valorProduto, 0);
    const aTotal = filteredSales.reduce((acc, s) => acc + s.valorAssistencia, 0);
    const iTotal = filteredSales.reduce((acc, s) => acc + s.valorImpermeabilizacao, 0);

    const pPerc = targets.product > 0 ? (pTotal / targets.product) : 0;
    const aPerc = targets.assistance > 0 ? (aTotal / targets.assistance) : 0;
    const iPerc = targets.waterproofing > 0 ? (iTotal / targets.waterproofing) : 0;

    const aRate = aPerc >= 1 ? 0.10 : 0.05;
    const aComissao = aTotal * aRate;
    const pComissaoBase = pTotal * 0.022;

    let level = 0;
    [3, 2, 1].forEach(lvlNum => {
      if (level > 0) return;
      const lNum = lvlNum as 1 | 2 | 3;
      const thresh = targets.levels[lNum].threshold / 100;
      if (pPerc >= thresh && aPerc >= thresh && iPerc >= thresh) level = lNum;
    });

    const accelRate = level > 0 ? targets.levels[level as 1|2|3].rate / 100 : 0;
    const accelBonus = pTotal * accelRate;

    const serviceCounts = { 'Montagem': 0, 'Lavagem': 0, 'Almofada': 0, 'Pés G-Roupa': 0, 'Impermeab.': 0 };
    const serviceValues = { 'Montagem': 10, 'Lavagem': 40, 'Almofada': 10, 'Pés G-Roupa': 7, 'Impermeab.': 40 };

    filteredSales.forEach(s => {
      s.servicosExtras.forEach(ex => {
        if (serviceCounts.hasOwnProperty(ex)) {
          // @ts-ignore
          serviceCounts[ex]++;
        }
      });
    });

    const totalExtrasFixo = Object.keys(serviceCounts).reduce((acc, key) => {
      // @ts-ignore
      return acc + (serviceCounts[key] * serviceValues[key]);
    }, 0);

    return {
      pTotal, aTotal, iTotal,
      pPerc, aPerc, iPerc,
      aComissao, aRate,
      pComissaoBase,
      accelBonus, accelRate, level,
      totalExtrasFixo,
      serviceCounts,
      ganhosTotais: pComissaoBase + aComissao + accelBonus + totalExtrasFixo,
      faturamentoGeral: pTotal + aTotal + iTotal
    };
  }, [filteredSales, targets]);

  const updateTargetValue = (key: 'product' | 'assistance' | 'waterproofing', val: string) => {
    const numeric = parseFloat(val.replace(/[^\d]/g, '')) / 100;
    setTargets(prev => ({ ...prev, [key]: isNaN(numeric) ? 0 : numeric }));
  };

  const renderContent = () => {
    if (activeNav === NavItem.AdicionarVenda) return <SaleForm onCancel={() => setActiveNav(NavItem.Resumos)} onSubmit={saveSale} />;

    // TELA EM BREVE - CLIENTES E FLUXO
    if (activeNav === NavItem.Clientes || activeNav === NavItem.Processos) {
      return (
        <div className="h-[75vh] flex flex-col items-center justify-center text-center animate-in zoom-in-95 duration-700">
           <div className="relative mb-12">
              <div className="absolute inset-0 bg-cyan-500 blur-[100px] opacity-20 animate-pulse"></div>
              <div className="p-12 bg-white/5 rounded-[3.5rem] border border-white/10 relative z-10 shadow-2xl">
                <Construction size={120} className="text-cyan-400" />
              </div>
           </div>
           <h2 className="text-6xl font-black text-white uppercase tracking-tighter italic mb-6">Módulo em Breve</h2>
           <p className="text-slate-500 font-bold uppercase tracking-[0.5em] max-w-lg mx-auto leading-relaxed">
             Estamos preparando atualizações incríveis para você. Este botão voltará a funcionar no próximo ciclo.
           </p>
           <button onClick={() => setActiveNav(NavItem.Resumos)} className="mt-12 px-14 py-6 bg-white/5 text-white border border-white/10 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-cyan-500 hover:text-black transition-all">Voltar ao Painel</button>
        </div>
      );
    }

    // RELATÓRIOS ATIVOS - WHATSAPP
    if (activeNav === NavItem.Relatorios) {
      return (
        <div className="content-section py-4 px-2 space-y-12 animate-in slide-in-from-right-10 duration-500">
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div>
              <div className="flex items-center gap-2 text-emerald-400 mb-2">
                <MessageCircle size={18} />
                <span className="text-[10px] font-black uppercase tracking-[0.4em]">Central de Conferência</span>
              </div>
              <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none">Exportar p/ Supervisor</h2>
            </div>
          </div>

          <div className="grid grid-cols-1 gap-4">
             {filteredSales.length === 0 ? (
               <div className="py-32 flex flex-col items-center justify-center glass rounded-[3rem] opacity-30 border-2 border-dashed border-white/5">
                  <FileText size={64} className="mb-6" />
                  <p className="font-black uppercase text-xs tracking-[0.4em]">Nenhum pedido para enviar</p>
               </div>
             ) : (
               filteredSales.map((sale, i) => (
                  <div key={i} className="glass group p-8 rounded-[2.5rem] border-white/5 flex flex-col md:flex-row items-center justify-between gap-8 hover:border-emerald-500/30 transition-all">
                     <div className="flex items-center gap-8 w-full md:w-1/3">
                        <div className="w-16 h-16 rounded-2xl bg-white/5 flex items-center justify-center text-white mono font-black text-lg">#{sale.numeroPedido}</div>
                        <div>
                           <div className="text-xs font-black text-slate-500 uppercase mb-1">{sale.data}</div>
                           <div className="text-2xl font-black text-white mono">{formatBRL(sale.total)}</div>
                        </div>
                     </div>

                     <div className="flex-1 flex flex-wrap gap-2 justify-center md:justify-start">
                        {sale.servicosExtras.map((s, idx) => (
                          <span key={idx} className="px-3 py-1.5 bg-white/5 rounded-lg text-[9px] font-black text-slate-400 uppercase tracking-widest border border-white/5">{s}</span>
                        ))}
                        {sale.valorAssistencia > 0 && <span className="px-3 py-1.5 bg-blue-500/10 rounded-lg text-[9px] font-black text-blue-400 uppercase border border-blue-500/20">Assis.</span>}
                        {sale.valorImpermeabilizacao > 0 && <span className="px-3 py-1.5 bg-fuchsia-500/10 rounded-lg text-[9px] font-black text-fuchsia-400 uppercase border border-fuchsia-500/20">Imper.</span>}
                     </div>

                     <button 
                        onClick={() => shareToWhatsApp(sale)}
                        className="w-full md:w-auto flex items-center justify-center gap-4 bg-emerald-500 text-black px-8 py-5 rounded-2xl font-black text-[11px] uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-xl shadow-emerald-500/20"
                     >
                        <Share2 size={16} /> Enviar p/ WhatsApp
                     </button>
                  </div>
               ))
             )}
          </div>
        </div>
      );
    }

    const filterUI = (
      <div className="glass p-4 rounded-3xl border-white/10 mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-500 uppercase mb-1 ml-1">Período Selecionado</span>
            <div className="flex items-center gap-2">
               <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
               <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
            </div>
          </div>
          {(startDate || endDate) && <button onClick={() => {setStartDate(''); setEndDate('');}} className="mt-4 p-2 text-rose-500"><FilterX size={16} /></button>}
        </div>
        <button onClick={() => setActiveNav(NavItem.AdicionarVenda)} className="bg-cyan-500 text-black px-6 py-3 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 shadow-lg transition-all active:scale-95"><Plus size={14} /> Novo Pedido</button>
      </div>
    );

    return (
      <div className="content-section py-4 px-2 space-y-8 animate-in slide-in-from-bottom-6 duration-700">
        {filterUI}

        {/* METAS QUANTUM - Nível 2 e 3 com marcadores claros */}
        <div className="glass rounded-[3.5rem] p-10 border-white/5 bg-white/[0.01] relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-cyan-500 opacity-5 blur-[100px] -mr-32 -mt-32"></div>

          <div className="flex items-center justify-between mb-12 relative z-10">
            <div>
              <h3 className="text-2xl font-black text-white uppercase tracking-tighter italic flex items-center gap-3">
                <Zap size={24} className="text-cyan-400" /> Sincronização Metas Nível 1/2/3
              </h3>
              <p className="text-[10px] text-slate-500 font-bold uppercase tracking-[0.3em] mt-2">As 3 barras devem atingir a marca para subir o bônus</p>
            </div>
            <div className="flex gap-4">
               {[
                 { l: 'Lvl 1', t: '100%', active: stats.level >= 1, color: 'text-cyan-400' },
                 { l: 'Lvl 2', t: '120%', active: stats.level >= 2, color: 'text-amber-400' },
                 { l: 'Lvl 3', t: '140%', active: stats.level >= 3, color: 'text-rose-400' },
               ].map(lvl => (
                 <div key={lvl.l} className={`px-6 py-3 rounded-2xl border text-[10px] font-black uppercase transition-all ${lvl.active ? 'bg-white/10 border-white/20 text-white' : 'bg-transparent border-white/5 text-slate-700'}`}>
                    <span className={lvl.active ? lvl.color : ''}>{lvl.l}</span> • {lvl.t}
                 </div>
               ))}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-12 relative z-10">
            {[
              { label: 'Produto', cur: stats.pPerc, color: 'from-cyan-500 to-blue-500' },
              { label: 'Assistência', cur: stats.aPerc, color: 'from-emerald-500 to-teal-500' },
              { label: 'Impermeab.', cur: stats.iPerc, color: 'from-fuchsia-500 to-violet-500' },
            ].map((bar) => (
              <div key={bar.label} className="space-y-6">
                <div className="flex items-center justify-between">
                  <span className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400">{bar.label}</span>
                  <span className="text-sm font-black text-white mono">{(bar.cur * 100).toFixed(1)}%</span>
                </div>
                <div className="h-6 bg-white/5 rounded-full p-1 relative border border-white/10 group">
                  <div className={`h-full rounded-full bg-gradient-to-r ${bar.color} transition-all duration-1000`} style={{ width: `${Math.min(bar.cur * 100, 140) / 1.4}%` }}></div>

                  {/* MARCADORES DE NÍVEL 1, 2 e 3 */}
                  <div className="absolute left-[71.4%] top-0 h-full w-[2px] bg-white/30 z-20 group-hover:bg-cyan-400 transition-colors">
                     <span className="absolute -top-6 left-1/2 -translate-x-1/2 text-[8px] font-black text-slate-500">100%</span>
                  </div>
                  <div className="absolute left-[85.7%] top-0 h-full w-[2px] bg-white/30 z-20 group-hover:bg-amber-400 transition-colors">
                     <span className="absolute -top-6 left-1/2 -translate-x-1/2 text-[8px] font-black text-slate-500">120%</span>
                  </div>
                  <div className="absolute left-[100%] top-0 h-full w-[2px] bg-white/30 z-20 group-hover:bg-rose-400 transition-colors">
                     <span className="absolute -top-6 left-1/2 -translate-x-1/2 text-[8px] font-black text-slate-500">140%</span>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* CARDS DE CATEGORIAS (Para não sumir!) */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
          <div className="glass p-6 rounded-[2rem] border-white/10">
            <span className="text-[10px] font-black text-slate-500 uppercase mb-3 block">Faturamento Global</span>
            <h3 className="text-xl font-black text-white mono">{formatBRL(stats.faturamentoGeral)}</h3>
          </div>
          <div className="glass p-6 rounded-[2rem] border-cyan-500/20 bg-cyan-500/[0.02]">
            <span className="text-[10px] font-black text-cyan-400 uppercase mb-3 block italic">Comissão 2.2%</span>
            <h3 className="text-xl font-black text-white mono">{formatBRL(stats.pComissaoBase)}</h3>
          </div>
          {/* CARD DE ASSISTÊNCIA EXPLICITO */}
          <div className="glass p-6 rounded-[2rem] border-emerald-500/20">
            <span className="text-[10px] font-black text-emerald-400 uppercase mb-3 block italic">Total Assistência</span>
            <h3 className="text-xl font-black text-white mono">{formatBRL(stats.aTotal)}</h3>
          </div>
          {/* CARD DE IMPERMEABILIZAÇÃO EXPLICITO */}
          <div className="glass p-6 rounded-[2rem] border-fuchsia-500/20">
            <span className="text-[10px] font-black text-fuchsia-400 uppercase mb-3 block italic">Total Impermeab.</span>
            <h3 className="text-xl font-black text-white mono">{formatBRL(stats.iTotal)}</h3>
          </div>
          <div className="glass p-6 rounded-[2rem] border-violet-500/20">
            <span className="text-[10px] font-black text-violet-400 uppercase mb-3 block italic">Bônus Nível {stats.level}</span>
            <h3 className="text-xl font-black text-white mono">{formatBRL(stats.accelBonus)}</h3>
          </div>
          <div className="bg-white/5 border border-cyan-500/30 p-6 rounded-[2rem]">
            <span className="text-[10px] font-black text-emerald-400 uppercase mb-3 block font-extrabold tracking-widest">Meus Ganhos</span>
            <h3 className="text-2xl font-black text-emerald-400 mono leading-none">{formatBRL(stats.ganhosTotais)}</h3>
          </div>
        </div>

        {activeNav === NavItem.ResumoPedido && (
          <div className="glass rounded-[3.5rem] p-10 bg-[#05020a] mt-12 border-white/10">
             <div className="flex items-center justify-between mb-12 border-b border-white/5 pb-10">
                <h3 className="text-3xl font-black text-white uppercase tracking-tighter">Histórico de Vendas</h3>
                <div className="text-right">
                   <span className="text-[10px] font-black text-slate-500 uppercase block mb-1">Total no período</span>
                   <div className="text-2xl font-black text-emerald-400 mono">{formatBRL(stats.ganhosTotais)}</div>
