             </div>

             <div className="space-y-4">
                {filteredSales.map((sale, i) => (
                  <div key={i} className="flex flex-col lg:flex-row items-center justify-between p-8 bg-white/5 border border-white/5 rounded-2xl gap-8 group">
                    <div className="flex items-center gap-6 w-full lg:w-1/4">
