import React, { useState, useRef, useEffect, useMemo } from 'react';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import PipelineView from './components/PipelineView';
import FunnelChart from './components/FunnelChart';
import SaleForm from './components/SaleForm';
import { NavItem, Sale, Targets, LevelConfig } from './types';
import { MOCK_OPPORTUNITIES, NAVIGATION_ITEMS } from './constants';
import { 
  Plus, 
  X, 
  History,
  Search,
  FilterX,
  Target,
  TrendingUp,
  Settings2,
  ShieldCheck,
  CheckCircle2,
  Lock,
  Wrench,
  Droplets,
  Layers,
  Layout,
  Star,
  Construction,
  Percent,
  ChevronRight,
  Zap,
  MessageCircle,
  Share2,
  FileText
} from 'lucide-react';

const STORAGE_KEY = 'vc_quantum_data_v2';
const TARGETS_KEY = 'vc_quantum_targets_v4';

const App: React.FC = () => {
  const [activeNav, setActiveNav] = useState<NavItem>(NavItem.Resumos);
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [isFabOpen, setIsFabOpen] = useState(false);
  const [savedSales, setSavedSales] = useState<Sale[]>([]);

  const [targets, setTargets] = useState<Targets>({
    product: 50000,
    assistance: 3000,
    waterproofing: 2000,
    levels: {
      1: { threshold: 100, rate: 0.6 },
      2: { threshold: 120, rate: 0.8 },
      3: { threshold: 140, rate: 1.1 }
    }
  });

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>('');

  useEffect(() => {
    const rawData = localStorage.getItem(STORAGE_KEY);
    if (rawData) {
      try { setSavedSales(JSON.parse(rawData)); } catch (e) {}
    }

    const rawTargets = localStorage.getItem(TARGETS_KEY);
    if (rawTargets) {
      try { setTargets(JSON.parse(rawTargets)); } catch (e) {}
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(savedSales));
  }, [savedSales]);

  useEffect(() => {
    localStorage.setItem(TARGETS_KEY, JSON.stringify(targets));
  }, [targets]);

  const saveSale = (newSaleData: any) => {
    const saleObj: Sale = {
      numeroPedido: newSaleData.pedido,
      valorProduto: newSaleData.produto,
      valorAssistencia: newSaleData.assistencia,
      valorImpermeabilizacao: newSaleData.impermeabilizacao,
      total: newSaleData.total,
      bonusTotal: newSaleData.bonusTotal,
      comissaoProduto: newSaleData.comissaoProduto,
      servicosExtras: newSaleData.servicosExtras,
      data: new Date().toLocaleDateString('pt-BR'),
      timestamp: Date.now()
    };
    setSavedSales(prev => [saleObj, ...prev]);
    setActiveNav(NavItem.ResumoPedido);
  };

  const formatBRL = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const filteredSales = useMemo(() => {
    return savedSales.filter(sale => {
      if (!startDate && !endDate) return true;
      const saleDate = new Date(sale.timestamp || 0);
      saleDate.setHours(0, 0, 0, 0);
      const start = startDate ? new Date(startDate + 'T00:00:00') : null;
      const end = endDate ? new Date(endDate + 'T23:59:59') : null;
      return !( (start && saleDate < start) || (end && saleDate > end) );
    });
  }, [savedSales, startDate, endDate]);

  const shareToWhatsApp = (sale: Sale) => {
    const message = `🚀 *RELATÓRIO DE PEDIDO V&C*
--------------------------------
📦 *Pedido:* #${sale.numeroPedido}
📅 *Data:* ${sale.data}

💰 *Valor Venda:* ${formatBRL(sale.total)}
🛠️ *Serviços:* ${sale.servicosExtras.length > 0 ? sale.servicosExtras.join(', ') : 'Venda Direta'}
🛡️ *Assistência:* ${formatBRL(sale.valorAssistencia)}
💧 *Impermeab.:* ${formatBRL(sale.valorImpermeabilizacao)}

--------------------------------
✅ *GANHO REAL: ${formatBRL(sale.bonusTotal)}*
--------------------------------
_Enviado via V&C Quantum Hub_`;

    const encodedMessage = encodeURIComponent(message);
    window.open(`https://wa.me/?text=${encodedMessage}`, '_blank');
  };

  const stats = useMemo(() => {
    const pTotal = filteredSales.reduce((acc, s) => acc + s.valorProduto, 0);
    const aTotal = filteredSales.reduce((acc, s) => acc + s.valorAssistencia, 0);
    const iTotal = filteredSales.reduce((acc, s) => acc + s.valorImpermeabilizacao, 0);

    const pPerc = targets.product > 0 ? (pTotal / targets.product) : 0;
    const aPerc = targets.assistance > 0 ? (aTotal / targets.assistance) : 0;
    const iPerc = targets.waterproofing > 0 ? (iTotal / targets.waterproofing) : 0;

    const aRate = aPerc >= 1 ? 0.10 : 0.05;
    const aComissao = aTotal * aRate;
    const pComissaoBase = pTotal * 0.022;

    let level = 0;
    [3, 2, 1].forEach(lvlNum => {
      if (level > 0) return;
      const lNum = lvlNum as 1 | 2 | 3;
      const thresh = targets.levels[lNum].threshold / 100;
      if (pPerc >= thresh && aPerc >= thresh && iPerc >= thresh) level = lNum;
    });

    const accelRate = level > 0 ? targets.levels[level as 1|2|3].rate / 100 : 0;
    const accelBonus = pTotal * accelRate;

    const serviceCounts = { 'Montagem': 0, 'Lavagem': 0, 'Almofada': 0, 'Pés G-Roupa': 0, 'Impermeab.': 0 };
    const serviceValues = { 'Montagem': 10, 'Lavagem': 40, 'Almofada': 10, 'Pés G-Roupa': 7, 'Impermeab.': 40 };

    filteredSales.forEach(s => {
      s.servicosExtras.forEach(ex => {
        if (serviceCounts.hasOwnProperty(ex)) {
          // @ts-ignore
          serviceCounts[ex]++;
        }
      });
    });

    const totalExtrasFixo = Object.keys(serviceCounts).reduce((acc, key) => {
      // @ts-ignore
      return acc + (serviceCounts[key] * serviceValues[key]);
    }, 0);

    return {
      pTotal, aTotal, iTotal,
      pPerc, aPerc, iPerc,
      aComissao, aRate,
      pComissaoBase,
      accelBonus, accelRate, level,
      totalExtrasFixo,
      serviceCounts,
      ganhosTotais: pComissaoBase + aComissao + accelBonus + totalExtrasFixo,
      faturamentoGeral: pTotal + aTotal + iTotal
    };
  }, [filteredSales, targets]);

  const updateTargetValue = (key: 'product' | 'assistance' | 'waterproofing', val: string) => {
    const numeric = parseFloat(val.replace(/[^\d]/g, '')) / 100;
    setTargets(prev => ({ ...prev, [key]: isNaN(numeric) ? 0 : numeric }));
  };

  const renderContent = () => {
    if (activeNav === NavItem.AdicionarVenda) return <SaleForm onCancel={() => setActiveNav(NavItem.Resumos)} onSubmit={saveSale} />;

    // TELA DE EM BREVE PARA CLIENTES E FLUXO
    if (activeNav === NavItem.Clientes || activeNav === NavItem.Processos) {
      return (
        <div className="h-[70vh] flex flex-col items-center justify-center text-center animate-in zoom-in-95 duration-700">
           <div className="relative mb-10">
              <div className="absolute inset-0 bg-cyan-500 blur-[80px] opacity-20 animate-pulse"></div>
              <div className="p-10 bg-white/5 rounded-[3rem] border border-white/10 relative z-10">
                <Construction size={100} className="text-cyan-400" />
              </div>
           </div>
           <h2 className="text-5xl font-black text-white uppercase tracking-tighter italic mb-4">Módulo em Breve</h2>
           <p className="text-slate-500 font-bold uppercase tracking-[0.4em] max-w-sm mx-auto leading-relaxed">
             Estamos preparando atualizações incríveis para estas funções. Aguarde as próximas versões.
           </p>
           <button onClick={() => setActiveNav(NavItem.Resumos)} className="mt-12 px-10 py-5 bg-cyan-500 text-black rounded-2xl font-black text-[10px] uppercase tracking-widest hover:scale-105 transition-all">Voltar ao Painel</button>
        </div>
      );
    }

    // TELA DE RELATÓRIOS (PARA WHATSAPP)
    if (activeNav === NavItem.Relatorios) {
      return (
        <div className="content-section py-4 px-2 space-y-12 animate-in slide-in-from-right-10 duration-500">
          <div>
            <div className="flex items-center gap-2 text-emerald-400 mb-2">
              <MessageCircle size={18} />
              <span className="text-[10px] font-black uppercase tracking-[0.4em]">Central de Relatórios</span>
            </div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none italic">Exportar Pedidos</h2>
          </div>

          <div className="grid grid-cols-1 gap-4">
             {filteredSales.length === 0 ? (
               <div className="py-24 flex flex-col items-center justify-center glass rounded-[3rem] border-2 border-dashed border-white/5">
                  <FileText size={48} className="text-slate-800 mb-4" />
                  <p className="text-slate-600 font-black uppercase text-xs tracking-widest">Sem pedidos no período</p>
               </div>
             ) : (
               filteredSales.map((sale, i) => (
                  <div key={i} className="glass p-8 rounded-[2.5rem] border-white/5 flex flex-col md:flex-row items-center justify-between gap-8 group hover:border-emerald-500/30 transition-all">
                     <div className="flex items-center gap-6 w-full md:w-1/3">
                        <div className="w-14 h-14 rounded-xl bg-white/5 flex items-center justify-center text-white font-black text-sm mono">#{sale.numeroPedido}</div>
                        <div>
                           <div className="text-[10px] font-black text-slate-500 uppercase mb-1">{sale.data}</div>
                           <div className="text-xl font-black text-white mono">{formatBRL(sale.total)}</div>
                        </div>
                     </div>
                     <div className="flex-1 flex flex-wrap gap-2 justify-center">
                        {sale.servicosExtras.map((s, idx) => (
                          <span key={idx} className="px-3 py-1 bg-white/5 rounded-lg text-[8px] font-black text-slate-400 uppercase tracking-widest border border-white/5">{s}</span>
                        ))}
                     </div>
                     <button 
                        onClick={() => shareToWhatsApp(sale)}
                        className="w-full md:w-auto bg-emerald-500 text-black px-8 py-5 rounded-2xl font-black text-[11px] uppercase tracking-widest flex items-center justify-center gap-3 hover:scale-105 active:scale-95 transition-all shadow-xl shadow-emerald-500/20"
                     >
                        <Share2 size={16} /> Enviar p/ Gerente
                     </button>
                  </div>
               ))
             )}
          </div>
        </div>
      );
    }

    const filterUI = (
      <div className="glass p-4 rounded-3xl border-white/10 mb-6 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="flex flex-col">
            <span className="text-[8px] font-black text-slate-500 uppercase mb-1 ml-1">Filtro de Período</span>
            <div className="flex items-center gap-2">
               <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
               <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-white/5 border border-white/10 rounded-xl p-2 text-[10px] text-white outline-none [color-scheme:dark]" />
            </div>
          </div>
          {(startDate || endDate) && <button onClick={() => {setStartDate(''); setEndDate('');}} className="mt-4 p-2 text-rose-500"><FilterX size={16} /></button>}
        </div>
        <button onClick={() => setActiveNav(NavItem.AdicionarVenda)} className="bg-cyan-500 text-black px-6 py-3 rounded-2xl font-black text-[10px] uppercase flex items-center gap-2 shadow-lg transition-all active:scale-95"><Plus size={14} /> Novo Pedido</button>
      </div>
    );

    return (
      <div className="content-section py-4 px-2 space-y-8 animate-in slide-in-from-bottom-6 duration-700">
        {filterUI}

        {/* METAS COM MARCADORES DE NÍVEL 1/2/3 */}
        <div className="glass rounded-[3rem] p-8 border-white/5 bg-white/[0.01]">
          <div className="flex items-center justify-between mb-10">
            <div>
              <h3 className="text-xl font-black text-white uppercase tracking-tighter italic flex items-center gap-2">
                <Zap size={20} className="text-cyan-400" /> Sincronização Metas Nível 1/2/3
              </h3>
            </div>
            <div className="flex gap-4">
              {[
                { label: 'Lvl 1', thresh: '100%', active: stats.level >= 1 },
                { label: 'Lvl 2', thresh: '120%', active: stats.level >= 2 },
                { label: 'Lvl 3', thresh: '140%', active: stats.level >= 3 },
              ].map(l => (
                <div key={l.label} className={`px-4 py-2 rounded-xl border text-[9px] font-black uppercase tracking-widest transition-all ${l.active ? 'bg-cyan-500 text-black border-cyan-400' : 'bg-white/5 text-slate-600 border-white/10'}`}>
                  {l.label} • {l.thresh}
                </div>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
            {[
              { label: 'Produto', current: stats.pPerc, color: 'from-cyan-500 to-blue-600' },
              { label: 'Assistência', current: stats.aPerc, color: 'from-emerald-500 to-teal-600' },
              { label: 'Impermeab.', current: stats.iPerc, color: 'from-fuchsia-500 to-purple-600' },
            ].map((cat) => (
              <div key={cat.label} className="space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">{cat.label}</span>
                  <span className={`text-[12px] font-black mono ${cat.current >= 1 ? 'text-emerald-400' : 'text-white'}`}>
                    {(cat.current * 100).toFixed(1)}%
                  </span>
                </div>
                <div className="h-5 bg-white/5 rounded-full p-1 border border-white/5 overflow-hidden relative">
                  <div className={`h-full rounded-full bg-gradient-to-r ${cat.color} transition-all duration-1000`} style={{ width: `${Math.min(cat.current * 100, 140) / 1.4}%` }}></div>

                  {/* MARCADORES VISUAIS DE NÍVEL */}
                  <div className="absolute left-[71.4%] top-0 w-px h-full bg-white/20 z-10"></div>
                  <div className="absolute left-[85.7%] top-0 w-px h-full bg-white/20 z-10"></div>
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
          <div className="glass p-8 rounded-[3rem] border-white/10">
            <span className="text-[11px] font-black text-cyan-400 uppercase mb-5 block">Faturamento Global</span>
            <h3 className="text-3xl font-black text-white mono tracking-tighter">{formatBRL(stats.faturamentoGeral)}</h3>
          </div>

          <div className="glass p-8 rounded-[3rem] border-cyan-400/30 bg-cyan-400/[0.04] relative group">
            <div className="absolute top-8 right-8 p-1.5 bg-cyan-500/20 rounded-xl text-cyan-400 group-hover:scale-110 transition-transform"><Percent size={18}/></div>
            <span className="text-[11px] font-black text-cyan-400 uppercase mb-5 block italic">Comissão Produto (2.2%)</span>
            <h3 className="text-3xl font-black text-white mono tracking-tighter">{formatBRL(stats.pComissaoBase)}</h3>
          </div>

          <div className="bg-gradient-to-br from-emerald-600 to-teal-800 p-8 rounded-[3rem] shadow-2xl relative overflow-hidden group">
