            <div className="flex items-center justify-between mb-5 relative z-10">
              <span className="text-[11px] font-black text-white/90 uppercase">Comis. Assistência</span>
              <span className="bg-white/25 px-2.5 py-1 rounded-xl text-[9px] font-black text-white">{(stats.aRate * 100)}%</span>
            </div>
            <h3 className="text-3xl font-black text-white mono tracking-tighter relative z-10">{formatBRL(stats.aComissao)}</h3>
