                   </div>
                </div>
              ))}
           </div>
        )}
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-[#05020a] flex flex-col">
      <div className={`fixed inset-0 z-50 transition-transform duration-500 ${isSidebarCollapsed ? '-translate-x-full' : 'translate-x-0'}`}>
