    window.addEventListener('offline', () => setIsOnline(false));

    // Carregar dados locais inicialmente
    const rawData = localStorage.getItem(STORAGE_KEY);
    if (rawData) {
      try { setSavedSales(JSON.parse(rawData)); } catch (e) {}
    }

    // AQUI você chamaria uma função para baixar os dados do Firebase
    // fetchSalesFromFirebase();
  }, []);

  const saveSale = async (newSaleData: any) => {
    const saleObj: Sale = {
      numeroPedido: newSaleData.pedido,
      valorProduto: newSaleData.produto,
      valorAssistencia: newSaleData.assistencia,
      valorImpermeabilizacao: newSaleData.impermeabilizacao,
      total: newSaleData.total,
      bonusTotal: newSaleData.bonusTotal,
      comissaoProduto: newSaleData.comissaoProduto,
      servicosExtras: newSaleData.servicosExtras,
      data: new Date().toLocaleDateString('pt-BR'),
      timestamp: Date.now()
    };

    const newSales = [saleObj, ...savedSales];
    setSavedSales(newSales);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(newSales));

    // AQUI você salvaria no Firebase se estiver online
    // if (isOnline) { await addDoc(collection(db, "vendas"), saleObj); }

    setActiveNav(NavItem.ResumoPedido);
  };

  const formatBRL = (val: number) => 
    new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);

  const stats = useMemo(() => {
    const pTotal = savedSales.reduce((acc, s) => acc + s.valorProduto, 0);
    const aTotal = savedSales.reduce((acc, s) => acc + s.valorAssistencia, 0);
    const iTotal = savedSales.reduce((acc, s) => acc + s.valorImpermeabilizacao, 0);
    const pPerc = targets.product > 0 ? (pTotal / targets.product) : 0;
    const aPerc = targets.assistance > 0 ? (aTotal / targets.assistance) : 0;
    const iPerc = targets.waterproofing > 0 ? (iTotal / targets.waterproofing) : 0;

    let level = 0;
    [3, 2, 1].forEach(lvlNum => {
      if (level > 0) return;
      const lNum = lvlNum as 1 | 2 | 3;
      const thresh = targets.levels[lNum].threshold / 100;
      if (pPerc >= thresh && aPerc >= thresh && iPerc >= thresh) level = lNum;
    });

    const serviceCounts = { 'Montagem': 0, 'Lavagem': 0, 'Almofada': 0, 'Pés G-Roupa': 0, 'Impermeab.': 0 };
    savedSales.forEach(s => s.servicosExtras.forEach(ex => { if (serviceCounts.hasOwnProperty(ex)) (serviceCounts as any)[ex]++; }));

    const totalExtras = Object.keys(serviceCounts).reduce((acc, k) => acc + ((serviceCounts as any)[k] * (k === 'Lavagem' || k === 'Impermeab.' ? 40 : k === 'Pés G-Roupa' ? 7 : 10)), 0);

    const pComissaoBase = pTotal * 0.022;
    const aComissao = aTotal * (aPerc >= 1 ? 0.10 : 0.05);
    const accelBonus = pTotal * (level > 0 ? targets.levels[level as 1|2|3].rate / 100 : 0);

    return {
      pTotal, aTotal, iTotal, pPerc, aPerc, iPerc, level,
      ganhosTotais: pComissaoBase + aComissao + accelBonus + totalExtras,
      faturamentoGeral: pTotal + aTotal + iTotal
    };
  }, [savedSales]);

  const renderContent = () => {
    if (activeNav === NavItem.AdicionarVenda) return <SaleForm onCancel={() => setActiveNav(NavItem.Resumos)} onSubmit={saveSale} />;

    return (
      <div className="content-section py-2 px-2 space-y-6 animate-in slide-in-from-bottom-6">
        <div className="glass p-5 rounded-[2rem] border-white/10 flex items-center justify-between shadow-2xl">
           <div>
              <h2 className="text-xl font-black text-white italic tracking-tighter uppercase leading-none">V&C Hub</h2>
              <span className="text-[8px] font-black text-cyan-400 tracking-[0.3em] uppercase">Quantum Business</span>
           </div>
           <button onClick={() => setActiveNav(NavItem.AdicionarVenda)} className="bg-cyan-500 text-black px-5 py-3 rounded-xl font-black text-[10px] uppercase shadow-lg shadow-cyan-500/20 active:scale-50 transition-all duration-300">Novo Pedido</button>
        </div>

        {/* Status de Conexão */}
        <div className={`flex items-center gap-2 px-4 py-2 rounded-full w-fit text-[8px] font-black uppercase tracking-widest ${isOnline ? 'bg-emerald-500/10 text-emerald-400' : 'bg-red-500/10 text-red-400'}`}>
           {isOnline ? <Wifi size={10} /> : <WifiOff size={10} />}
           {isOnline ? 'Sincronizado Cloud' : 'Modo Offline'}
        </div>

        <div className="glass rounded-[2rem] p-6 border-white/5 relative overflow-hidden bg-white/[0.01]">
           <div className="flex items-center justify-between mb-6">
              <span className="text-[10px] font-black text-cyan-400 uppercase tracking-widest italic">Nível de Performance: {stats.level}</span>
              <CloudLightning size={18} className="text-cyan-400 animate-pulse" />
           </div>
           <div className="space-y-6">
              {[
                { label: 'Venda Geral', current: stats.pPerc, color: 'from-cyan-500 to-blue-600' },
                { label: 'Assistência', current: stats.aPerc, color: 'from-emerald-500 to-teal-600' },
                { label: 'Impermeab.', current: stats.iPerc, color: 'from-fuchsia-500 to-purple-600' },
              ].map((cat) => (
                <div key={cat.label} className="space-y-2">
                   <div className="flex justify-between text-[10px] font-black uppercase">
                      <span className="text-slate-500">{cat.label}</span>
                      <span className="text-white">{(cat.current * 100).toFixed(1)}%</span>
                   </div>
                   <div className="h-2.5 bg-white/5 rounded-full overflow-hidden p-[1px]">
                      <div className={`h-full bg-gradient-to-r ${cat.color} rounded-full transition-all duration-1000`} style={{ width: `${Math.min(cat.current * 100, 100)}%` }}></div>
                   </div>
                </div>
              ))}
           </div>
        </div>

        <div className="grid grid-cols-2 gap-3">
           <div className="glass p-5 rounded-[1.8rem] border-white/5">
              <span className="text-[8px] font-black text-slate-500 uppercase block mb-1">Faturamento</span>
              <div className="text-md font-black text-white mono">{formatBRL(stats.faturamentoGeral)}</div>
           </div>
           <div className="glass p-5 rounded-[1.8rem] border-emerald-500/20 bg-emerald-500/[0.03]">
              <span className="text-[8px] font-black text-emerald-400 uppercase block mb-1">Comissão Real</span>
              <div className="text-md font-black text-emerald-400 mono">{formatBRL(stats.ganhosTotais)}</div>
           </div>
        </div>

        <div className="space-y-3">
           <h3 className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-2">Últimas Atividades</h3>
           {savedSales.slice(0, 5).map((sale, i) => (
             <div key={i} className="glass p-5 rounded-[1.5rem] border-white/5 flex justify-between items-center bg-white/[0.01]">
                <div className="flex flex-col">
                   <span className="text-[10px] font-black text-white mono">#{sale.numeroPedido}</span>
                   <span className="text-[8px] font-bold text-slate-600 uppercase mt-0.5">{sale.data}</span>
                </div>
                <div className="text-right">
                   <div className="text-[11px] font-black text-emerald-400 mono">{formatBRL(sale.bonusTotal)}</div>
                   <div className="text-[8px] font-bold text-slate-600 uppercase">Bônus</div>
                </div>
             </div>
           ))}
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-[#05020a] flex flex-col selection:bg-cyan-500/30">
      <div className={`fixed inset-0 z-50 transition-transform duration-500 ${isSidebarCollapsed ? '-translate-x-full' : 'translate-x-0'}`}>
         <div className="absolute inset-0 bg-black/80 backdrop-blur-sm" onClick={() => setIsSidebarCollapsed(true)}></div>
         <div className="relative w-64 h-full">
            <Sidebar isCollapsed={false} setIsCollapsed={setIsSidebarCollapsed} activeItem={activeNav} onSelect={(item) => { setActiveNav(item); setIsSidebarCollapsed(true); }} />
         </div>
      </div>

      <header className="h-20 flex items-center justify-between px-6 sticky top-0 z-40 bg-[#05020a]/80 backdrop-blur-md border-b border-white/5">
         <button onClick={() => setIsSidebarCollapsed(false)} className="p-2 text-white active:scale-50 transition-transform duration-200">
            <Zap size={24} className="text-cyan-400" />
         </button>
         <h1 className="text-xl font-black text-white tracking-tighter uppercase italic">V&C <span className="text-cyan-400">HUB</span></h1>
         <div className="w-9 h-9 rounded-xl bg-white/5 border border-white/10 overflow-hidden shadow-inner">
            <img src="https://picsum.photos/seed/vc/100/100" alt="Avatar" className="opacity-80" />
         </div>
      </header>

      <main className="flex-1 overflow-y-auto px-4 pb-32">
        <div className="max-w-md mx-auto">{renderContent()}</div>
      </main>

      {/* BOTÃO FLUTUANTE DIRETO: Ação instantânea + Efeito "Pequenininho" (scale-50) */}
      <div className="fixed bottom-8 right-8 z-40">
         <button 
           onClick={() => setActiveNav(NavItem.AdicionarVenda)} 
           className="w-20 h-20 bg-cyan-500 rounded-[2.2rem] flex items-center justify-center text-black shadow-[0_10px_40px_rgba(34,211,238,0.4)] active:scale-50 transition-all duration-300 transform-gpu hover:shadow-cyan-500/60"
         >
            <Plus size={36} strokeWidth={3} />
         </button>
      </div>
    </div>
  );
};

export default App;
